-- Practice 283: Part 3 (Questions 191 to 283)
-- Table: public.question_explanations

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-191', 'practice_283', 'Công ty cần áp dụng các quy tắc bảo mật cho các phiên bản Amazon EC2 cụ thể. Dịch vụ hoặc tính năng AWS nào cung cấp chức năng này?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'Các Security Group hoạt động như tường lửa cho các phiên bản Amazon EC2 được liên kết, kiểm soát cả lưu lượng truy cập vào và ra ở cấp phiên bản. Bạn có thể sử dụng các Security Group để đặt quy tắc cho phép hoặc từ chối lưu lượng truy cập đến hoặc từ phiên bản của mình. Bạn có thể sửa đổi các quy tắc cho Security Group bất kỳ lúc nào; các quy tắc mới sẽ tự động được áp dụng cho tất cả các phiên bản được liên kết với Security Group.', '[{"label": "A", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "ACL mạng", "is_correct": false, "analysis_vi": "Sai. ACL mạng: Network ACL là tường lửa ở cấp subnet, hoạt động không trạng thái (Stateless) và hỗ trợ cả quy tắc cho phép (Allow) lẫn từ chối (Deny). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Security Group", "is_correct": true, "analysis_vi": "Đúng. Security Group là đáp án chính xác. Các Security Group hoạt động như tường lửa cho các phiên bản Amazon EC2 được liên kết, kiểm soát cả lưu lượng truy cập vào và ra ở cấp phiên bản."}, {"label": "D", "text_vi": "Trình quản lý tường lửa AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý tường lửa AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon EC2", "AWS Shield", "AWS Secrets Manager"]'::jsonb, NOW())
