INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-192', 'practice_283', 'Dịch vụ AWS nào chuyển đổi văn bản thành giọng nói sống động như thật?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon Polly là dịch vụ biến văn bản thành lời nói sống động như thật, cho phép bạn tạo các ứng dụng có thể nói chuyện và xây dựng các danh mục sản phẩm hỗ trợ giọng nói hoàn toàn mới. Dịch vụ Chuyển văn bản thành giọng nói (TTS) của Polly sử dụng các công nghệ học sâu tiên tiến để tổng hợp giọng nói con người có âm thanh tự nhiên1. Amazon Polly hỗ trợ hàng chục ngôn ngữ và nhiều giọng nói có âm thanh tự nhiên. Bạn có thể tùy chỉnh và kiểm soát đầu ra giọng nói bằng cách sử dụng từ vựng và thẻ SSML. Bạn cũng có thể lưu trữ và phân phối lại đầu ra giọng nói ở các định dạng âm thanh tiêu chuẩn như MP3 và OGG2. Amazon Transcribe là dịch vụ chuyển đổi giọng nói thành văn bản, cho phép bạn tạo bản ghi văn bản từ tệp âm thanh hoặc video. Nó có thể nhận ra nhiều người nói, ngôn ngữ khác nhau, giọng nói, phương ngữ và tiếng ồn xung quanh. Nó cũng có thể thêm dấu câu và định dạng vào bản ghi. Amazon Transcribe rất hữu ích cho các ứng dụng như phụ đề, chú thích, chép lời và tìm kiếm bằng giọng nói. Amazon Rekognition là dịch vụ cung cấp khả năng phân tích hình ảnh và video bằng cách sử dụng thị giác máy tính và học sâu. Nó có thể phát hiện các vật thể, khuôn mặt, văn bản, cảnh, hoạt động và cảm xúc trong hình ảnh và video. Nó cũng có thể thực hiện nhận dạng khuôn mặt, so sánh khuôn mặt, tìm kiếm khuôn mặt, nhận dạng người nổi tiếng và phân tích khuôn mặt. Amazon Rekognition rất hữu ích cho các ứng dụng như bảo mật, truyền thông xã hội, thương mại điện tử cũng như truyền thông và giải trí. Amazon Textract là dịch vụ trích xuất văn bản và dữ liệu từ các tài liệu được quét bằng cách sử dụng nhận dạng ký tự quang học (OCR) và học máy. Nó có thể xác định nội dung của các trường trong biểu mẫu và bảng cũng như mối quan hệ giữa chúng. Nó cũng có thể giữ nguyên bố cục và cấu trúc của tài liệu gốc. Amazon Textract rất hữu ích cho các ứng dụng như nhập dữ liệu, quản lý tài liệu, tuân thủ và phân tích.', '[{"label": "A", "text_vi": "Phiên âm của Amazon", "is_correct": false, "analysis_vi": "Sai. Phiên âm của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Nhận thức lại Amazon", "is_correct": false, "analysis_vi": "Sai. Nhận thức lại Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon Polly", "is_correct": true, "analysis_vi": "Đúng. Amazon Polly là đáp án chính xác. Amazon Polly là dịch vụ biến văn bản thành lời nói sống động như thật, cho phép bạn tạo các ứng dụng có thể nói chuyện và xây dựng các danh mục sản phẩm hỗ trợ giọng nói hoàn toàn mới."}, {"label": "D", "text_vi": "Văn bản Amazon", "is_correct": false, "analysis_vi": "Sai. Văn bản Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
