INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-193', 'practice_283', 'Một công ty muốn cải thiện tình hình kiểm tra và bảo mật của mình bằng cách hạn chế quyền truy cập vào Amazon EC2. Theo mô hình trách nhiệm chung của AWS, nhiệm vụ nào là trách nhiệm của khách hàng?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm định cấu hình các biện pháp kiểm soát truy cập logic cho tài nguyên và bảo vệ thông tin xác thực tài khoản. Điều này bao gồm quản lý quyền của người dùng IAM, quy tắc Security Group, ACL mạng, khóa mã hóa và các khía cạnh khác của quản lý quyền truy cập1. AWS chịu trách nhiệm bảo vệ cơ sở hạ tầng toàn cầu chạy tất cả các dịch vụ được cung cấp trên Đám mây AWS, chẳng hạn như phần cứng, phần mềm, mạng và cơ sở vật chất. AWS cũng chịu trách nhiệm định cấu hình bảo mật được sử dụng bởi các dịch vụ được quản lý, chẳng hạn như Amazon RDS, Amazon DynamoDB và Amazon Aurora2.', '[{"label": "A", "text_vi": "Bảo vệ cơ sở hạ tầng toàn cầu chạy tất cả các dịch vụ được cung cấp trên Đám mây AWS.", "is_correct": false, "analysis_vi": "Sai. Bảo vệ cơ sở hạ tầng toàn cầu chạy tất cả các dịch vụ được cung cấp trên Đám mây AWS. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Định cấu hình các biện pháp kiểm soát truy cập hợp lý cho tài nguyên và bảo vệ thông tin xác thực tài khoản.", "is_correct": true, "analysis_vi": "Đúng. Định cấu hình các biện pháp kiểm soát truy cập hợp lý cho tài nguyên và bảo vệ thông tin xác thực tài khoản. là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm định cấu hình các biện pháp kiểm soát truy cập logic cho tài nguyên và bảo vệ thông tin xác thực tài khoản."}, {"label": "C", "text_vi": "Định cấu hình bảo mật được sử dụng bởi các dịch vụ được quản lý.", "is_correct": false, "analysis_vi": "Sai. Định cấu hình bảo mật được sử dụng bởi các dịch vụ được quản lý.: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Vá và sao lưu Amazon Aurora.", "is_correct": false, "analysis_vi": "Sai. Vá và sao lưu Amazon Aurora.: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2", "Amazon Aurora"]'::jsonb, NOW())
