INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-194', 'practice_283', 'Lợi ích nào của Đám mây AWS mang lại cho công ty khả năng triển khai nhanh chóng các tài nguyên đám mây để truy cập cơ sở hạ tầng điện toán, lưu trữ và cơ sở dữ liệu chỉ trong vài phút?', 'Domain 1: Cloud Concepts', 'Dịch vụ điện toán đám mây Amazon EC2', 'Tính linh hoạt là lợi ích của Đám mây AWS mang lại cho công ty khả năng triển khai nhanh chóng các tài nguyên đám mây để truy cập cơ sở hạ tầng điện toán, lưu trữ và cơ sở dữ liệu chỉ trong vài phút. Tính linh hoạt có nghĩa là bạn có thể giảm thời gian cung cấp tài nguyên CNTT cho nhà phát triển của mình từ vài tuần xuống chỉ còn vài phút, dẫn đến sự gia tăng đáng kể về khả năng đổi mới và khả năng phản hồi1. AWS cung cấp nhiều dịch vụ và công cụ cho phép bạn khởi chạy, mở rộng quy mô và quản lý các ứng dụng đám mây của mình một cách dễ dàng và nhanh chóng, chẳng hạn như AWS CloudFormation, AWS Elastic Beanstalk, AWS CodeDeploy và AWS Quick Starts2345.', '[{"label": "A", "text_vi": "Độ đàn hồi", "is_correct": false, "analysis_vi": "Sai. Độ đàn hồi: Độ co giãn (Elasticity) là khả năng hệ thống tự động tăng hoặc giảm tài nguyên máy tính chính xác theo nhu cầu tải công việc thực tế. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Tiết kiệm chi phí", "is_correct": false, "analysis_vi": "Sai. Tiết kiệm chi phí không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Nhanh nhẹn", "is_correct": true, "analysis_vi": "Đúng. Nhanh nhẹn là đáp án chính xác. Tính linh hoạt là lợi ích của Đám mây AWS mang lại cho công ty khả năng triển khai nhanh chóng các tài nguyên đám mây để truy cập cơ sở hạ tầng điện toán, lưu trữ và cơ sở dữ liệu chỉ trong vài phút."}, {"label": "D", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '[]'::jsonb, NOW())
