INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-195', 'practice_283', 'Công ty có thể sử dụng dịch vụ AWS nào để lưu trữ và chạy cơ sở dữ liệu MySQL? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon RDS và Amazon EC2 là hai dịch vụ AWS mà bạn có thể sử dụng để lưu trữ và chạy cơ sở dữ liệu MySQL. Amazon RDS là dịch vụ giúp bạn dễ dàng thiết lập, vận hành và mở rộng quy mô cơ sở dữ liệu quan hệ trên đám mây. Bạn có thể sử dụng Amazon RDS để khởi chạy phiên bản cơ sở dữ liệu MySQL và để Amazon RDS quản lý các tác vụ cơ sở dữ liệu phổ biến như sao lưu, vá lỗi, thay đổi quy mô và sao chép6. Amazon EC2 là dịch vụ cung cấp khả năng tính toán bảo mật và có thể thay đổi quy mô trên đám mây. Bạn có thể sử dụng Amazon EC2 để khởi chạy máy chủ ảo và cài đặt phần mềm MySQL trên đó. Bạn có toàn quyền kiểm soát cấu hình cơ sở dữ liệu của mình nhưng bạn chịu trách nhiệm quản lý và duy trì phần mềm cơ sở dữ liệu cũng như cơ sở hạ tầng cơ bản7. Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị mang lại hiệu suất mili giây một chữ số ở mọi quy mô. Amazon S3 là dịch vụ lưu trữ đối tượng cung cấp khả năng mở rộng, tính khả dụng của dữ liệu, tính bảo mật và hiệu suất hàng đầu trong ngành. Amazon MQ là dịch vụ môi giới tin nhắn được quản lý dành cho Apache ActiveMQ. Không có dịch vụ nào trong số này có thể giúp bạn lưu trữ và chạy cơ sở dữ liệu MySQL.', '[{"label": "A", "text_vi": "Amazon RDS", "is_correct": true, "analysis_vi": "Đúng. Amazon RDS là giải pháp đáp ứng yêu cầu. Amazon RDS và Amazon EC2 là hai dịch vụ AWS mà bạn có thể sử dụng để lưu trữ và chạy cơ sở dữ liệu MySQL. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao."}, {"label": "B", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon EC2", "is_correct": true, "analysis_vi": "Đúng. Amazon EC2 là giải pháp đáp ứng yêu cầu. Amazon RDS và Amazon EC2 là hai dịch vụ AWS mà bạn có thể sử dụng để lưu trữ và chạy cơ sở dữ liệu MySQL. Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật."}, {"label": "E", "text_vi": "Amazon MQ", "is_correct": false, "analysis_vi": "Sai. Amazon MQ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "Amazon S3", "Amazon RDS", "Amazon DynamoDB"]'::jsonb, NOW())
