INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-196', 'practice_283', 'Một công ty đang lên kế hoạch lưu trữ khối lượng công việc của mình trên AWS. Dịch vụ AWS nào yêu cầu công ty cập nhật và vá lỗi hệ điều hành khách?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Amazon EC2 là dịch vụ AWS cung cấp khả năng tính toán có thể mở rộng, bảo mật và thay đổi kích thước trên đám mây. Amazon EC2 cho phép khách hàng khởi chạy và quản lý các máy chủ ảo, được gọi là phiên bản, chạy nhiều hệ điều hành và ứng dụng khác nhau. Khách hàng có toàn quyền kiểm soát cấu hình và quản lý phiên bản của mình, bao gồm cả hệ điều hành khách. Do đó, khách hàng có trách nhiệm cập nhật và vá lỗi hệ điều hành khách trên các phiên bản EC2 của mình cũng như mọi phần mềm hoặc tiện ích khác được cài đặt trên các phiên bản. AWS cung cấp các công cụ và dịch vụ như AWS Systems Manager và AWS OpsWorks để giúp khách hàng tự động hóa và đơn giản hóa quy trình vá lỗi.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon EC2", "is_correct": true, "analysis_vi": "Đúng. Amazon EC2 là giải pháp đáp ứng yêu cầu. Amazon EC2 là dịch vụ AWS cung cấp khả năng tính toán có thể mở rộng, bảo mật và thay đổi kích thước trên đám mây. Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật."}, {"label": "D", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "Amazon S3", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
