INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-197', 'practice_283', 'Người dùng muốn cho phép các ứng dụng chạy trên phiên bản Amazon EC2 thực hiện lệnh gọi đến các dịch vụ AWS khác. Quyền truy cập được cấp phải được bảo mật. Nên sử dụng dịch vụ hoặc tính năng AWS nào?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Vai trò IAM là một cách an toàn để cấp quyền cho các ứng dụng chạy trên phiên bản Amazon EC2 nhằm thực hiện lệnh gọi tới các dịch vụ AWS khác. Vai trò IAM là các thực thể có chính sách quyền cụ thể kèm theo. Bạn có thể tạo vai trò IAM và liên kết nó với phiên bản EC2 khi bạn khởi chạy phiên bản đó hoặc sau này. Sau đó, các ứng dụng trên phiên bản có thể sử dụng thông tin xác thực tạm thời do vai trò cung cấp để truy cập các tài nguyên AWS mà vai trò đó cho phép. Bằng cách này, bạn không phải lưu trữ bất kỳ thông tin xác thực hoặc khóa truy cập dài hạn nào trên phiên bản, điều này giúp giảm nguy cơ bị xâm phạm hoặc sử dụng sai mục đích12. Các tùy chọn khác không chính xác vì: Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho phiên bản EC2 của bạn. Các Security Group không cấp quyền truy cập các dịch vụ AWS khác mà lọc lưu lượng mạng dựa trên các quy tắc mà bạn xác định3. AWS Fire Manager là dịch vụ giúp bạn đặt cấu hình và quản lý tập trung các quy tắc tường lửa trên các tài khoản và tài nguyên của bạn. Trình quản lý tường lửa AWS hoạt động với các Security Group AWS WAF, AWS Shield Advanced và Amazon VPC. Trình quản lý tường lửa AWS không cấp quyền truy cập các dịch vụ AWS khác mà giúp bạn thực thi các chính sách bảo mật nhất quán trên cơ sở hạ tầng AWS của mình4. Khóa SSH của người dùng IAM là thông tin xác thực cho phép bạn kết nối với phiên bản EC2 của mình bằng SSH. Khóa SSH không cấp quyền truy cập các dịch vụ AWS khác mà xác thực danh tính của bạn khi bạn đăng nhập vào phiên bản5.', '[{"label": "A", "text_vi": "Security Group", "is_correct": false, "analysis_vi": "Sai. Các tùy chọn khác không chính xác vì: Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho phiên bản EC2 của bạn."}, {"label": "B", "text_vi": "Trình quản lý tường lửa AWS", "is_correct": false, "analysis_vi": "Sai. Các tùy chọn khác không chính xác vì: Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho phiên bản EC2 của bạn."}, {"label": "C", "text_vi": "Vai trò IAM", "is_correct": true, "analysis_vi": "Đúng. Vai trò IAM là giải pháp đáp ứng yêu cầu. Vai trò IAM là một cách an toàn để cấp quyền cho các ứng dụng chạy trên phiên bản Amazon EC2 nhằm thực hiện lệnh gọi tới các dịch vụ AWS khác. AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege)."}, {"label": "D", "text_vi": "Khóa SSH của người dùng IAM", "is_correct": false, "analysis_vi": "Sai. Bằng cách này, bạn không phải lưu trữ bất kỳ thông tin xác thực hoặc khóa truy cập dài hạn nào trên phiên bản, điều này giúp giảm nguy cơ bị xâm phạm hoặc sử dụng sai mục đích12."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon EC2", "AWS Secrets Manager", "AWS IAM"]'::jsonb, NOW())
