INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-198', 'practice_283', 'Lựa chọn nào mang lại lợi ích kinh tế nhờ quy mô dựa trên lợi thế của điện toán đám mây?', 'Domain 1: Cloud Concepts', 'Dịch vụ điện toán đám mây Amazon EC2', 'Tính kinh tế nhờ quy mô là lợi thế về chi phí do việc tăng quy mô sản xuất hoặc vận hành. Trong điện toán đám mây, tính kinh tế theo quy mô đạt được bằng cách tập hợp các tài nguyên và chia sẻ chúng giữa nhiều người dùng, giúp giảm chi phí đơn vị tính toán và lưu trữ. Một trong những lợi ích của tính kinh tế theo quy mô trong điện toán đám mây là tăng tốc độ và tính linh hoạt, nghĩa là khả năng triển khai ứng dụng nhanh hơn và đáp ứng nhu cầu kinh doanh thay đổi nhanh hơn. Điện toán đám mây cho phép người dùng truy cập tài nguyên máy tính theo yêu cầu mà không cần phải đầu tư vào cơ sở hạ tầng đắt tiền hoặc chờ đợi quá trình cung cấp kéo dài. Điều này cho phép người dùng tăng hoặc giảm quy mô khi cần, thử nghiệm các ý tưởng mới và mang lại giá trị cho khách hàng nhanh hơn123.', '[{"label": "A", "text_vi": "Khả năng giao dịch chi phí biến đổi với chi phí cố định", "is_correct": false, "analysis_vi": "Sai. Khả năng giao dịch chi phí biến đổi với chi phí cố định không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tăng tốc độ và sự nhanh nhẹn", "is_correct": false, "analysis_vi": "Sai. Tăng tốc độ và sự nhanh nhẹn: Tính nhanh nhạy (Agility) giúp rút ngắn thời gian khởi tạo và thử nghiệm công nghệ từ hàng tuần xuống chỉ còn vài phút. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Chi phí biến đổi thấp hơn chi phí cố định", "is_correct": true, "analysis_vi": "Đúng. Chi phí biến đổi thấp hơn chi phí cố định đáp ứng đầy đủ yêu cầu của đề bài. Tính kinh tế nhờ quy mô là lợi thế về chi phí do việc tăng quy mô sản xuất hoặc vận hành."}, {"label": "D", "text_vi": "Tăng chi phí vận hành trên các trung tâm dữ liệu", "is_correct": false, "analysis_vi": "Sai. Tăng chi phí vận hành trên các trung tâm dữ liệu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
