INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-199', 'practice_283', 'Dịch vụ AWS nào sẽ giúp bảo vệ các ứng dụng chạy trên AWS khỏi các cuộc tấn công DDoS?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Shield là dịch vụ bảo vệ Từ chối dịch vụ phân tán (DDoS) được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS. AWS Shield cung cấp khả năng phát hiện liên tục và giảm thiểu nội tuyến tự động nhằm giảm thiểu thời gian ngừng hoạt động và độ trễ của ứng dụng, do đó không cần phải nhờ tới AWS Support để hưởng lợi từ tính năng bảo vệ DDoS3.', '[{"label": "A", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Khiên AWS", "is_correct": true, "analysis_vi": "Đúng. Khiên AWS là đáp án chính xác. AWS Shield là dịch vụ bảo vệ Từ chối dịch vụ phân tán (DDoS) được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "AWS WAF", "Amazon GuardDuty", "Amazon Inspector"]'::jsonb, NOW())
