INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-200', 'practice_283', 'Gói Hỗ trợ AWS nào là bậc tối thiểu được đề xuất cho người dùng có khối lượng công việc sản xuất trên AWS?', 'Domain 4: Billing, Pricing and Support', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'AWS Business Support là bậc tối thiểu được đề xuất cho người dùng có khối lượng công việc sản xuất trên AWS. AWS Business Support cung cấp quyền truy cập 24x7 cho các kỹ sư hỗ trợ đám mây qua điện thoại, trò chuyện hoặc email cũng như thời gian phản hồi được đảm bảo dưới một giờ đối với các vấn đề khẩn cấp. AWS Business Support cũng bao gồm quyền truy cập vào AWS Trusted Advisor, một công cụ cung cấp hướng dẫn theo thời gian thực để giúp bạn cung cấp tài nguyên của mình theo các biện pháp thực hành tốt nhất của AWS4.', '[{"label": "A", "text_vi": "Hỗ trợ nhà phát triển AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ nhà phát triển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hỗ trợ doanh nghiệp AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ doanh nghiệp AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Hỗ trợ kinh doanh của AWS", "is_correct": true, "analysis_vi": "Đúng. Hỗ trợ kinh doanh của AWS là đáp án chính xác. AWS Business Support là bậc tối thiểu được đề xuất cho người dùng có khối lượng công việc sản xuất trên AWS."}, {"label": "D", "text_vi": "Hỗ trợ trên đường nối của AWS Enterprise", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ trên đường nối của AWS Enterprise không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
