INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-201', 'practice_283', 'AWS thuộc trách nhiệm của những nhiệm vụ nào theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Các nhiệm vụ thuộc trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS là đảm bảo quyền truy cập vào các cơ sở AWS vật lý cũng như thực hiện vá lỗi và bảo trì cơ sở hạ tầng. Mô hình trách nhiệm chung của AWS xác định sự phân chia trách nhiệm giữa AWS và khách hàng về vấn đề bảo mật và tuân thủ. AWS chịu trách nhiệm về bảo mật của đám mây, bao gồm bảo mật vật lý của phần cứng, phần mềm, mạng và cơ sở chạy dịch vụ AWS. AWS cũng chịu trách nhiệm bảo trì và vá lỗi cơ sở hạ tầng hỗ trợ các dịch vụ AWS. Khách hàng chịu trách nhiệm về tính bảo mật trên đám mây, bao gồm cấu hình và quản lý các tài nguyên cũng như ứng dụng AWS mà họ sử dụng. Định cấu hình AWS Identity and Access Management (IAM), định cấu hình Security Group trên phiên bản Amazon EC2 và vá lỗi các ứng dụng chạy trên phiên bản Amazon EC2 là các nhiệm vụ thuộc trách nhiệm của khách hàng, không phải của AWS.', '[{"label": "A", "text_vi": "Định cấu hình AWS Identity and Access Management (IAM).", "is_correct": false, "analysis_vi": "Sai. Định cấu hình AWS Identity and Access Management (IAM).: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Định cấu hình Security Group trên phiên bản Amazon EC2.", "is_correct": false, "analysis_vi": "Sai. Định cấu hình Security Group trên phiên bản Amazon EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Bảo mật quyền truy cập vào cơ sở AWS vật lý.", "is_correct": true, "analysis_vi": "Đúng. Bảo mật quyền truy cập vào cơ sở AWS vật lý. là đáp án chính xác. Các nhiệm vụ thuộc trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS là đảm bảo quyền truy cập vào các cơ sở AWS vật lý cũng như thực hiện vá lỗi và bảo trì cơ sở hạ tầng."}, {"label": "D", "text_vi": "Vá các ứng dụng chạy trên phiên bản Amazon EC2.", "is_correct": false, "analysis_vi": "Sai. Vá các ứng dụng chạy trên phiên bản Amazon EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Thực hiện vá lỗi và bảo trì cơ sở hạ tầng.", "is_correct": true, "analysis_vi": "Đúng. Thực hiện vá lỗi và bảo trì cơ sở hạ tầng. là đáp án chính xác. Các nhiệm vụ thuộc trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS là đảm bảo quyền truy cập vào các cơ sở AWS vật lý cũng như thực hiện vá lỗi và bảo trì cơ sở hạ tầng."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2", "AWS IAM"]'::jsonb, NOW())
