INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-202', 'practice_283', 'Một công ty cần sử dụng SQL tiêu chuẩn để truy vấn và kết hợp hàng exabyte dữ liệu có cấu trúc và bán cấu trúc trên kho dữ liệu, cơ sở dữ liệu vận hành và hồ dữ liệu. Dịch vụ AWS nào đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon Redshift là dịch vụ đáp ứng các yêu cầu sử dụng SQL tiêu chuẩn để truy vấn và kết hợp hàng exabyte dữ liệu có cấu trúc và bán cấu trúc trên kho dữ liệu, cơ sở dữ liệu vận hành và kho dữ liệu. Amazon Redshift là dịch vụ kho dữ liệu quy mô petabyte, được quản lý toàn phần, cho phép bạn chạy các truy vấn phân tích phức tạp bằng cách sử dụng SQL tiêu chuẩn và các công cụ nghiệp vụ thông minh hiện có của bạn. Amazon Redshift cũng hỗ trợ Redshift Spectrum, một tính năng cho phép bạn truy vấn trực tiếp và kết hợp dữ liệu được lưu trữ trong Amazon S3 bằng cùng một cú pháp SQL. Amazon Redshift có thể tăng hoặc giảm quy mô để xử lý mọi khối lượng dữ liệu và mang lại hiệu suất truy vấn nhanh5', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon Athena", "is_correct": false, "analysis_vi": "Sai. Amazon Athena không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": true, "analysis_vi": "Đúng. Dịch chuyển đỏ của Amazon là đáp án chính xác. Amazon Redshift là dịch vụ đáp ứng các yêu cầu sử dụng SQL tiêu chuẩn để truy vấn và kết hợp hàng exabyte dữ liệu có cấu trúc và bán cấu trúc trên kho dữ liệu, cơ sở dữ liệu vận hành và kho dữ liệu."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
