INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-203', 'practice_283', 'Thông tin xác thực cơ sở dữ liệu nên được lưu trữ trong dịch vụ AWS nào sau đây để bảo mật tối đa?', 'Domain 2: Security and Compliance', 'Giải pháp cơ sở dữ liệu trên AWS', 'AWS Secrets Manager là dịch vụ AWS nơi lưu trữ thông tin xác thực cơ sở dữ liệu để bảo mật tối đa. AWS Secrets Manager giúp bảo vệ các bí mật, chẳng hạn như thông tin xác thực cơ sở dữ liệu, mật khẩu, khóa API và mã thông báo, được sử dụng để truy cập các ứng dụng, dịch vụ và tài nguyên. AWS Secrets Manager cho phép lưu trữ, mã hóa, xoay và truy xuất bí mật một cách an toàn. AWS Secrets Manager cũng tích hợp với các dịch vụ AWS khác, chẳng hạn như AWS Identity and Access Management (IAM), AWS Key Management Service (AWS KMS) và AWS Lambda. Để biết thêm thông tin, hãy xem [AWS Secrets Manager là gì?] và [Bắt đầu với AWS Secrets Manager].', '[{"label": "A", "text_vi": "Quản lý quyền truy cập và nhận dạng AWS (IAM)", "is_correct": false, "analysis_vi": "Sai. Quản lý quyền truy cập và nhận dạng AWS (IAM): AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS Secrets Manager", "is_correct": true, "analysis_vi": "Đúng. AWS Secrets Manager là đáp án chính xác. AWS Secrets Manager là dịch vụ AWS nơi lưu trữ thông tin xác thực cơ sở dữ liệu để bảo mật tối đa."}, {"label": "C", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dịch vụ quản lý khóa AWS (AWS KMS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ quản lý khóa AWS (AWS KMS): AWS Key Management Service (KMS) giúp tạo, quản lý và kiểm soát các khóa mã hóa dùng để mã hóa dữ liệu trên các dịch vụ AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS KMS", "AWS Secrets Manager", "AWS IAM"]'::jsonb, NOW())
