INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-204', 'practice_283', 'Dịch vụ hoặc công cụ AWS nào cung cấp quyền truy cập theo yêu cầu vào các báo cáo tuân thủ và bảo mật AWS cũng như các thỏa thuận trực tuyến của AWS?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Artifact là dịch vụ hoặc công cụ AWS cung cấp quyền truy cập theo yêu cầu vào các báo cáo tuân thủ và bảo mật AWS cũng như các thỏa thuận trực tuyến của AWS. AWS Trusted Advisor là công cụ cung cấp hướng dẫn theo thời gian thực để giúp người dùng cung cấp tài nguyên của họ theo các phương pháp thực hành tốt nhất của AWS. Amazon Inspector là dịch vụ giúp người dùng cải thiện tính bảo mật và tuân thủ cho ứng dụng của họ. Bảng điều khiển thanh toán AWS là công cụ giúp người dùng quản lý chi phí và mức sử dụng AWS của họ. Những khái niệm này được giải thích trong khóa học Kiến thức cơ bản dành cho người thực hành đám mây AWS3.', '[{"label": "A", "text_vi": "Hiện vật AWS", "is_correct": true, "analysis_vi": "Đúng. Hiện vật AWS là đáp án chính xác. AWS Artifact là dịch vụ hoặc công cụ AWS cung cấp quyền truy cập theo yêu cầu vào các báo cáo tuân thủ và bảo mật AWS cũng như các thỏa thuận trực tuyến của AWS."}, {"label": "B", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Bảng điều khiển thanh toán AWS", "is_correct": false, "analysis_vi": "Sai. Bảng điều khiển thanh toán AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS Trusted Advisor", "Amazon Inspector", "AWS Artifact"]'::jsonb, NOW())
