INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-205', 'practice_283', 'Một công ty có các nhóm có vai trò và trách nhiệm công việc khác nhau. Nhân viên của công ty thường xuyên thay đổi đội. Công ty cần quản lý các quyền cho nhân viên sao cho các quyền đó phù hợp với trách nhiệm công việc. Công ty nên sử dụng tài nguyên IAM nào để đáp ứng yêu cầu này với chi phí hoạt động ÍT NHẤT?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Vai trò IAM là một cách cấp quyền tạm thời cho các thực thể cần truy cập tài nguyên AWS, chẳng hạn như người dùng, ứng dụng hoặc dịch vụ. Vai trò IAM cho phép khách hàng chỉ định quyền cho các thực thể mà không cần phải tạo hoặc quản lý người dùng IAM hoặc thông tin xác thực cho họ. Các thực thể khác nhau có thể đảm nhận các vai trò IAM tùy thuộc vào chính sách tin cậy gắn liền với vai trò đó. Ví dụ: Người dùng IAM có thể đảm nhận vai trò IAM trong cùng một hoặc các tài khoản AWS khác nhau, các dịch vụ AWS như EC2 hoặc Lambda hoặc các danh tính bên ngoài như người dùng liên kết hoặc danh tính web. Người dùng IAM cũng có thể chuyển đổi vai trò IAM để tạm thời thay đổi quyền của họ. Vai trò IAM được đề xuất để quản lý quyền cho những nhân viên thường xuyên thay đổi nhóm vì chúng cho phép khách hàng xác định quyền dựa trên vai trò và trách nhiệm công việc, đồng thời dễ dàng gán hoặc thu hồi chúng khi cần. Vai trò IAM cũng giảm chi phí hoạt động trong việc tạo, cập nhật hoặc xóa người dùng hoặc thông tin đăng nhập IAM đối với mỗi thay đổi của nhân viên hoặc nhóm.', '[{"label": "A", "text_vi": "Nhóm người dùng IAM", "is_correct": false, "analysis_vi": "Sai. Nhóm người dùng IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Vai trò IAM", "is_correct": true, "analysis_vi": "Đúng. Vai trò IAM là giải pháp đáp ứng yêu cầu. Vai trò IAM là một cách cấp quyền tạm thời cho các thực thể cần truy cập tài nguyên AWS, chẳng hạn như người dùng, ứng dụng hoặc dịch vụ. AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege)."}, {"label": "C", "text_vi": "Cấu hình phiên bản IAM", "is_correct": false, "analysis_vi": "Sai. Cấu hình phiên bản IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Chính sách IAM dành cho người dùng cá nhân", "is_correct": false, "analysis_vi": "Sai. Chính sách IAM dành cho người dùng cá nhân: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
