INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-206', 'practice_283', 'Dịch vụ AWS nào giúp nhà phát triển sử dụng tính năng ghép nối lỏng lẻo và nhắn tin đáng tin cậy giữa các vi dịch vụ?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon Simple Queue Service (Amazon SQS) là dịch vụ cung cấp hàng đợi tin nhắn được quản lý hoàn toàn để liên lạc không đồng bộ giữa các vi dịch vụ. Nó giúp các nhà phát triển sử dụng tính năng ghép nối lỏng lẻo và nhắn tin đáng tin cậy bằng cách cho phép họ gửi, lưu trữ và nhận tin nhắn giữa các thành phần được phân phối mà không làm mất chúng hoặc yêu cầu mỗi thành phần phải luôn sẵn sàng1. Cân bằng tải đàn hồi là dịch vụ phân phối lưu lượng truy cập đến trên nhiều mục tiêu, chẳng hạn như phiên bản, bộ chứa và địa chỉ IP của Amazon EC2. Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) là dịch vụ cung cấp tính năng nhắn tin pub/sub được quản lý hoàn toàn để liên lạc theo sự kiện và dựa trên đẩy giữa các vi dịch vụ. Amazon CloudFront là dịch vụ cung cấp mạng phân phối nội dung (CDN) nhanh chóng và an toàn cho các ứng dụng web.', '[{"label": "A", "text_vi": "Cân bằng tải đàn hồi", "is_correct": false, "analysis_vi": "Sai. Nó giúp các nhà phát triển sử dụng tính năng ghép nối lỏng lẻo và nhắn tin đáng tin cậy bằng cách cho phép họ gửi, lưu trữ và nhận tin nhắn giữa các thành phần được phân phối mà không làm mất chúng hoặc yêu cầu mỗi thành phần phải luôn sẵn sàng1."}, {"label": "B", "text_vi": "Dịch vụ thông báo đơn giản của Amazon (Amazon SNS)", "is_correct": false, "analysis_vi": "Sai. Amazon Simple Queue Service (Amazon SQS) là dịch vụ cung cấp hàng đợi tin nhắn được quản lý hoàn toàn để liên lạc không đồng bộ giữa các vi dịch vụ."}, {"label": "C", "text_vi": "Amazon CloudFront", "is_correct": false, "analysis_vi": "Sai. Amazon CloudFront: Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) toàn cầu với độ trễ thấp thông qua mạng lưới các Edge Location. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS) là đáp án chính xác. Amazon Simple Queue Service (Amazon SQS) là dịch vụ cung cấp hàng đợi tin nhắn được quản lý hoàn toàn để liên lạc không đồng bộ giữa các vi dịch vụ."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudFront", "Amazon SNS", "Amazon SQS"]'::jsonb, NOW())
