INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-207', 'practice_283', 'Nhóm phát triển muốn triển khai nhiều môi trường thử nghiệm cho một ứng dụng theo cách có thể lặp lại nhanh chóng. Nhóm nên sử dụng dịch vụ AWS nào?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS CloudFormation là dịch vụ cho phép bạn lập mô hình và cung cấp tài nguyên AWS bằng cách sử dụng các mẫu. Bạn có thể xác định cơ sở hạ tầng của mình dưới dạng mã và tự động hóa việc tạo và cập nhật tài nguyên của mình. AWS CloudFormation cũng hỗ trợ các ngăn xếp lồng nhau, bộ thay đổi và tính năng khôi phục để giúp bạn quản lý các môi trường phức tạp và năng động34.', '[{"label": "A", "text_vi": "Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Đám mây AWS", "is_correct": true, "analysis_vi": "Đúng. Đám mây AWS là đáp án chính xác. AWS CloudFormation là dịch vụ cho phép bạn lập mô hình và cung cấp tài nguyên AWS bằng cách sử dụng các mẫu."}, {"label": "C", "text_vi": "Amazon QuickSight", "is_correct": false, "analysis_vi": "Sai. Amazon QuickSight không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch vụ container đàn hồi của Amazon (Amazon ECS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ container đàn hồi của Amazon (Amazon ECS): Amazon ECS là dịch vụ điều phối container Docker có khả năng mở rộng cao và hiệu năng cao trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS CloudFormation"]'::jsonb, NOW())
