INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-208', 'practice_283', 'Một công ty muốn cấp cho người dùng trong một tài khoản AWS quyền truy cập vào tài nguyên trong một tài khoản AWS khác. Người dùng hiện không có quyền truy cập vào tài nguyên. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Vai trò IAM là một cách để ủy quyền truy cập vào tài nguyên trong các tài khoản AWS khác nhau. Vai trò IAM cho phép người dùng đảm nhận một nhóm quyền trong thời gian giới hạn mà không cần phải tạo hoặc chia sẻ thông tin xác thực dài hạn. Bạn có thể sử dụng vai trò IAM để cấp quyền truy cập nhiều tài khoản bằng cách tạo mối quan hệ tin cậy giữa các tài khoản và chỉ định các quyền mà vai trò đó có thể thực hiện. Sau đó, người dùng có thể chuyển sang vai trò và truy cập tài nguyên trong tài khoản khác bằng thông tin xác thực bảo mật tạm thời do vai trò cung cấp.', '[{"label": "A", "text_vi": "Nhóm IAM", "is_correct": false, "analysis_vi": "Sai. Vai trò IAM cho phép người dùng đảm nhận một nhóm quyền trong thời gian giới hạn mà không cần phải tạo hoặc chia sẻ thông tin xác thực dài hạn."}, {"label": "B", "text_vi": "Vai trò IAM", "is_correct": true, "analysis_vi": "Đúng. Vai trò IAM là giải pháp đáp ứng yêu cầu. Vai trò IAM là một cách để ủy quyền truy cập vào tài nguyên trong các tài khoản AWS khác nhau. AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege)."}, {"label": "C", "text_vi": "Thẻ IAM", "is_correct": false, "analysis_vi": "Sai. Thẻ IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Trình phân tích truy cập IAM", "is_correct": false, "analysis_vi": "Sai. Trình phân tích truy cập IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
