INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-209', 'practice_283', 'Một công ty có khối lượng công việc ứng dụng không có trạng thái theo thiết kế và có thể thỉnh thoảng ngừng hoạt động. Ứng dụng này thực hiện các tính toán song song ồ ạt. Công ty nên chọn mô hình định giá Amazon EC2 nào cho ứng dụng của mình để giảm chi phí?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Phiên bản dùng ngay Amazon EC2 cho phép bạn tận dụng dung lượng EC2 chưa sử dụng trên đám mây AWS. Phiên bản Spot được cung cấp với mức giảm giá lên tới 90% so với giá Theo yêu cầu. Bạn có thể sử dụng Phiên bản Spot cho nhiều ứng dụng không trạng thái, có khả năng chịu lỗi hoặc linh hoạt khác nhau, chẳng hạn như dữ liệu lớn, khối lượng công việc trong bộ chứa, CI/CD, máy chủ web, điện toán hiệu năng cao (HPC) cũng như các khối lượng công việc thử nghiệm & phát triển khác. Phiên bản Spot rất phù hợp cho các tính toán song song quy mô lớn vì chúng có thể cung cấp lượng công suất điện toán lớn với chi phí thấp và có thể bị gián đoạn chỉ sau hai phút3', '[{"label": "A", "text_vi": "Phiên bản theo yêu cầu", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Phiên bản Spot", "is_correct": true, "analysis_vi": "Đúng. Phiên bản Spot là đáp án chính xác. Phiên bản dùng ngay Amazon EC2 cho phép bạn tận dụng dung lượng EC2 chưa sử dụng trên đám mây AWS."}, {"label": "C", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Phiên bản chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Phiên bản chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
