INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-210', 'practice_283', 'Một công ty muốn chạy khối lượng công việc sản xuất của mình trên AWS. Công ty cần dịch vụ trợ giúp đặc biệt, người quản lý tài khoản kỹ thuật AWS (TAM) được chỉ định và hỗ trợ kỹ thuật luôn sẵn sàng 24 giờ một ngày, 7 ngày một tuần. Gói hỗ trợ AWS nào sẽ đáp ứng các yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Các gói hỗ trợ kỹ thuật AWS Support Plans', 'B đúng vì AWS Enterprise Support là gói AWS Support cung cấp dịch vụ trợ giúp đặc biệt, người quản lý tài khoản kỹ thuật AWS (TAM) được chỉ định và hỗ trợ kỹ thuật luôn sẵn sàng 24 giờ một ngày, 7 ngày một tuần. Gói này được thiết kế dành cho những khách hàng chạy khối lượng công việc quan trọng trên AWS và cần mức hỗ trợ cao nhất. A không chính xác vì AWS Basic Support là gói AWS Support cung cấp dịch vụ khách hàng và hỗ trợ cho các vấn đề về thanh toán và tài khoản, tăng giới hạn dịch vụ và hỗ trợ kỹ thuật cho một bộ dịch vụ AWS có giới hạn. Nó không cung cấp dịch vụ trợ giúp đặc biệt, TAM được chỉ định hoặc hỗ trợ kỹ thuật 24/7. C không chính xác vì AWS Business Support là gói AWS Support cung cấp dịch vụ khách hàng và hỗ trợ cho các vấn đề về thanh toán và tài khoản, tăng giới hạn dịch vụ và hỗ trợ kỹ thuật cho tất cả các dịch vụ AWS cũng như quyền truy cập vào AWS Trusted Advisor và API AWS Support. Nó không cung cấp dịch vụ trợ giúp đặc biệt hoặc TAM được chỉ định. D không chính xác vì Hỗ trợ nhà phát triển AWS là gói Hỗ trợ AWS cung cấp dịch vụ khách hàng và hỗ trợ cho các vấn đề về thanh toán và tài khoản, tăng giới hạn dịch vụ và hỗ trợ kỹ thuật cho tất cả các dịch vụ AWS cũng như quyền truy cập vào AWS Trusted Advisor. Nó không cung cấp dịch vụ trợ giúp đặc biệt, TAM được chỉ định hoặc hỗ trợ kỹ thuật 24/7.', '[{"label": "A", "text_vi": "Hỗ trợ cơ bản của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ cơ bản của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hỗ trợ doanh nghiệp AWS", "is_correct": true, "analysis_vi": "Đúng. Hỗ trợ doanh nghiệp AWS là đáp án chính xác. B đúng vì AWS Enterprise Support là gói AWS Support cung cấp dịch vụ trợ giúp đặc biệt, người quản lý tài khoản kỹ thuật AWS (TAM) được chỉ định và hỗ trợ kỹ thuật luôn sẵn sàng 24 giờ một ngày, 7 ngày một tuần."}, {"label": "C", "text_vi": "Hỗ trợ kinh doanh của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ kinh doanh của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hỗ trợ nhà phát triển AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ nhà phát triển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '["AWS Secrets Manager"]'::jsonb, NOW())
