INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-211', 'practice_283', 'Một công ty điều hành cơ sở dữ liệu trên Amazon Aurora ở Khu vực us-east-1. Công ty có yêu cầu khắc phục thảm họa là cơ sở dữ liệu phải có sẵn ở Khu vực khác. Giải pháp nào đáp ứng yêu cầu này với sự gián đoạn tối thiểu đối với hoạt động của cơ sở dữ liệu?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Giải pháp đáp ứng yêu cầu của công ty vận hành cơ sở dữ liệu trên Amazon Aurora ở Khu vực us-East-1 và có yêu cầu khắc phục thảm họa là cơ sở dữ liệu phải sẵn có ở Khu vực khác với sự gián đoạn tối thiểu đối với các hoạt động cơ sở dữ liệu là triển khai bản sao đọc Aurora xuyên khu vực. Bản sao đọc Aurora xuyên khu vực là các cụm Aurora phụ được tạo ở AWS Region khác với cụm Aurora chính và được giữ đồng bộ hóa với cụm chính bằng cách sử dụng bản sao vật lý. Công ty có thể sử dụng bản sao đọc Aurora xuyên khu vực để cải thiện tính khả dụng và độ bền của cơ sở dữ liệu, cũng như giảm mục tiêu thời gian khôi phục (RTO) và mục tiêu điểm khôi phục (RPO) trong trường hợp xảy ra thảm họa trong khu vực. Thực hiện triển khai Aurora Multi-AZ, tạo bản kết xuất nhanh khối lượng Amazon EBS cho Aurora và sao chép chúng sang Khu vực khác cũng như triển khai Bản sao Aurora không phải là giải pháp tốt nhất cho yêu cầu này. Triển khai Aurora Multi-AZ là cấu hình tạo ra một hoặc nhiều Bản sao Aurora trong cùng AWS Region với cụm Aurora chính và cung cấp khả năng chuyển đổi dự phòng tự động trong trường hợp ngừng hoạt động của Availability Zone (AZ). Tuy nhiên, điều này không cung cấp khả năng khắc phục thảm họa xuyên khu vực. Tạo bản kết xuất nhanh ổ đĩa Amazon EBS cho Aurora và sao chép chúng sang Khu vực khác là một quy trình thủ công yêu cầu dừng cơ sở dữ liệu, tạo bản kết xuất nhanh, sao chép chúng vào Khu vực mục tiêu và khôi phục chúng vào cụm Aurora mới. Quá trình này có thể gây ra thời gian ngừng hoạt động và mất dữ liệu đáng kể. Triển khai Bản sao Aurora là cấu hình tạo ra một hoặc nhiều cụm Aurora phụ trong cùng AWS Region với cụm Aurora chính, đồng thời cung cấp khả năng mở rộng quy mô đọc và tính sẵn sàng cao. Tuy nhiên, điều này không cung cấp khả năng khắc phục thảm họa xuyên khu vực. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Thực hiện triển khai Aurora Multi-AZ.", "is_correct": false, "analysis_vi": "Sai. Thực hiện triển khai Aurora Multi-AZ.: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Triển khai bản sao đọc của Aurora trên nhiều khu vực.", "is_correct": true, "analysis_vi": "Đúng. Triển khai bản sao đọc của Aurora trên nhiều khu vực. là đáp án chính xác. Giải pháp đáp ứng yêu cầu của công ty vận hành cơ sở dữ liệu trên Amazon Aurora ở Khu vực us-East-1 và có yêu cầu khắc phục thảm họa là cơ sở dữ liệu phải sẵn có ở Khu vực khác với sự gián đoạn tối thiểu đối với các hoạt động cơ sở dữ liệu là triển khai bản sao đọc Aurora xuyên khu vực."}, {"label": "C", "text_vi": "Tạo ảnh chụp nhanh ổ đĩa Amazon Elastic Block Store (Amazon EBS) cho Aurora và sao chép chúng sang Khu vực khác.", "is_correct": false, "analysis_vi": "Sai. Tạo ảnh chụp nhanh ổ đĩa Amazon Elastic Block Store (Amazon EBS) cho Aurora và sao chép chúng sang Khu vực khác.: Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Triển khai bản sao Aurora.", "is_correct": false, "analysis_vi": "Sai. Triển khai bản sao Aurora.: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon Aurora"]'::jsonb, NOW())
