INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-212', 'practice_283', 'Công ty cần đánh giá môi trường AWS của mình và đưa ra các đề xuất phương pháp hay nhất theo năm hạng mục: chi phí, hiệu suất, giới hạn dịch vụ, khả năng chịu lỗi và bảo mật. Công ty có thể sử dụng dịch vụ AWS nào để đáp ứng các yêu cầu này?', 'Domain 2: Security and Compliance', 'Quản lý chi phí & Thanh toán AWS', 'AWS Trusted Advisor là dịch vụ có thể đáp ứng được những yêu cầu này. AWS Trusted Advisor là dịch vụ giúp bạn tối ưu hóa môi trường AWS bằng cách đưa ra đề xuất dựa trên các phương pháp thực hành tốt nhất của AWS. Trusted Advisor liên tục đánh giá các tài nguyên và dịch vụ AWS của bạn theo năm hạng mục: tối ưu hóa chi phí, hiệu suất, giới hạn dịch vụ, khả năng chịu lỗi và bảo mật. Bạn có thể xem các đề xuất trên bảng điều khiển Trusted Advisor hoặc truy cập chúng theo chương trình bằng API Trusted Advisor. Bạn cũng có thể thiết lập thông báo và cảnh báo cho bất kỳ thay đổi nào về trạng thái séc của mình. Trusted Advisor có thể giúp bạn cải thiện môi trường AWS bằng cách giảm chi phí, nâng cao hiệu suất, tăng cường bảo mật và đảm bảo độ tin cậy12. Các dịch vụ khác không được thiết kế để cung cấp các khuyến nghị thực hành tốt nhất trong năm loại. AWS Shield là dịch vụ bảo vệ tài nguyên AWS của bạn khỏi các cuộc tấn công từ chối dịch vụ (DDoS) phân tán. AWS WAF là dịch vụ giúp bạn bảo vệ các ứng dụng web của mình khỏi các cách khai thác web phổ biến. Danh mục dịch vụ AWS là dịch vụ cho phép bạn tạo và quản lý danh mục dịch vụ CNTT được phê duyệt để sử dụng trên AWS34.', '[{"label": "A", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Trusted Advisor", "is_correct": true, "analysis_vi": "Đúng. AWS Trusted Advisor là đáp án chính xác. AWS Trusted Advisor là dịch vụ có thể đáp ứng được những yêu cầu này."}, {"label": "D", "text_vi": "Danh mục dịch vụ AWS", "is_correct": false, "analysis_vi": "Sai. Danh mục dịch vụ AWS: AWS Service Catalog cho phép tổ chức tạo và quản lý các danh mục dịch vụ CNTT đã được phê duyệt sẵn để người dùng tự triển khai. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Trusted Advisor", "AWS Shield", "AWS WAF"]'::jsonb, NOW())
