INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-213', 'practice_283', 'Theo mô hình trách nhiệm chung của AWS, trách nhiệm nào sau đây là của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Câu trả lời đúng là A và D vì cơ sở hạ tầng mạng và ảo hóa cơ sở hạ tầng cũng như bảo mật vật lý của phần cứng là trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS. Mô hình trách nhiệm chung của AWS là một khuôn khổ xác định sự phân chia trách nhiệm giữa AWS và khách hàng về vấn đề bảo mật và tuân thủ. AWS chịu trách nhiệm về tính bảo mật của đám mây, bao gồm cơ sở hạ tầng toàn cầu, chẳng hạn như các khu vực, Availability Zone (AZ) và vị trí biên; phần cứng, phần mềm, mạng và cơ sở vật chất chạy các dịch vụ AWS; và lớp ảo hóa phân tách phiên bản khách hàng và bộ lưu trữ. Khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm dữ liệu khách hàng, hệ điều hành khách, ứng dụng, quản lý danh tính và quyền truy cập, cấu hình tường lửa và mã hóa. Các tùy chọn khác không chính xác vì chúng không phải là trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS. Bảo mật dữ liệu ứng dụng, hệ điều hành khách cũng như thông tin xác thực và chính sách là trách nhiệm của khách hàng theo mô hình trách nhiệm chung của AWS.', '[{"label": "A", "text_vi": "Hạ tầng mạng và ảo hóa hạ tầng", "is_correct": true, "analysis_vi": "Đúng. Hạ tầng mạng và ảo hóa hạ tầng là đáp án chính xác. Câu trả lời đúng là A và D vì cơ sở hạ tầng mạng và ảo hóa cơ sở hạ tầng cũng như bảo mật vật lý của phần cứng là trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS."}, {"label": "B", "text_vi": "Bảo mật dữ liệu ứng dụng", "is_correct": false, "analysis_vi": "Sai. Bảo mật dữ liệu ứng dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Hệ điều hành khách", "is_correct": false, "analysis_vi": "Sai. Hệ điều hành khách không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Bảo mật vật lý của phần cứng", "is_correct": true, "analysis_vi": "Đúng. Bảo mật vật lý của phần cứng là đáp án chính xác. Câu trả lời đúng là A và D vì cơ sở hạ tầng mạng và ảo hóa cơ sở hạ tầng cũng như bảo mật vật lý của phần cứng là trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS."}, {"label": "E", "text_vi": "Thông tin xác thực và chính sách", "is_correct": false, "analysis_vi": "Sai. Các tùy chọn khác không chính xác vì chúng không phải là trách nhiệm của AWS theo mô hình trách nhiệm chung của AWS."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
