INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-214', 'practice_283', 'Một công ty sử dụng AWS Organs. Công ty muốn áp dụng các biện pháp bảo mật tốt nhất từ ​​Khung kiến ​​trúc tối ưu AWS cho tất cả các tài khoản AWS của mình. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Tháp điều khiển AWS là cách dễ dàng nhất để thiết lập và quản lý môi trường AWS đa tài khoản, an toàn dựa trên các biện pháp thực hành tốt nhất được thiết lập thông qua kinh nghiệm của AWS khi làm việc với hàng nghìn doanh nghiệp khi họ chuyển sang đám mây. Với Tháp điều khiển AWS, các nhà xây dựng có thể cung cấp tài khoản AWS mới chỉ bằng vài cú nhấp chuột, trong khi bạn có thể yên tâm khi biết tài khoản của mình tuân thủ chính sách của tổ chức. Tháp điều khiển AWS tự động hóa việc thiết lập môi trường cơ sở hoặc vùng hạ cánh, đó là môi trường AWS đa tài khoản có kiến ​​trúc tốt, an toàn1. Tháp điều khiển AWS giúp bạn áp dụng các biện pháp bảo mật tốt nhất từ ​​Khung kiến ​​trúc tối ưu AWS cho tất cả các tài khoản AWS của bạn2.', '[{"label": "A", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon Macie: Amazon Macie sử dụng máy học và đối sánh mẫu để tự động phát hiện, phân loại và bảo vệ dữ liệu nhạy cảm (như PII, số thẻ tín dụng) trên Amazon S3. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Thám tử Amazon", "is_correct": false, "analysis_vi": "Sai. Thám tử Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Tháp điều khiển AWS", "is_correct": true, "analysis_vi": "Đúng. Tháp điều khiển AWS là đáp án chính xác. Tháp điều khiển AWS là cách dễ dàng nhất để thiết lập và quản lý môi trường AWS đa tài khoản, an toàn dựa trên các biện pháp thực hành tốt nhất được thiết lập thông qua kinh nghiệm của AWS khi làm việc với hàng nghìn doanh nghiệp khi họ chuyển sang đám mây."}, {"label": "D", "text_vi": "AWS Secrets Manager", "is_correct": false, "analysis_vi": "Sai. AWS Secrets Manager: AWS Secrets Manager giúp lưu trữ, xoay vòng tự động và quản lý các thông tin bí mật như mật khẩu database và API key trong suốt vòng đời. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS Organizations", "Amazon Macie", "AWS Secrets Manager"]'::jsonb, NOW())
