INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-215', 'practice_283', 'Một công ty muốn tự động thêm và xóa phiên bản Amazon EC2. Công ty muốn các phiên bản EC2 tự động điều chỉnh theo khối lượng công việc khác nhau. Dịch vụ hoặc tính năng nào sẽ đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon EC2 Auto Scaling là dịch vụ giúp bạn duy trì tính khả dụng của ứng dụng và cho phép bạn tự động thêm hoặc xóa phiên bản EC2 theo các điều kiện có thể xác định. Bạn có thể tạo bộ sưu tập phiên bản EC2, được gọi là nhóm Auto Scaling, đồng thời chỉ định số lượng phiên bản tối thiểu và tối đa trong mỗi nhóm. Bạn cũng có thể xác định các chính sách mở rộng quy mô để điều chỉnh số lượng phiên bản dựa trên nhu cầu trên ứng dụng của mình. Amazon EC2 Auto Scaling giúp bạn cải thiện hiệu suất, độ tin cậy và hiệu quả chi phí cho khối lượng công việc EC2 của bạn123.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Phiên bản Spot của Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Phiên bản Spot của Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Gia đình AWS Snow", "is_correct": false, "analysis_vi": "Sai. Gia đình AWS Snow không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Tự động thay đổi quy mô Amazon EC2", "is_correct": true, "analysis_vi": "Đúng. Tự động thay đổi quy mô Amazon EC2 là đáp án chính xác. Amazon EC2 Auto Scaling là dịch vụ giúp bạn duy trì tính khả dụng của ứng dụng và cho phép bạn tự động thêm hoặc xóa phiên bản EC2 theo các điều kiện có thể xác định."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon DynamoDB"]'::jsonb, NOW())
