INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-216', 'practice_283', 'Những nhiệm vụ nào thuộc trách nhiệm của khách hàng theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm các nhiệm vụ quản lý mã hóa dữ liệu và cấp quyền truy cập đặc quyền tối thiểu cho người dùng IAM. Mã hóa dữ liệu là quá trình chuyển đổi dữ liệu sang định dạng không thể đọc được và chỉ có thể truy cập được bằng khóa hoặc mật khẩu. Khách hàng phải quyết định mã hóa dữ liệu của họ ở trạng thái lưu trữ (khi dữ liệu được lưu trữ trên AWS) hay đang truyền tải (khi dữ liệu được di chuyển giữa AWS và khách hàng hoặc giữa các dịch vụ AWS). Khách hàng cũng phải chọn phương thức mã hóa, thuật toán và giải pháp quản lý khóa phù hợp nhất với nhu cầu của mình. AWS cung cấp nhiều dịch vụ và tính năng khác nhau hỗ trợ mã hóa dữ liệu, chẳng hạn như Dịch vụ quản lý khóa AWS (AWS KMS), AWS Certificate Manager (ACM) (ACM) và AWS Encryption SDK5. Người dùng IAM là các thực thể đại diện cho những người hoặc ứng dụng tương tác với tài nguyên và dịch vụ AWS. Khách hàng phải cấp cho người dùng IAM các quyền tối thiểu mà họ cần để thực hiện nhiệm vụ của mình và tránh cấp cho họ quyền truy cập không cần thiết hoặc quá mức. Đây được gọi là nguyên tắc đặc quyền tối thiểu và giúp giảm nguy cơ thực hiện các hành động trái phép hoặc độc hại. Khách hàng có thể sử dụng các chính sách, vai trò, nhóm và ranh giới quyền của IAM để quản lý quyền truy cập của người dùng IAM.', '[{"label": "A", "text_vi": "Vá hệ điều hành Amazon RDS.", "is_correct": false, "analysis_vi": "Sai. Vá hệ điều hành Amazon RDS.: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Nâng cấp firmware của cơ sở hạ tầng mạng.", "is_correct": false, "analysis_vi": "Sai. Nâng cấp firmware của cơ sở hạ tầng mạng. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Quản lý mã hóa dữ liệu.", "is_correct": true, "analysis_vi": "Đúng. Quản lý mã hóa dữ liệu. là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm các nhiệm vụ quản lý mã hóa dữ liệu và cấp quyền truy cập đặc quyền tối thiểu cho người dùng IAM."}, {"label": "D", "text_vi": "Duy trì kiểm soát truy cập vật lý trong AWS Region.", "is_correct": false, "analysis_vi": "Sai. Duy trì kiểm soát truy cập vật lý trong AWS Region. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Cấp quyền truy cập đặc quyền tối thiểu cho người dùng IAM.", "is_correct": true, "analysis_vi": "Đúng. Cấp quyền truy cập đặc quyền tối thiểu cho người dùng IAM. là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, khách hàng chịu trách nhiệm về bảo mật trên đám mây, bao gồm các nhiệm vụ quản lý mã hóa dữ liệu và cấp quyền truy cập đặc quyền tối thiểu cho người dùng IAM."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon RDS", "AWS IAM"]'::jsonb, NOW())
