INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-217', 'practice_283', 'Lớp lưu trữ theo bậc thông minh của Amazon S3 cung cấp những gì?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Lớp lưu trữ Phân bậc thông minh của Amazon S3 giúp tiết kiệm chi phí một cách tự động bằng cách di chuyển các đối tượng giữa các tầng dựa trên những thay đổi về mẫu truy cập. Lớp lưu trữ này được thiết kế cho dữ liệu có kiểu truy cập không xác định hoặc đang thay đổi. Nó có hai tầng truy cập: truy cập thường xuyên và truy cập không thường xuyên. Theo mặc định, các đối tượng được lưu trữ ở cấp truy cập thường xuyên và được chuyển sang cấp truy cập không thường xuyên sau 30 ngày liên tục không có quyền truy cập. Nếu một đối tượng ở tầng truy cập không thường xuyên được truy cập, nó sẽ được chuyển trở lại tầng truy cập thường xuyên. Không có phí truy xuất trong S3 Phân bậc thông minh và không có phí phân bậc bổ sung khi các đối tượng được di chuyển giữa các bậc truy cập trong lớp lưu trữ Phân bậc thông minh S3.', '[{"label": "A", "text_vi": "Thanh toán linh hoạt bằng cách dự trữ dung lượng lưu trữ", "is_correct": false, "analysis_vi": "Sai. Thanh toán linh hoạt bằng cách dự trữ dung lượng lưu trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Lưu giữ dữ liệu lâu dài bằng cách sao chép dữ liệu vào ổ đĩa Amazon Elastic Block Store (Amazon EBS) được mã hóa", "is_correct": false, "analysis_vi": "Sai. Lưu giữ dữ liệu lâu dài bằng cách sao chép dữ liệu vào ổ đĩa Amazon Elastic Block Store (Amazon EBS) được mã hóa: Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Tự động tiết kiệm chi phí bằng cách di chuyển các đối tượng giữa các tầng dựa trên những thay đổi về kiểu truy cập", "is_correct": true, "analysis_vi": "Đúng. Tự động tiết kiệm chi phí bằng cách di chuyển các đối tượng giữa các tầng dựa trên những thay đổi về kiểu truy cập là đáp án chính xác. Lớp lưu trữ Phân bậc thông minh của Amazon S3 giúp tiết kiệm chi phí một cách tự động bằng cách di chuyển các đối tượng giữa các tầng dựa trên những thay đổi về mẫu truy cập."}, {"label": "D", "text_vi": "Lưu trữ an toàn, bền bỉ và chi phí thấp nhất để lưu trữ dữ liệu", "is_correct": false, "analysis_vi": "Sai. Lớp lưu trữ này được thiết kế cho dữ liệu có kiểu truy cập không xác định hoặc đang thay đổi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
