INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-218', 'practice_283', 'Công ty cần xác định ai đã truy cập dịch vụ AWS và hành động nào đã được thực hiện trong một khoảng thời gian nhất định. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng yêu cầu này?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS CloudTrail là dịch vụ cho phép quản trị, tuân thủ, kiểm tra hoạt động và kiểm tra rủi ro đối với tài khoản AWS của bạn. Với CloudTrail, bạn có thể ghi nhật ký, giám sát liên tục và lưu giữ hoạt động tài khoản liên quan đến các hành động trên cơ sở hạ tầng AWS của mình. Bạn có thể sử dụng CloudTrail để xác định ai đã truy cập dịch vụ AWS và hành động nào đã được thực hiện trong một khoảng thời gian nhất định. Amazon CloudWatch, AWS Security Hub và Amazon Inspector là các dịch vụ AWS cung cấp nhiều loại khả năng giám sát và bảo mật khác nhau.', '[{"label": "A", "text_vi": "Amazon CloudWatch", "is_correct": false, "analysis_vi": "Sai. Amazon CloudWatch: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS CloudTrail", "is_correct": true, "analysis_vi": "Đúng. AWS CloudTrail là đáp án chính xác. AWS CloudTrail là dịch vụ cho phép quản trị, tuân thủ, kiểm tra hoạt động và kiểm tra rủi ro đối với tài khoản AWS của bạn."}, {"label": "C", "text_vi": "Trung tâm bảo mật AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm bảo mật AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudWatch", "AWS CloudTrail", "Amazon Inspector"]'::jsonb, NOW())
