INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-219', 'practice_283', 'Trụ cột nào của Khung kiến trúc tối ưu AWS bao gồm mô hình trách nhiệm chung của AWS?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Khung kiến trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành các hệ thống đáng tin cậy, an toàn, hiệu quả và tiết kiệm chi phí trên đám mây. Khung này bao gồm năm trụ cột: hoạt động xuất sắc, hiệu quả hoạt động, độ tin cậy, bảo mật và tối ưu hóa chi phí. Trụ cột bảo mật bao gồm mô hình trách nhiệm chung của AWS, trong đó xác định trách nhiệm bảo mật và tuân thủ của AWS và khách hàng. Bạn có thể tìm hiểu thêm về AWS Well- Architected Framework từ [báo cáo nghiên cứu chuyên sâu này] hoặc [khóa học kỹ thuật số này].', '[{"label": "A", "text_vi": "Hoạt động xuất sắc", "is_correct": false, "analysis_vi": "Sai. Hoạt động xuất sắc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hiệu quả hoạt động", "is_correct": false, "analysis_vi": "Sai. Hiệu quả hoạt động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Bảo mật", "is_correct": true, "analysis_vi": "Đúng. Bảo mật đáp ứng đầy đủ yêu cầu của đề bài. Khung kiến trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành các hệ thống đáng tin cậy, an toàn, hiệu quả và tiết kiệm chi phí trên đám mây."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
