INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-220', 'practice_283', 'Một công ty cần trợ giúp quản lý nhiều tài khoản được liên kết AWS được báo cáo trên hóa đơn tổng hợp. Gói Hỗ trợ AWS nào bao gồm nhân viên trợ giúp AWS mà công ty có thể yêu cầu hỗ trợ?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'AWS Enterprise Support là gói AWS Support bao gồm nhân viên hỗ trợ AWS mà công ty có thể yêu cầu hỗ trợ. Theo trang Gói hỗ trợ AWS, AWS Enterprise Support cung cấp "Người quản lý tài khoản kỹ thuật (TAM) chuyên dụng, người cung cấp dịch vụ hỗ trợ và hướng dẫn để giúp lập kế hoạch và xây dựng các giải pháp bằng cách sử dụng các biện pháp thực hành tốt nhất, điều phối quyền truy cập vào các chuyên gia về chủ đề và chủ động duy trì môi trường AWS của bạn hoạt động lành mạnh."2 AWS Business Support, AWS Developer Support và AWS Basic Support không bao gồm TAM hoặc dịch vụ trợ giúp đặc biệt.', '[{"label": "A", "text_vi": "Hỗ trợ nhà phát triển AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ nhà phát triển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Hỗ trợ doanh nghiệp AWS", "is_correct": true, "analysis_vi": "Đúng. Hỗ trợ doanh nghiệp AWS là đáp án chính xác. AWS Enterprise Support là gói AWS Support bao gồm nhân viên hỗ trợ AWS mà công ty có thể yêu cầu hỗ trợ."}, {"label": "C", "text_vi": "Hỗ trợ kinh doanh của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ kinh doanh của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hỗ trợ cơ bản của AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ cơ bản của AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
