INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-221', 'practice_283', 'Một công ty muốn di chuyển cơ sở dữ liệu từ môi trường tại chỗ sang Amazon RDS. Sau khi quá trình di chuyển hoàn tất, công ty vẫn phải chịu trách nhiệm về nhiệm vụ quản lý nào?', 'Domain 3: Cloud Technology and Services', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Amazon RDS là dịch vụ cơ sở dữ liệu được quản lý, xử lý hầu hết các tác vụ quản trị cơ sở dữ liệu phổ biến, chẳng hạn như cung cấp phần cứng, bảo trì máy chủ, sao lưu và phục hồi, vá lỗi, thay đổi quy mô và sao chép. Tuy nhiên, Amazon RDS không tối ưu hóa ứng dụng tương tác với cơ sở dữ liệu. Công ty vẫn chịu trách nhiệm điều chỉnh hiệu suất, tính bảo mật và tính khả dụng của ứng dụng theo yêu cầu kinh doanh và các phương pháp hay nhất của mình12.', '[{"label": "A", "text_vi": "Quản lý vòng đời phần cứng", "is_correct": false, "analysis_vi": "Sai. Quản lý vòng đời phần cứng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tối ưu hóa ứng dụng", "is_correct": false, "analysis_vi": "Sai. Tuy nhiên, Amazon RDS không tối ưu hóa ứng dụng tương tác với cơ sở dữ liệu."}, {"label": "C", "text_vi": "Bảo trì máy chủ", "is_correct": true, "analysis_vi": "Đúng. Bảo trì máy chủ đáp ứng đầy đủ yêu cầu của đề bài. Amazon RDS là dịch vụ cơ sở dữ liệu được quản lý, xử lý hầu hết các tác vụ quản trị cơ sở dữ liệu phổ biến, chẳng hạn như cung cấp phần cứng, bảo trì máy chủ, sao lưu và phục hồi, vá lỗi, thay đổi quy mô và sao chép."}, {"label": "D", "text_vi": "Cung cấp nguồn, mạng và làm mát", "is_correct": false, "analysis_vi": "Sai. Cung cấp nguồn, mạng và làm mát không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon RDS"]'::jsonb, NOW())
