INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-222', 'practice_283', 'Một công ty lớn có nhiều phòng ban. Mỗi bộ phận đều có tài khoản AWS riêng. Mỗi bộ phận đều đã mua Phiên bản dự trữ của Amazon EC2. Một số bộ phận không sử dụng tất cả Phiên bản dự trữ mà họ đã mua và các bộ phận khác cần nhiều Phiên bản dự trữ hơn mức họ đã mua. Công ty cần quản lý tài khoản AWS cho tất cả các phòng ban để các phòng ban có thể chia sẻ Phiên bản dự trữ. Công ty nên sử dụng dịch vụ hoặc công cụ AWS nào để đáp ứng các yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Dịch vụ điện toán đám mây Amazon EC2', 'AWS Organizations là dịch vụ cho phép bạn hợp nhất nhiều tài khoản AWS thành một tổ chức do bạn tạo và quản lý tập trung. Với AWS Organs, bạn có thể áp dụng chính sách kiểm soát dịch vụ (SCP) trên nhiều tài khoản AWS để hạn chế những dịch vụ và hành động mà người dùng và vai trò có thể truy cập. Bạn cũng có thể sử dụng AWS Organs để kích hoạt các tính năng như thanh toán tổng hợp, quy tắc AWS Config và gói tuân thủ cũng như AWS CloudFormation StackSets trên nhiều tài khoản3. Một trong những lợi ích của việc sử dụng AWS Organs là bạn có thể chia sẻ Phiên bản dự trữ (RI) với tất cả các tài khoản trong tổ chức của mình. Điều này cho phép bạn tận dụng lợi ích thanh toán của RI mà không cần phải chỉ định tài khoản nào sẽ sử dụng chúng4. AWS Systems Manager là dịch vụ cung cấp cho bạn khả năng hiển thị và kiểm soát cơ sở hạ tầng của bạn trên AWS. Cost Explorer là một công cụ cho phép bạn trực quan hóa, hiểu và quản lý chi phí cũng như mức sử dụng AWS của mình theo thời gian. AWS Trusted Advisor là dịch vụ cung cấp hướng dẫn theo thời gian thực để giúp bạn cung cấp tài nguyên của mình theo các biện pháp thực hành tốt nhất của AWS. Không có dịch vụ hoặc công cụ nào trong số này có thể giúp bạn quản lý tài khoản AWS cho tất cả các phòng ban để các phòng ban có thể chia sẻ Phiên bản dự trữ.', '[{"label": "A", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWS Cost Explorer", "is_correct": false, "analysis_vi": "Sai. AWS Cost Explorer: AWS Cost Explorer cung cấp giao diện trực quan để phân tích, hiểu rõ chi phí lịch sử và dự báo chi tiêu AWS trong tương lai lên đến 12 tháng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS Organizations", "is_correct": true, "analysis_vi": "Đúng. AWS Organizations là đáp án chính xác. AWS Organizations là dịch vụ cho phép bạn hợp nhất nhiều tài khoản AWS thành một tổ chức do bạn tạo và quản lý tập trung."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Trusted Advisor", "AWS Cost Explorer", "AWS Organizations", "AWS Secrets Manager"]'::jsonb, NOW())
