INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-223', 'practice_283', 'Một công ty đang chuyển trung tâm dữ liệu tại chỗ sang Đám mây AWS. Công ty phải di chuyển 50 petabyte dữ liệu lưu trữ tệp sang AWS với chi phí hoạt động ít nhất có thể. Công ty nên sử dụng dịch vụ hoặc tài nguyên AWS nào để đáp ứng các yêu cầu này?', 'Domain 2: Security and Compliance', 'Quản lý chi phí & Thanh toán AWS', 'Dịch vụ AWS mà công ty nên sử dụng để đáp ứng các yêu cầu này là A. AWS Snowmobile. AWS Snowmobile là dịch vụ cho phép bạn di chuyển lượng lớn dữ liệu sang AWS bằng cách sử dụng thùng vận chuyển chắc chắn dài 45 foot có thể lưu trữ tới 100 petabyte dữ liệu. AWS Snowmobile được thiết kế cho các tình huống mà bạn cần di chuyển lượng lớn dữ liệu lên đám mây một cách nhanh chóng, an toàn và tiết kiệm chi phí. AWS Snowmobile có chi phí vận hành ít nhất có thể vì giải pháp này giúp loại bỏ nhu cầu mua, đặt cấu hình hoặc quản lý hàng trăm hoặc hàng nghìn thiết bị lưu trữ12. AWS Snowball Edge là dịch vụ cho phép bạn di chuyển dữ liệu sang AWS bằng thiết bị vật lý có thể lưu trữ tới 80 terabyte dữ liệu, đồng thời có khả năng tính toán và lưu trữ để chạy các ứng dụng trên thiết bị. AWS Snowball Edge phù hợp với những tình huống mà kết nối mạng của bạn bị hạn chế hoặc không liên tục hoặc khi chi phí băng thông cao. Tuy nhiên, AWS Snowball Edge có nhiều chi phí vận hành hơn AWS Snowmobile vì bạn cần yêu cầu nhiều thiết bị và truyền dữ liệu của mình lên chúng bằng ứng dụng khách3. AWS Data Exchange là dịch vụ cho phép bạn tìm, đăng ký và sử dụng dữ liệu của bên thứ ba trên đám mây. AWS Data Exchange không phải là dịch vụ di chuyển dữ liệu mà là thị trường dữ liệu cho phép nhà cung cấp dữ liệu và người tiêu dùng dữ liệu trao đổi tập dữ liệu một cách an toàn và hiệu quả4. Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS) là dịch vụ giúp di chuyển cơ sở dữ liệu sang AWS. AWS DMS không di chuyển dữ liệu lưu trữ tệp mà hỗ trợ nhiều nền tảng và công cụ cơ sở dữ liệu khác nhau dưới dạng nguồn và đích5.', '[{"label": "A", "text_vi": "Xe trượt tuyết AWS", "is_correct": true, "analysis_vi": "Đúng. Xe trượt tuyết AWS là đáp án chính xác. AWS Snowmobile là dịch vụ cho phép bạn di chuyển lượng lớn dữ liệu sang AWS bằng cách sử dụng thùng vận chuyển chắc chắn dài 45 foot có thể lưu trữ tới 100 petabyte dữ liệu."}, {"label": "B", "text_vi": "AWS Snowball Edge", "is_correct": false, "analysis_vi": "Sai. AWS Snowball Edge: AWS Snowball là thiết bị lưu trữ vật lý an toàn được vận chuyển tận nơi để di chuyển dữ liệu quy mô terabyte đến petabyte vào hoặc ra khỏi AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trao đổi dữ liệu AWS", "is_correct": false, "analysis_vi": "Sai. Trao đổi dữ liệu AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ di chuyển cơ sở dữ liệu AWS (AWS DMS) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["AWS Snowball"]'::jsonb, NOW())
