INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-224', 'practice_283', 'Một công ty muốn triển khai và quản lý ứng dụng dựa trên Docker trên AWS. Giải pháp nào đáp ứng các yêu cầu này với chi phí hoạt động NHỎ NHẤT?', 'Domain 2: Security and Compliance', 'Quản lý chi phí & Thanh toán AWS', 'Amazon Elastic Container Service (Amazon ECS) là giải pháp đáp ứng các yêu cầu triển khai và quản lý ứng dụng dựa trên Docker trên AWS với chi phí hoạt động ít nhất. Amazon ECS là dịch vụ điều phối bộ chứa được quản lý toàn phần giúp dễ dàng chạy, mở rộng quy mô và bảo mật các ứng dụng bộ chứa Docker trên AWS. Amazon ECS loại bỏ nhu cầu cài đặt, vận hành và mở rộng cơ sở hạ tầng quản lý cụm của riêng bạn. Với lệnh gọi API đơn giản, bạn có thể khởi chạy và dừng các ứng dụng hỗ trợ vùng chứa, truy vấn trạng thái hoàn chỉnh của cụm và truy cập nhiều tính năng quen thuộc như Security Group, Cân bằng tải đàn hồi, khối lượng EBS và vai trò IAM3.', '[{"label": "A", "text_vi": "Trình điều phối Docker mã nguồn mở trên các phiên bản Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Trình điều phối Docker mã nguồn mở trên các phiên bản Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Đồng bộ hóa ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Cơ quan đăng ký vùng chứa đàn hồi của Amazon (Amazon ECR)", "is_correct": false, "analysis_vi": "Sai. Cơ quan đăng ký vùng chứa đàn hồi của Amazon (Amazon ECR) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Dịch vụ container đàn hồi của Amazon (Amazon ECS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ container đàn hồi của Amazon (Amazon ECS) là đáp án chính xác. Amazon Elastic Container Service (Amazon ECS) là giải pháp đáp ứng các yêu cầu triển khai và quản lý ứng dụng dựa trên Docker trên AWS với chi phí hoạt động ít nhất."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
