INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-225', 'practice_283', 'Nhà phát triển nên sử dụng công cụ nào để tích hợp trực tiếp các tính năng dịch vụ AWS vào ứng dụng?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Bộ công cụ phát triển phần mềm AWS (SDK) là một bộ công cụ dành riêng cho nền tảng dành cho nhà phát triển, cho phép họ tích hợp trực tiếp các tính năng dịch vụ AWS vào ứng dụng của mình. AWS SDK cung cấp thư viện, mẫu mã, tài liệu và các tài nguyên khác để giúp nhà phát triển viết mã tương tác với API AWS. SDK AWS hỗ trợ nhiều ngôn ngữ lập trình khác nhau, chẳng hạn như Java, Python, Ruby, .NET, Node.js, Go, v.v. SDK AWS giúp các nhà phát triển truy cập các dịch vụ AWS dễ dàng hơn, chẳng hạn như Amazon S3, Amazon EC2, Amazon DynamoDB, AWS Lambda, v.v., từ ứng dụng của họ. SDK AWS cũng xử lý các tác vụ như xác thực, xử lý lỗi, thử lại và tuần tự hóa dữ liệu để các nhà phát triển có thể tập trung vào logic ứng dụng của họ.', '[{"label": "A", "text_vi": "Bộ phát triển phần mềm AWS", "is_correct": true, "analysis_vi": "Đúng. Bộ phát triển phần mềm AWS là đáp án chính xác. Bộ công cụ phát triển phần mềm AWS (SDK) là một bộ công cụ dành riêng cho nền tảng dành cho nhà phát triển, cho phép họ tích hợp trực tiếp các tính năng dịch vụ AWS vào ứng dụng của mình."}, {"label": "B", "text_vi": "AWS CodeDeploy", "is_correct": false, "analysis_vi": "Sai. AWS CodeDeploy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "AWS Lambda", "is_correct": false, "analysis_vi": "Sai. AWS Lambda: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Lô AWS", "is_correct": false, "analysis_vi": "Sai. Lô AWS: AWS Batch cho phép các nhà phát triển và kỹ sư dễ dàng chạy hàng trăm nghìn công việc xử lý hàng loạt (batch computing) trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Lambda"]'::jsonb, NOW())
