INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-226', 'practice_283', 'Dịch vụ AWS nào cung cấp khả năng lưu trữ cơ sở dữ liệu NoSQL trên Đám mây AWS?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon DynamoDB là dịch vụ cơ sở dữ liệu NoSQL được quản lý toàn phần, cung cấp hiệu suất nhanh và có thể dự đoán được với khả năng mở rộng liền mạch. Nó hỗ trợ cả mô hình dữ liệu khóa-giá trị và tài liệu, đồng thời cho phép bạn tạo các bảng có thể lưu trữ và truy xuất bất kỳ lượng dữ liệu nào cũng như phục vụ mọi mức lưu lượng yêu cầu. Bạn cũng có thể sử dụng Luồng DynamoDB để ghi lại các sự kiện sửa đổi dữ liệu trong bảng DynamoDB. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon DynamoDB", "is_correct": true, "analysis_vi": "Đúng. Amazon DynamoDB là đáp án chính xác. Amazon DynamoDB là dịch vụ cơ sở dữ liệu NoSQL được quản lý toàn phần, cung cấp hiệu suất nhanh và có thể dự đoán được với khả năng mở rộng liền mạch."}, {"label": "C", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": false, "analysis_vi": "Sai. Dịch chuyển đỏ của Amazon: Amazon Redshift là kho dữ liệu đám mây (Data Warehouse) phục vụ phân tích dữ liệu lớn và OLAP ở quy mô petabyte. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
