INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-227', 'practice_283', 'Công ty có thể thực hiện nhiệm vụ nào bằng cách sử dụng các Security Group trên Đám mây AWS?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho các phiên bản Amazon EC2. Chúng có thể được sử dụng để cho phép truy cập vào phiên bản Amazon EC2 chỉ thông qua một cổng cụ thể, chẳng hạn như cổng 22 cho SSH hoặc cổng 80 cho HTTP. Các Security Group không thể từ chối quyền truy cập vào các địa chỉ IP độc hại ở cấp mạng con vì họ chỉ cho phép hoặc từ chối lưu lượng truy cập dựa trên các quy tắc do khách hàng xác định. Để chặn các địa chỉ IP độc hại, khách hàng có thể sử dụng ACL mạng, là tường lửa không trạng thái có thể áp dụng cho mạng con. Các Security Group không thể bảo vệ dữ liệu được Amazon CloudFront lưu vào bộ nhớ đệm vì chúng chỉ áp dụng cho các phiên bản EC2. Để bảo vệ dữ liệu được Amazon CloudFront lưu vào bộ nhớ đệm, khách hàng có thể sử dụng mã hóa, URL đã ký hoặc cookie đã ký. Các Security Group không phải là tường lửa không trạng thái, vì chúng theo dõi trạng thái của lưu lượng và tự động cho phép lưu lượng phản hồi quay trở lại nguồn. Tường lửa không trạng thái không theo dõi trạng thái lưu lượng và yêu cầu các quy tắc cho cả lưu lượng truy cập vào và ra.', '[{"label": "A", "text_vi": "Chỉ cho phép truy cập vào phiên bản Amazon EC2 thông qua một cổng cụ thể.", "is_correct": true, "analysis_vi": "Đúng. Chỉ cho phép truy cập vào phiên bản Amazon EC2 thông qua một cổng cụ thể. là đáp án chính xác. Security Group là tường lửa ảo kiểm soát lưu lượng vào và ra cho các phiên bản Amazon EC2."}, {"label": "B", "text_vi": "Từ chối quyền truy cập vào các địa chỉ IP độc hại ở cấp mạng con.", "is_correct": false, "analysis_vi": "Sai. Từ chối quyền truy cập vào các địa chỉ IP độc hại ở cấp mạng con. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Bảo vệ dữ liệu được Amazon CloudFront lưu vào bộ nhớ đệm.", "is_correct": false, "analysis_vi": "Sai. Các Security Group không thể bảo vệ dữ liệu được Amazon CloudFront lưu vào bộ nhớ đệm vì chúng chỉ áp dụng cho các phiên bản EC2."}, {"label": "D", "text_vi": "Áp dụng tường lửa không trạng thái cho phiên bản Amazon EC2.", "is_correct": false, "analysis_vi": "Sai. Áp dụng tường lửa không trạng thái cho phiên bản Amazon EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon CloudFront"]'::jsonb, NOW())
