INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-228', 'practice_283', 'Mô hình triển khai Đám mây AWS nào sử dụng AWS Outposts như một phần của cơ sở hạ tầng triển khai ứng dụng?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng, dịch vụ, API và công cụ AWS tới cơ sở của khách hàng. Bằng cách cung cấp quyền truy cập cục bộ vào cơ sở hạ tầng do AWS quản lý, AWS Outposts cho phép khách hàng xây dựng và chạy ứng dụng tại cơ sở bằng cách sử dụng cùng giao diện lập trình như trong AWS Region, đồng thời sử dụng tài nguyên điện toán và lưu trữ cục bộ để có độ trễ thấp hơn và nhu cầu xử lý dữ liệu cục bộ. Outpost là một nhóm dung lượng điện toán và lưu trữ AWS được triển khai tại địa điểm của khách hàng. AWS vận hành, giám sát và quản lý năng lực này như một phần của AWS Region. Bạn có thể tạo mạng con trên Outpost của mình và chỉ định chúng khi tạo tài nguyên AWS như phiên bản EC2, ổ đĩa EBS, cụm ECS và phiên bản RDS. Các phiên bản trong mạng con Outpost giao tiếp với các phiên bản khác trong AWS Region bằng địa chỉ IP riêng, tất cả đều nằm trong cùng một VPC. Các giải pháp Outposts cho phép bạn mở rộng và chạy các dịch vụ AWS gốc tại chỗ và có sẵn ở nhiều hệ số dạng khác nhau, từ máy chủ Outposts 1U và 2U đến giá đỡ 42U Outposts và triển khai nhiều giá đỡ. Với AWS Outposts, bạn có thể chạy cục bộ một số dịch vụ AWS và kết nối với nhiều dịch vụ có sẵn ở AWS Region2 cục bộ. AWS Outposts là mô hình triển khai đám mây lai sử dụng AWS Outposts như một phần của cơ sở hạ tầng triển khai ứng dụng. Đám mây lai là môi trường điện toán đám mây sử dụng kết hợp các dịch vụ tại chỗ, đám mây riêng và đám mây công cộng với sự phối hợp giữa các nền tảng. Đám mây lai cung cấp cho doanh nghiệp sự linh hoạt cao hơn, nhiều tùy chọn triển khai hơn và chi phí được tối ưu hóa. Bằng cách sử dụng AWS Outposts, khách hàng có thể hưởng lợi từ cơ sở hạ tầng, dịch vụ, API và công cụ của AWS được quản lý toàn phần tại cơ sở, trong khi vẫn có quyền truy cập vào đầy đủ các dịch vụ AWS có sẵn trong Khu vực để có trải nghiệm kết hợp thực sự nhất quán3.', '[{"label": "A", "text_vi": "Tại chỗ", "is_correct": true, "analysis_vi": "Đúng. Tại chỗ đáp ứng đầy đủ yêu cầu của đề bài. AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng, dịch vụ, API và công cụ AWS tới cơ sở của khách hàng."}, {"label": "B", "text_vi": "Không có máy chủ", "is_correct": false, "analysis_vi": "Sai. Không có máy chủ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Bản địa trên nền tảng đám mây", "is_correct": false, "analysis_vi": "Sai. Bản địa trên nền tảng đám mây không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Lai", "is_correct": false, "analysis_vi": "Sai. Lai không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
