INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-229', 'practice_283', 'Khái niệm Khung kiến trúc tối ưu AWS nào thể hiện khả năng duy trì hoạt động của hệ thống khi hệ thống gặp phải sự cố vận hành?', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Khung kiến trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành hệ thống trên đám mây. Khung này bao gồm năm trụ cột: hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí. Khái niệm độ co giãn thể hiện khả năng của hệ thống trong việc thích ứng với những thay đổi về nhu cầu bằng cách tự động tăng hoặc giảm quy mô tài nguyên. Do đó, câu trả lời đúng là B. Bạn có thể tìm hiểu thêm về AWS Well- Architected Framework và các trụ cột của nó từ trang này.', '[{"label": "A", "text_vi": "Tính nhất quán", "is_correct": false, "analysis_vi": "Sai. Tính nhất quán không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Độ đàn hồi", "is_correct": true, "analysis_vi": "Đúng. Độ đàn hồi là giải pháp đáp ứng yêu cầu. Khung kiến trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành hệ thống trên đám mây. Độ co giãn (Elasticity) là khả năng hệ thống tự động tăng hoặc giảm tài nguyên máy tính chính xác theo nhu cầu tải công việc thực tế."}, {"label": "C", "text_vi": "Độ bền", "is_correct": false, "analysis_vi": "Sai. Độ bền không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Độ trễ", "is_correct": false, "analysis_vi": "Sai. Độ trễ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
