INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-230', 'practice_283', 'Một công ty đang sử dụng các hàm AWS Lambda để xây dựng ứng dụng. Công ty phải chịu trách nhiệm về những nhiệm vụ nào theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, AWS chịu trách nhiệm về tính bảo mật của đám mây, trong khi người dùng chịu trách nhiệm về tính bảo mật trên đám mây. Điều này có nghĩa là AWS quản lý tính bảo mật và bảo trì cơ sở hạ tầng cơ bản, chẳng hạn như máy chủ, mạng và hệ điều hành, trong khi người dùng quản lý tính bảo mật và cấu hình của các tài nguyên cũng như ứng dụng chạy trên AWS. Đối với các hàm AWS Lambda, nhiệm vụ mà người dùng có trách nhiệm là: Thiết lập các quyền IAM để xác định ai có thể chạy các hàm Lambda. IAM là dịch vụ cho phép người dùng quản lý quyền truy cập và quyền đối với tài nguyên và người dùng AWS. Người dùng có thể tạo chính sách, vai trò và người dùng IAM để cấp hoặc từ chối quyền chạy các hàm Lambda, gọi các dịch vụ AWS khác hoặc truy cập tài nguyên AWS từ các hàm Lambda. [Quyền của AWS Lambda] Người thực hành đám mây được chứng nhận AWS - aws.amazon.com Viết mã cho các hàm Lambda để xác định logic ứng dụng. Hàm Lambda là các đơn vị mã có thể được viết bằng bất kỳ ngôn ngữ lập trình được hỗ trợ nào, chẳng hạn như Python, Node.js, Java hoặc Go. Người dùng có thể viết mã cho các hàm Lambda bằng Bảng điều khiển quản lý AWS, Giao diện dòng lệnh AWS (AWS CLI), AWS SDK hoặc bất kỳ trình soạn thảo mã nào mà họ chọn. Người dùng cũng có thể sử dụng Lớp AWS Lambda để chia sẻ và quản lý mã chung cũng như các phần phụ thuộc trên nhiều chức năng. [Tổng quan về AWS Lambda] Người thực hành đám mây được chứng nhận AWS - aws.amazon.com', '[{"label": "A", "text_vi": "Vá các máy chủ nơi chức năng Lambda được triển khai.", "is_correct": false, "analysis_vi": "Sai. Vá các máy chủ nơi chức năng Lambda được triển khai.: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Thiết lập quyền IAM để xác định ai có thể chạy các hàm Lambda.", "is_correct": true, "analysis_vi": "Đúng. Thiết lập quyền IAM để xác định ai có thể chạy các hàm Lambda. là đáp án chính xác. Điều này có nghĩa là AWS quản lý tính bảo mật và bảo trì cơ sở hạ tầng cơ bản, chẳng hạn như máy chủ, mạng và hệ điều hành, trong khi người dùng quản lý tính bảo mật và cấu hình của các tài nguyên cũng như ứng dụng chạy trên AWS."}, {"label": "C", "text_vi": "Viết mã cho các hàm Lambda để xác định logic ứng dụng.", "is_correct": true, "analysis_vi": "Đúng. Viết mã cho các hàm Lambda để xác định logic ứng dụng. là đáp án chính xác. Điều này có nghĩa là AWS quản lý tính bảo mật và bảo trì cơ sở hạ tầng cơ bản, chẳng hạn như máy chủ, mạng và hệ điều hành, trong khi người dùng quản lý tính bảo mật và cấu hình của các tài nguyên cũng như ứng dụng chạy trên AWS."}, {"label": "D", "text_vi": "Triển khai các phiên bản Amazon EC2 để hỗ trợ các hàm Lambda.", "is_correct": false, "analysis_vi": "Sai. Triển khai các phiên bản Amazon EC2 để hỗ trợ các hàm Lambda.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Mở rộng quy mô các hàm Lambda khi tải tăng.", "is_correct": false, "analysis_vi": "Sai. Mở rộng quy mô các hàm Lambda khi tải tăng.: AWS Lambda là dịch vụ điện toán không máy chủ (Serverless), tự động chạy mã phản hồi sự kiện và tính phí chính xác theo mili-giây thực thi, không cần quản lý máy chủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon EC2", "AWS Lambda", "AWS IAM"]'::jsonb, NOW())
