INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-231', 'practice_283', 'Người thực hành đám mây có thể sử dụng những gì để truy xuất các tài liệu tuân thủ và bảo mật AWS và gửi chúng làm bằng chứng cho kiểm toán viên hoặc cơ quan quản lý?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Artifact là dịch vụ cung cấp quyền truy cập theo yêu cầu vào các tài liệu tuân thủ và bảo mật AWS, chẳng hạn như chứng chỉ AWS ISO, báo cáo Ngành thẻ thanh toán (PCI) và báo cáo Kiểm soát tổ chức dịch vụ (SOC). Bạn có thể tải xuống các tài liệu này và gửi chúng làm bằng chứng cho kiểm toán viên hoặc cơ quan quản lý để chứng minh tính bảo mật và tuân thủ của cơ sở hạ tầng và dịch vụ AWS mà bạn sử dụng. AWS Artifact cũng cho phép bạn xem xét, chấp nhận và quản lý các thỏa thuận AWS, chẳng hạn như Phụ lục liên kết kinh doanh (BAA) dành cho những khách hàng tuân theo Đạo luật về trách nhiệm giải trình và cung cấp thông tin bảo hiểm y tế (HIPAA).', '[{"label": "A", "text_vi": "AWS Certificate Manager (ACM)", "is_correct": false, "analysis_vi": "Sai. AWS Certificate Manager (ACM) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Tạo phẩm AWS", "is_correct": true, "analysis_vi": "Đúng. Tạo phẩm AWS là đáp án chính xác. AWS Artifact là dịch vụ cung cấp quyền truy cập theo yêu cầu vào các tài liệu tuân thủ và bảo mật AWS, chẳng hạn như chứng chỉ AWS ISO, báo cáo Ngành thẻ thanh toán (PCI) và báo cáo Kiểm soát tổ chức dịch vụ (SOC)."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["Amazon Inspector", "AWS Secrets Manager", "AWS Artifact"]'::jsonb, NOW())
