INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-232', 'practice_283', 'Một trang web của công ty đang gặp phải các cuộc tấn công DDoS. Dịch vụ AWS nào có thể giúp bảo vệ trang web của công ty trước những cuộc tấn công này?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Shield là dịch vụ bảo vệ DDoS được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS khỏi các cuộc tấn công từ chối dịch vụ (DDoS) phân tán. Các cuộc tấn công DDoS là những nỗ lực độc hại nhằm phá vỡ hoạt động bình thường của một trang web hoặc ứng dụng bằng cách áp đảo nó với một lượng lớn lưu lượng truy cập từ nhiều nguồn. AWS Shield cung cấp hai cấp độ bảo vệ: Tiêu chuẩn và Nâng cao. AWS Shield Standard được kích hoạt tự động cho tất cả khách hàng AWS mà không mất thêm phí. Nó bảo vệ các tài nguyên AWS của bạn, chẳng hạn như Amazon CloudFront, AWS Global Accelerator và Amazon Route 53, khỏi các cuộc tấn công DDoS mạng và lớp vận chuyển phổ biến và thường xuyên xảy ra nhất. AWS Shield Advanced là dịch vụ trả phí tùy chọn cung cấp khả năng bảo vệ bổ sung cho các tài nguyên và ứng dụng AWS của bạn, chẳng hạn như Amazon Elastic Computing Cloud (Amazon EC2), Elastic Load Balancing (ELB), Amazon Simple Storage Service (Amazon S3), Amazon Relational Database Service (Amazon RDS) và AWS Elastic Beanstalk. AWS Shield Advanced cung cấp khả năng phát hiện và giảm thiểu nâng cao, quyền truy cập 24/7 vào Nhóm phản hồi DDoS (DRT) của AWS, khả năng hiển thị và báo cáo theo thời gian thực cũng như bảo vệ chi phí trước các đợt tăng đột biến liên quan đến DDoS trong hóa đơn AWS của bạn12', '[{"label": "A", "text_vi": "Trình quản lý truy cập tài nguyên AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý truy cập tài nguyên AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khuếch đại AWS", "is_correct": false, "analysis_vi": "Sai. Khuếch đại AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Khiên AWS", "is_correct": true, "analysis_vi": "Đúng. Khiên AWS là đáp án chính xác. AWS Shield là dịch vụ bảo vệ DDoS được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS khỏi các cuộc tấn công từ chối dịch vụ (DDoS) phân tán."}, {"label": "D", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "Amazon GuardDuty", "AWS Secrets Manager"]'::jsonb, NOW())
