INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-233', 'practice_283', 'Lớp lưu trữ hoặc dịch vụ AWS nào cung cấp khả năng lưu trữ dữ liệu dài hạn, chi phí thấp?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Amazon S3 Glacier Deep Archive là lớp lưu trữ trong Amazon S3 cung cấp khả năng lưu trữ dữ liệu dài hạn, chi phí thấp nhất cho những dữ liệu hiếm khi được truy cập. AWS Snowball là dịch vụ cung cấp thiết bị vật lý để truyền lượng lớn dữ liệu vào và ra khỏi AWS. Amazon MQ là dịch vụ cung cấp dịch vụ môi giới tin nhắn được quản lý cho Apache ActiveMQ. AWS Storage Gateway là dịch vụ cung cấp lưu trữ đám mây lai cho các ứng dụng tại chỗ.', '[{"label": "A", "text_vi": "Kho lưu trữ sâu Amazon S3 Glacier", "is_correct": true, "analysis_vi": "Đúng. Kho lưu trữ sâu Amazon S3 Glacier là đáp án chính xác. Amazon S3 Glacier Deep Archive là lớp lưu trữ trong Amazon S3 cung cấp khả năng lưu trữ dữ liệu dài hạn, chi phí thấp nhất cho những dữ liệu hiếm khi được truy cập."}, {"label": "B", "text_vi": "Quả cầu tuyết AWS", "is_correct": false, "analysis_vi": "Sai. Quả cầu tuyết AWS: AWS Snowball là thiết bị lưu trữ vật lý an toàn được vận chuyển tận nơi để di chuyển dữ liệu quy mô terabyte đến petabyte vào hoặc ra khỏi AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon MQ", "is_correct": false, "analysis_vi": "Sai. Amazon MQ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway: AWS Storage Gateway kết nối môi trường tại chỗ với lưu trữ đám mây AWS, cung cấp quyền truy cập liền mạch vào S3 và EBS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS Storage Gateway", "AWS Snowball"]'::jsonb, NOW())
