INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-234', 'practice_283', 'Dịch vụ AWS nào được sử dụng để cung cấp mã hóa cho Amazon EBS?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'AWS KMS là dịch vụ được sử dụng để cung cấp mã hóa cho Amazon EBS. AWS KMS là dịch vụ được quản lý cho phép bạn dễ dàng tạo và kiểm soát các khóa mã hóa dùng để mã hóa dữ liệu của mình. Amazon EBS sử dụng AWS KMS để mã hóa và giải mã các ổ đĩa và bản kết xuất nhanh EBS của bạn. Bạn có thể chọn sử dụng CMK do AWS quản lý mặc định hoặc CMK do khách hàng của bạn quản lý để mã hóa. AWS KMS cũng cung cấp các tính năng như xoay vòng khóa, ghi nhật ký kiểm tra và chính sách kiểm soát truy cập để giúp bạn quản lý khóa mã hóa và bảo vệ dữ liệu của mình12. Các dịch vụ khác không được sử dụng để cung cấp mã hóa cho Amazon EBS. AWS Certification Manager là dịch vụ cho phép bạn cung cấp, quản lý và triển khai các chứng chỉ SSL/TLS công khai và riêng tư để sử dụng với các dịch vụ AWS và tài nguyên được kết nối nội bộ của bạn3. AWS Systems Manager là dịch vụ cung cấp giao diện người dùng thống nhất để xem và quản lý tài nguyên AWS của bạn, tự động hóa các tác vụ vận hành chung và áp dụng các chính sách tuân thủ4. AWS Config là dịch vụ cho phép bạn đánh giá, kiểm tra và đánh giá cấu hình tài nguyên AWS của mình.', '[{"label": "A", "text_vi": "AWS Certificate Manager (ACM)", "is_correct": false, "analysis_vi": "Sai. AWS Certificate Manager (ACM) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS KMS", "is_correct": true, "analysis_vi": "Đúng. AWS KMS là giải pháp đáp ứng yêu cầu. AWS KMS là dịch vụ được sử dụng để cung cấp mã hóa cho Amazon EBS. AWS Key Management Service (KMS) giúp tạo, quản lý và kiểm soát các khóa mã hóa dùng để mã hóa dữ liệu trên các dịch vụ AWS."}, {"label": "D", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS KMS", "AWS Secrets Manager"]'::jsonb, NOW())
