INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-235', 'practice_283', 'Dịch vụ hoặc tính năng nào của AWS cho phép người dùng mã hóa dữ liệu ở trạng thái lưu trữ trên Amazon S3?', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Mã hóa phía máy chủ là một tùy chọn mã hóa mà Amazon S3 cung cấp để mã hóa dữ liệu ở trạng thái lưu trữ trên Amazon S3. Với mã hóa phía máy chủ, Amazon S3 mã hóa một đối tượng trước khi lưu nó vào đĩa trong trung tâm dữ liệu của nó và giải mã nó khi bạn tải đối tượng xuống. Bạn có ba tùy chọn mã hóa phía máy chủ để chọn: SSE-S3, SSE-C và SSE-KMS. SSE-S3 sử dụng các khóa được quản lý bởi Amazon S3. SSE-C cho phép bạn quản lý các khóa mã hóa của riêng mình. SSE-KMS sử dụng các khóa được quản lý bởi AWS Key Management Service (AWS KMS)5.', '[{"label": "A", "text_vi": "Chính sách IAM", "is_correct": false, "analysis_vi": "Sai. Chính sách IAM: AWS IAM cho phép quản lý danh tính, phân quyền chi tiết, xác thực đa yếu tố (MFA) và áp dụng nguyên tắc đặc quyền tối thiểu (Least Privilege). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Mã hóa phía máy chủ", "is_correct": true, "analysis_vi": "Đúng. Mã hóa phía máy chủ là đáp án chính xác. Mã hóa phía máy chủ là một tùy chọn mã hóa mà Amazon S3 cung cấp để mã hóa dữ liệu ở trạng thái lưu trữ trên Amazon S3."}, {"label": "C", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Mã hóa phía máy khách", "is_correct": false, "analysis_vi": "Sai. Mã hóa phía máy khách không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "Amazon GuardDuty", "AWS IAM"]'::jsonb, NOW())
