INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-236', 'practice_283', 'Những biện pháp kiểm soát nào là trách nhiệm của cả khách hàng AWS và AWS, theo mô hình trách nhiệm chung của AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Quản lý bản vá và quản lý cấu hình là các biện pháp kiểm soát thuộc trách nhiệm của cả khách hàng AWS và AWS, theo mô hình trách nhiệm chung của AWS. Quản lý bản vá là quá trình áp dụng các bản cập nhật cho phần mềm và ứng dụng để khắc phục các lỗ hổng, lỗi hoặc sự cố về hiệu suất. Quản lý cấu hình là quá trình xác định và duy trì các cài đặt cũng như thông số của hệ thống và ứng dụng để đảm bảo tính nhất quán và độ tin cậy của chúng. AWS chịu trách nhiệm vá lỗi và đặt cấu hình phần mềm cũng như dịch vụ mà mình quản lý, chẳng hạn như cơ sở hạ tầng toàn cầu AWS, bộ điều khiển ảo hóa và các dịch vụ do AWS quản lý. Khách hàng chịu trách nhiệm vá lỗi và đặt cấu hình phần mềm cũng như dịch vụ mà họ quản lý, chẳng hạn như hệ điều hành khách, ứng dụng và dịch vụ do khách hàng AWS quản lý. Kiểm soát vật lý và môi trường là trách nhiệm của AWS, theo mô hình trách nhiệm chung của AWS. Kiểm soát vật lý và môi trường là các biện pháp bảo vệ tính bảo mật vật lý và tính khả dụng của cơ sở hạ tầng toàn cầu AWS, chẳng hạn như nguồn điện, làm mát, chữa cháy và kiểm soát truy cập. AWS chịu trách nhiệm duy trì các biện pháp kiểm soát này và đảm bảo khả năng phục hồi cũng như độ tin cậy của Đám mây AWS. Cấu trúc tài khoản là trách nhiệm của khách hàng, theo mô hình trách nhiệm chung của AWS. Cấu trúc tài khoản là cách khách hàng tổ chức và quản lý tài khoản và tài nguyên AWS của họ, chẳng hạn như sử dụng AWS Organs, người dùng và vai trò IAM, gắn thẻ tài nguyên và tùy chọn thanh toán. Khách hàng chịu trách nhiệm tạo và đặt cấu hình các cấu trúc này cũng như đảm bảo tính bảo mật và quản trị môi trường AWS của họ. Việc lựa chọn AWS Region nơi lưu trữ dữ liệu là trách nhiệm của khách hàng, theo mô hình trách nhiệm chung của AWS. AWS Region là các khu vực địa lý bao gồm nhiều Availability Zone (AZ) bị cô lập. Khách hàng có thể chọn AWS Region nào để lưu trữ dữ liệu và chạy ứng dụng của mình, tùy thuộc vào yêu cầu về độ trễ, mức độ tuân thủ và chi phí. Khách hàng có trách nhiệm lựa chọn AWS Region phù hợp và đảm bảo chủ quyền dữ liệu cũng như tuân thủ quy định đối với dữ liệu của họ.', '[{"label": "A", "text_vi": "Kiểm soát vật lý và môi trường", "is_correct": false, "analysis_vi": "Sai. Kiểm soát vật lý và môi trường không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Quản lý bản vá", "is_correct": true, "analysis_vi": "Đúng. Quản lý bản vá là đáp án chính xác. Quản lý bản vá và quản lý cấu hình là các biện pháp kiểm soát thuộc trách nhiệm của cả khách hàng AWS và AWS, theo mô hình trách nhiệm chung của AWS."}, {"label": "C", "text_vi": "Quản lý cấu hình", "is_correct": true, "analysis_vi": "Đúng. Quản lý cấu hình là đáp án chính xác. Quản lý bản vá và quản lý cấu hình là các biện pháp kiểm soát thuộc trách nhiệm của cả khách hàng AWS và AWS, theo mô hình trách nhiệm chung của AWS."}, {"label": "D", "text_vi": "Cấu trúc tài khoản", "is_correct": false, "analysis_vi": "Sai. Cấu trúc tài khoản không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Lựa chọn AWS Region nơi lưu trữ dữ liệu", "is_correct": false, "analysis_vi": "Sai. Lựa chọn AWS Region nơi lưu trữ dữ liệu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
