INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-237', 'practice_283', 'Nguyên tắc thiết kế Đám mây AWS nào sau đây? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Câu trả lời đúng là B và D vì việc đưa ra quyết định dựa trên dữ liệu để xác định hệ thống thử nghiệm và thiết kế kiến trúc đám mây ở quy mô sản xuất là nguyên tắc thiết kế Đám mây AWS. Đưa ra quyết định dựa trên dữ liệu để xác định thiết kế kiến ​​trúc đám mây có nghĩa là người dùng nên thu thập và phân tích dữ liệu từ các tài nguyên và ứng dụng AWS của mình để tối ưu hóa hiệu suất, tính khả dụng, bảo mật và chi phí. Hệ thống thử nghiệm ở quy mô sản xuất có nghĩa là người dùng nên mô phỏng các tình huống và điều kiện tải trong thế giới thực để xác thực chức năng, độ tin cậy và khả năng mở rộng của hệ thống của họ. Các tùy chọn khác không chính xác vì chúng không phải là nguyên tắc thiết kế của Đám mây AWS. Trả trước cho tài nguyên điện toán có nghĩa là người dùng phải đầu tư nhiều vào trung tâm dữ liệu và máy chủ trước khi biết họ sẽ sử dụng chúng như thế nào. Đây không phải là nguyên tắc thiết kế đám mây mà là mô hình CNTT truyền thống. Nhấn mạnh các quy trình thủ công để cho phép thay đổi có nghĩa là người dùng phải dựa vào sự can thiệp và phối hợp của con người để thực hiện các nhiệm vụ vận hành và cập nhật. Đây không phải là nguyên tắc thiết kế đám mây mà là nguồn gốc của sự thiếu hiệu quả và sai sót. Việc tinh chỉnh các quy trình vận hành không thường xuyên có nghĩa là người dùng phải tuân theo các phương pháp và thực tiễn giống nhau mà không thích ứng với nhu cầu và phản hồi đang thay đổi. Đây không phải là nguyên tắc thiết kế đám mây mà là trở ngại cho sự đổi mới và cải tiến.', '[{"label": "A", "text_vi": "Thanh toán trước cho tài nguyên máy tính.", "is_correct": false, "analysis_vi": "Sai. Thanh toán trước cho tài nguyên máy tính. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Đưa ra quyết định dựa trên dữ liệu để xác định thiết kế kiến ​​trúc đám mây.", "is_correct": true, "analysis_vi": "Đúng. Đưa ra quyết định dựa trên dữ liệu để xác định thiết kế kiến ​​trúc đám mây. là đáp án chính xác. Câu trả lời đúng là B và D vì việc đưa ra quyết định dựa trên dữ liệu để xác định hệ thống thử nghiệm và thiết kế kiến trúc đám mây ở quy mô sản xuất là nguyên tắc thiết kế Đám mây AWS."}, {"label": "C", "text_vi": "Nhấn mạnh các quy trình thủ công để cho phép thay đổi.", "is_correct": false, "analysis_vi": "Sai. Nhấn mạnh các quy trình thủ công để cho phép thay đổi. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hệ thống thử nghiệm ở quy mô sản xuất.", "is_correct": true, "analysis_vi": "Đúng. Hệ thống thử nghiệm ở quy mô sản xuất. là đáp án chính xác. Câu trả lời đúng là B và D vì việc đưa ra quyết định dựa trên dữ liệu để xác định hệ thống thử nghiệm và thiết kế kiến trúc đám mây ở quy mô sản xuất là nguyên tắc thiết kế Đám mây AWS."}, {"label": "E", "text_vi": "Tinh chỉnh các quy trình vận hành không thường xuyên.", "is_correct": false, "analysis_vi": "Sai. Tinh chỉnh các quy trình vận hành không thường xuyên. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
