INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-238', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào cung cấp cho người dùng khả năng nắm bắt thông tin về lưu lượng mạng trong VPC?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Nhật ký lưu lượng VPC là tính năng cho phép bạn nắm bắt thông tin về lưu lượng IP đến và đi từ các giao diện mạng trong VPC của bạn. Dữ liệu nhật ký luồng có thể được xuất bản lên Amazon CloudWatch Logs, Amazon S3 hoặc Amazon Kinesis Data Firehose. Bạn có thể sử dụng Nhật ký lưu lượng VPC để chẩn đoán sự cố mạng, giám sát mẫu lưu lượng truy cập, phát hiện các điểm bất thường về bảo mật và tuân thủ các yêu cầu kiểm tra34.', '[{"label": "A", "text_vi": "Nhật ký luồng VPC", "is_correct": true, "analysis_vi": "Đúng. Nhật ký luồng VPC là đáp án chính xác. Nhật ký lưu lượng VPC là tính năng cho phép bạn nắm bắt thông tin về lưu lượng IP đến và đi từ các giao diện mạng trong VPC của bạn."}, {"label": "B", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon Inspector: Amazon Inspector là dịch vụ quản lý lỗ hổng bảo mật tự động, quét các lỗ hổng phần mềm và phát hiện phơi nhiễm mạng ngoài ý muốn trên EC2, ECR và Lambda. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Bảng lộ trình VPC", "is_correct": false, "analysis_vi": "Sai. Bảng lộ trình VPC: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "AWS CloudTrail", "is_correct": false, "analysis_vi": "Sai. AWS CloudTrail: AWS CloudTrail ghi nhật ký và giám sát toàn bộ hoạt động gọi API của tài khoản AWS, phục vụ quản trị, kiểm toán bảo mật và tuân thủ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS CloudTrail", "Amazon Inspector", "Amazon VPC"]'::jsonb, NOW())
