INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-239', 'practice_283', 'Một công ty cần lưu trữ máy chủ web trên phiên bản Amazon EC2 trong ít nhất 1 năm. Máy chủ web không thể chịu được sự gián đoạn. Tùy chọn mua phiên bản EC2 nào sẽ đáp ứng các yêu cầu này với chi phí hiệu quả nhất?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Tùy chọn mua phiên bản EC2 tiết kiệm chi phí nhất dành cho công ty cần lưu trữ máy chủ web trên phiên bản Amazon EC2 trong ít nhất 1 năm và không thể chịu được tình trạng gián đoạn là Phiên bản dự trữ trả trước một phần. Phiên bản dự trữ là mô hình định giá có mức giảm giá đáng kể so với Phiên bản theo yêu cầu để đổi lấy cam kết sử dụng lượng công suất điện toán cụ thể trong một khoảng thời gian cố định (1 hoặc 3 năm). Phiên bản dự trữ trả trước một phần yêu cầu khách hàng thanh toán trước một phần tổng chi phí và chi phí còn lại theo hình thức trả góp hàng tháng trong thời hạn. Tùy chọn này cung cấp mức giá hiệu dụng theo giờ thấp hơn so với Phiên bản dự trữ không trả trước, không yêu cầu thanh toán trả trước nhưng có khoản thanh toán hàng tháng cao hơn. Phiên bản theo yêu cầu và Phiên bản giao ngay không phải là lựa chọn tốt nhất cho công ty. Phiên bản theo yêu cầu là mô hình định giá mang lại sự linh hoạt nhất và không cần cam kết dài hạn nhưng có mức giá theo giờ cao nhất. Phiên bản Spot là mô hình định giá mang lại chi phí thấp nhất nhưng có thể bị gián đoạn dựa trên cung và cầu34', '[{"label": "A", "text_vi": "Phiên bản theo yêu cầu", "is_correct": false, "analysis_vi": "Sai. Tùy chọn mua phiên bản EC2 tiết kiệm chi phí nhất dành cho công ty cần lưu trữ máy chủ web trên phiên bản Amazon EC2 trong ít nhất 1 năm và không thể chịu được tình trạng gián đoạn là Phiên bản dự trữ trả trước một phần."}, {"label": "B", "text_vi": "Phiên bản dự trữ trả trước một phần", "is_correct": true, "analysis_vi": "Đúng. Phiên bản dự trữ trả trước một phần là đáp án chính xác. Tùy chọn mua phiên bản EC2 tiết kiệm chi phí nhất dành cho công ty cần lưu trữ máy chủ web trên phiên bản Amazon EC2 trong ít nhất 1 năm và không thể chịu được tình trạng gián đoạn là Phiên bản dự trữ trả trước một phần."}, {"label": "C", "text_vi": "Phiên bản Spot", "is_correct": false, "analysis_vi": "Sai. Tùy chọn mua phiên bản EC2 tiết kiệm chi phí nhất dành cho công ty cần lưu trữ máy chủ web trên phiên bản Amazon EC2 trong ít nhất 1 năm và không thể chịu được tình trạng gián đoạn là Phiên bản dự trữ trả trước một phần."}, {"label": "D", "text_vi": "Không có phiên bản dự trữ trả trước", "is_correct": false, "analysis_vi": "Sai. Tùy chọn mua phiên bản EC2 tiết kiệm chi phí nhất dành cho công ty cần lưu trữ máy chủ web trên phiên bản Amazon EC2 trong ít nhất 1 năm và không thể chịu được tình trạng gián đoạn là Phiên bản dự trữ trả trước một phần."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
