INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-240', 'practice_283', 'Dịch vụ AWS nào cung cấp tính năng thanh toán tổng hợp?', 'Domain 4: Billing, Pricing and Support', 'Billing, Pricing and Support', 'AWS Organizations là dịch vụ cho phép bạn hợp nhất nhiều tài khoản AWS thành một tổ chức do bạn tạo và quản lý tập trung. Với AWS Organs, bạn có thể tạo một phương thức thanh toán duy nhất cho tất cả tài khoản AWS trong tổ chức của mình thông qua thanh toán tổng hợp. Thanh toán tổng hợp cho phép bạn xem tổng hợp các khoản phí AWS mà tất cả tài khoản trong tổ chức của bạn phải chịu, cũng như nhận báo cáo chi phí chi tiết cho từng tài khoản AWS riêng lẻ được liên kết với tổ chức của bạn. AWS Artifact là dịch vụ cung cấp quyền truy cập theo yêu cầu vào các báo cáo tuân thủ và bảo mật của AWS cũng như các thỏa thuận trực tuyến chọn lọc. AWS Budgets là dịch vụ cho phép bạn lập kế hoạch sử dụng dịch vụ, chi phí dịch vụ và đặt trước phiên bản. AWS Trusted Advisor là dịch vụ cung cấp hướng dẫn theo thời gian thực để giúp bạn cung cấp tài nguyên của mình theo các biện pháp thực hành tốt nhất của AWS. Không có dịch vụ hoặc công cụ nào trong số này cung cấp tính năng thanh toán tổng hợp.', '[{"label": "A", "text_vi": "Hiện vật AWS", "is_correct": false, "analysis_vi": "Sai. Hiện vật AWS: AWS Artifact là cổng thông tin cung cấp quyền truy cập theo yêu cầu vào các báo cáo kiểm toán bảo mật và tuân thủ của AWS (SOC, PCI-DSS, ISO). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Ngân sách AWS", "is_correct": false, "analysis_vi": "Sai. Ngân sách AWS: AWS Budgets cho phép thiết lập ngưỡng ngân sách tùy chỉnh và gửi thông báo hoặc kích hoạt hành động tự động khi chi phí dự kiến vượt ngưỡng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS Organizations", "is_correct": true, "analysis_vi": "Đúng. AWS Organizations là đáp án chính xác. AWS Organizations là dịch vụ cho phép bạn hợp nhất nhiều tài khoản AWS thành một tổ chức do bạn tạo và quản lý tập trung."}, {"label": "D", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. AWS Trusted Advisor: AWS Trusted Advisor quét toàn bộ tài khoản AWS và đưa ra khuyến nghị tối ưu theo 5 trụ cột: Chi phí, Hiệu năng, Bảo mật, Khả năng chịu lỗi và Giới hạn dịch vụ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Trusted Advisor", "AWS Budgets", "AWS Organizations", "AWS Artifact"]'::jsonb, NOW())
