INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-241', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào cung cấp bảo mật cho VPC bằng cách hoạt động như tường lửa để kiểm soát lưu lượng vào và ra khỏi mạng con?', 'Domain 2: Security and Compliance', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'Network ACL (mạng ACL) là một tính năng hoạt động như tường lửa để kiểm soát lưu lượng vào và ra một hoặc nhiều mạng con trong đám mây riêng ảo (VPC). ACL mạng có thể được định cấu hình bằng các quy tắc cho phép hoặc từ chối lưu lượng truy cập dựa trên địa chỉ IP, cổng và giao thức nguồn và đích1. Trung tâm bảo mật AWS là dịch vụ cung cấp cái nhìn toàn diện về trạng thái bảo mật của tài khoản và tài nguyên AWS2. Security Group là các tính năng hoạt động như tường lửa để kiểm soát lưu lượng ở cấp phiên bản3. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web khỏi các cách khai thác web phổ biến4. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Trung tâm bảo mật AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm bảo mật AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Security Group", "is_correct": false, "analysis_vi": "Sai. Security Group: Security Group là tường lửa ảo ở cấp instance, hoạt động có trạng thái (Stateful) và chỉ cấu hình các quy tắc cho phép (Allow rules). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "ACL mạng", "is_correct": true, "analysis_vi": "Đúng. ACL mạng là đáp án chính xác. Network ACL (mạng ACL) là một tính năng hoạt động như tường lửa để kiểm soát lưu lượng vào và ra một hoặc nhiều mạng con trong đám mây riêng ảo (VPC)."}, {"label": "D", "text_vi": "AWSWAF", "is_correct": false, "analysis_vi": "Sai. AWSWAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Cặp dịch vụ bảo mật hay gặp: GuardDuty (phát hiện mối đe dọa thông minh), Inspector (quét lỗ hổng phần mềm trên EC2/Lambda), WAF (tường lửa web lớp 7)."]'::jsonb, '[{"term": "phát hiện mối đe dọa", "points_to": "Amazon GuardDuty"}]'::jsonb, '["AWS WAF", "Amazon VPC"]'::jsonb, NOW())
