INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-242', 'practice_283', 'Một công ty thương mại điện tử muốn phân phối lưu lượng giữa các phiên bản Amazon EC2 lưu trữ trang web của công ty đó. Dịch vụ hoặc tài nguyên AWS nào sẽ đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Đây là dịch vụ hoặc tài nguyên AWS sẽ đáp ứng yêu cầu phân phối lưu lượng giữa các phiên bản Amazon EC2 lưu trữ trang web. Cân bằng tải ứng dụng là một loại Cân bằng tải đàn hồi giúp phân phối lưu lượng truy cập ứng dụng đến trên nhiều mục tiêu, chẳng hạn như phiên bản Amazon EC2, bộ chứa, địa chỉ IP và hàm Lambda. Cân bằng tải ứng dụng hoạt động ở lớp ứng dụng (lớp 7) của mô hình OSI và hỗ trợ các tính năng nâng cao như định tuyến dựa trên đường dẫn, định tuyến dựa trên máy chủ, kiểm tra tình trạng và chấm dứt SSL. Bạn có thể tìm hiểu thêm về Cân bằng tải ứng dụng từ [trang web này] hoặc [khóa học kỹ thuật số này].', '[{"label": "A", "text_vi": "Cân bằng tải ứng dụng", "is_correct": true, "analysis_vi": "Đúng. Cân bằng tải ứng dụng là đáp án chính xác. Cân bằng tải ứng dụng là một loại Cân bằng tải đàn hồi giúp phân phối lưu lượng truy cập ứng dụng đến trên nhiều mục tiêu, chẳng hạn như phiên bản Amazon EC2, bộ chứa, địa chỉ IP và hàm Lambda."}, {"label": "B", "text_vi": "AWS WAF", "is_correct": false, "analysis_vi": "Sai. AWS WAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "AWS CloudHSM", "is_correct": false, "analysis_vi": "Sai. AWS CloudHSM: AWS CloudHSM cung cấp thiết bị bảo mật phần cứng chuyên dụng (FIPS 140-2 Level 3) do khách hàng độc quyền kiểm soát để quản lý khóa mã hóa. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Kết nối trực tiếp AWS", "is_correct": false, "analysis_vi": "Sai. Kết nối trực tiếp AWS: AWS Direct Connect thiết lập kết nối mạng chuyên dụng riêng biệt từ hạ tầng on-premises tới AWS, bỏ qua mạng Internet công cộng để có băng thông ổn định. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "AWS WAF", "AWS Direct Connect"]'::jsonb, NOW())
