INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-243', 'practice_283', 'Dịch vụ nào là dịch vụ lưu trữ dữ liệu trong bộ nhớ của AWS?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon ElastiCache là dịch vụ cung cấp các dịch vụ bộ nhớ đệm và lưu trữ dữ liệu trong bộ nhớ được quản lý toàn phần, mang lại thời gian phản hồi dưới một phần nghìn giây cho các ứng dụng. Bạn có thể sử dụng Amazon ElastiCache để cải thiện hiệu suất ứng dụng của mình bằng cách truy xuất dữ liệu từ các kho lưu trữ dữ liệu trong bộ nhớ, có tốc độ nhanh, được quản lý, thay vì dựa hoàn toàn vào cơ sở dữ liệu trên ổ đĩa có tốc độ chậm hơn. Amazon Aurora là dịch vụ cơ sở dữ liệu quan hệ kết hợp hiệu suất và tính khả dụng của cơ sở dữ liệu thương mại cao cấp với sự đơn giản và tiết kiệm chi phí của cơ sở dữ liệu nguồn mở. Amazon RDS là dịch vụ giúp bạn dễ dàng thiết lập, vận hành và mở rộng quy mô cơ sở dữ liệu quan hệ trên đám mây. Amazon DynamoDB là cơ sở dữ liệu tài liệu và khóa-giá trị mang lại hiệu suất mili giây một chữ số ở mọi quy mô. Không có dịch vụ nào trong số này là dịch vụ lưu trữ dữ liệu trong bộ nhớ.', '[{"label": "A", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon ElastiCache", "is_correct": true, "analysis_vi": "Đúng. Amazon ElastiCache là đáp án chính xác. Amazon ElastiCache là dịch vụ cung cấp các dịch vụ bộ nhớ đệm và lưu trữ dữ liệu trong bộ nhớ được quản lý toàn phần, mang lại thời gian phản hồi dưới một phần nghìn giây cho các ứng dụng."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
