INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-244', 'practice_283', 'Theo mô hình trách nhiệm chung của AWS, ai chịu trách nhiệm về lớp ảo hóa cho đến bảo mật vật lý của các cơ sở nơi dịch vụ AWS vận hành?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Theo mô hình trách nhiệm chung của AWS, AWS chịu trách nhiệm về tính bảo mật của đám mây, bao gồm lớp ảo hóa cho đến bảo mật vật lý của các cơ sở nơi dịch vụ AWS hoạt động1. Khách hàng chịu trách nhiệm về tính bảo mật trên đám mây, bao gồm cấu hình và quản lý các tài nguyên và ứng dụng AWS mà họ sử dụng1.', '[{"label": "A", "text_vi": "Đây là trách nhiệm duy nhất của khách hàng.", "is_correct": false, "analysis_vi": "Sai. Đây là trách nhiệm duy nhất của khách hàng. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Đó là trách nhiệm duy nhất của AWS.", "is_correct": true, "analysis_vi": "Đúng. Đó là trách nhiệm duy nhất của AWS. là đáp án chính xác. Theo mô hình trách nhiệm chung của AWS, AWS chịu trách nhiệm về tính bảo mật của đám mây, bao gồm lớp ảo hóa cho đến bảo mật vật lý của các cơ sở nơi dịch vụ AWS hoạt động1."}, {"label": "C", "text_vi": "Đó là trách nhiệm chung giữa AWS và khách hàng.", "is_correct": false, "analysis_vi": "Sai. Đó là trách nhiệm chung giữa AWS và khách hàng.: Mô hình trách nhiệm chung: AWS chịu trách nhiệm ''Bảo mật CỦA đám mây'' (hạ tầng, máy chủ, mạng vật lý), Khách hàng chịu trách nhiệm ''Bảo mật TRONG đám mây'' (dữ liệu, IAM, hệ điều hành). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Cấp gói AWS Support của khách hàng xác định ai quản lý cấu hình.", "is_correct": false, "analysis_vi": "Sai. Cấp gói AWS Support của khách hàng xác định ai quản lý cấu hình.: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '[]'::jsonb, NOW())
