INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-245', 'practice_283', 'Một công ty muốn đảm bảo rằng hai phiên bản Amazon EC2 nằm trong các trung tâm dữ liệu riêng biệt với độ trễ giao tiếp giữa các trung tâm dữ liệu ở mức tối thiểu. Làm thế nào công ty có thể đáp ứng được yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Câu trả lời đúng là B vì đặt các phiên bản EC2 ở hai Availability Zone (AZ) riêng biệt trong cùng AWS Region là cách tốt nhất để đáp ứng yêu cầu. Availability Zone (AZ) là các vị trí biệt lập trong AWS Region có nguồn điện, khả năng làm mát và kết nối mạng độc lập. Người dùng có thể khởi chạy tài nguyên của mình, chẳng hạn như phiên bản Amazon EC2, trong nhiều Availability Zone (AZ) để tăng khả năng chịu lỗi và khả năng phục hồi cho ứng dụng của họ. Các Availability Zone (AZ) trong cùng AWS Region được kết nối với mạng có độ trễ thấp, thông lượng cao và có tính dự phòng cao. Các lựa chọn khác không chính xác vì chúng không phải là cách tốt nhất để đáp ứng yêu cầu. Việc đặt các phiên bản EC2 ở hai AWS Region riêng biệt được kết nối bằng kết nối ngang hàng VPC không phải là cách tốt nhất để đáp ứng yêu cầu vì các AWS Region phân tán về mặt địa lý và có thể có độ trễ liên lạc giữa chúng cao hơn so với các Availability Zone (AZ) trong cùng AWS Region. Kết nối ngang hàng VPC là kết nối mạng giữa hai VPC cho phép người dùng định tuyến lưu lượng truy cập giữa chúng bằng địa chỉ IP riêng. Việc đặt một phiên bản EC2 tại cơ sở và phiên bản còn lại trong AWS Region, sau đó kết nối chúng bằng kết nối AWS VPN không phải là cách tốt nhất để đáp ứng yêu cầu vì tại chỗ và AWS Region bị phân tán về mặt địa lý và có thể có độ trễ liên lạc giữa chúng cao hơn so với các Availability Zone (AZ) trong cùng AWS Region. Kết nối AWS VPN là kết nối an toàn và được mã hóa giữa mạng của người dùng và VPC của họ. Việc đặt cả hai phiên bản EC2 vào một nhóm vị trí dành cho băng thông chuyên dụng không phải là cách tốt nhất để đáp ứng yêu cầu vì nhóm vị trí là một nhóm hợp lý các phiên bản trong một Availability Zone (AZ) duy nhất cho phép người dùng khởi chạy các phiên bản có đặc điểm hiệu suất cụ thể. Nhóm vị trí không đảm bảo rằng các phiên bản nằm trong các trung tâm dữ liệu riêng biệt và nhóm này không cung cấp khả năng liên lạc có độ trễ thấp giữa các phiên bản trong các Availability Zone (AZ) khác nhau.', '[{"label": "A", "text_vi": "Đặt các phiên bản EC2 vào hai AWS Region riêng biệt được kết nối bằng kết nối ngang hàng VPC.", "is_correct": false, "analysis_vi": "Sai. Đặt các phiên bản EC2 vào hai AWS Region riêng biệt được kết nối bằng kết nối ngang hàng VPC.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Đặt các phiên bản EC2 vào hai Availability Zone (AZ) riêng biệt trong cùng một AWS Region.", "is_correct": true, "analysis_vi": "Đúng. Đặt các phiên bản EC2 vào hai Availability Zone (AZ) riêng biệt trong cùng một AWS Region. là đáp án chính xác. Câu trả lời đúng là B vì đặt các phiên bản EC2 ở hai Availability Zone (AZ) riêng biệt trong cùng AWS Region là cách tốt nhất để đáp ứng yêu cầu."}, {"label": "C", "text_vi": "Đặt một phiên bản EC2 tại cơ sở và phiên bản còn lại trong AWS Region. Sau đó kết nối chúng bằng cách sử dụng kết nối AWS VPN.", "is_correct": false, "analysis_vi": "Sai. Đặt một phiên bản EC2 tại cơ sở và phiên bản còn lại trong AWS Region. Sau đó kết nối chúng bằng cách sử dụng kết nối AWS VPN.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Đặt cả hai phiên bản EC2 vào một nhóm vị trí để có băng thông chuyên dụng.", "is_correct": false, "analysis_vi": "Sai. Đặt cả hai phiên bản EC2 vào một nhóm vị trí để có băng thông chuyên dụng.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon VPC", "AWS Direct Connect"]'::jsonb, NOW())
