INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-246', 'practice_283', 'Trụ cột nào của Khung kiến trúc tối ưu AWS tập trung vào khả năng chạy khối lượng công việc một cách hiệu quả, hiểu rõ hơn về hoạt động và liên tục cải tiến các quy trình và thủ tục hỗ trợ?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Khung kiến trúc tối ưu AWS là một tập hợp các biện pháp thực hành và hướng dẫn tốt nhất để thiết kế và vận hành hệ thống trên đám mây. Khung này bao gồm năm trụ cột: hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí. Trụ cột vận hành xuất sắc tập trung vào khả năng xử lý khối lượng công việc một cách hiệu quả, hiểu rõ hơn về hoạt động và liên tục cải tiến các quy trình và thủ tục hỗ trợ. Do đó, câu trả lời đúng là C. Bạn có thể tìm hiểu thêm về Khung kiến ​​trúc tối ưu AWS và các trụ cột của nó từ trang này.', '[{"label": "A", "text_vi": "Tối ưu hóa chi phí", "is_correct": false, "analysis_vi": "Sai. Tối ưu hóa chi phí không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Hoạt động xuất sắc", "is_correct": true, "analysis_vi": "Đúng. Hoạt động xuất sắc là đáp án chính xác. Khung này bao gồm năm trụ cột: hoạt động xuất sắc, bảo mật, độ tin cậy, hiệu quả hoạt động và tối ưu hóa chi phí."}, {"label": "D", "text_vi": "Hiệu quả hoạt động", "is_correct": false, "analysis_vi": "Sai. Hiệu quả hoạt động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Ghi nhớ các ngưỡng SLA phản hồi: Business (<1h cho production down, 24/7 phone/chat/email), Enterprise (<15m cho mission-critical, có TAM)."]'::jsonb, '[{"term": "support plan", "points_to": "Developer / Business / Enterprise"}]'::jsonb, '[]'::jsonb, NOW())
