INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-247', 'practice_283', 'Công ty đang sử dụng Amazon RDS có trách nhiệm gì?', 'Domain 2: Security and Compliance', 'Mô hình trách nhiệm chung (Shared Responsibility Model)', 'Câu trả lời đúng là B vì chính sách AWS IAM có thể được sử dụng để kiểm soát quyền truy cập quản trị vào dịch vụ Amazon RDS. Các tùy chọn khác không chính xác vì chúng là trách nhiệm của AWS chứ không phải công ty đang sử dụng Amazon RDS. AWS quản lý việc cung cấp, đi cáp, cài đặt và vá lỗi cơ sở hạ tầng cơ bản cho Amazon RDS.', '[{"label": "A", "text_vi": "Cung cấp cơ sở hạ tầng cơ bản.", "is_correct": false, "analysis_vi": "Sai. Cung cấp cơ sở hạ tầng cơ bản. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tạo chính sách IAM để kiểm soát quyền truy cập quản trị vào dịch vụ.", "is_correct": true, "analysis_vi": "Đúng. Tạo chính sách IAM để kiểm soát quyền truy cập quản trị vào dịch vụ. là đáp án chính xác. Câu trả lời đúng là B vì chính sách AWS IAM có thể được sử dụng để kiểm soát quyền truy cập quản trị vào dịch vụ Amazon RDS."}, {"label": "C", "text_vi": "Lắp đặt cáp để kết nối phần cứng dùng cho tính toán và lưu trữ.", "is_correct": false, "analysis_vi": "Sai. Lắp đặt cáp để kết nối phần cứng dùng cho tính toán và lưu trữ. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Cài đặt và vá lỗi hệ điều hành RDS.", "is_correct": false, "analysis_vi": "Sai. Cài đặt và vá lỗi hệ điều hành RDS.: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Nguyên tắc vàng: AWS quản lý ''Bảo mật CỦA đám mây'' (phần cứng, hạ tầng vật lý), Khách hàng quản lý ''Bảo mật TRONG đám mây'' (dữ liệu, cấu hình IAM, OS)."]'::jsonb, '[{"term": "trách nhiệm của AWS", "points_to": "Hạ tầng vật lý, data center, ảo hóa"}]'::jsonb, '["Amazon RDS", "AWS IAM", "AWS Direct Connect"]'::jsonb, NOW())
