INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-248', 'practice_283', 'Tính năng AWS nào cung cấp nền tảng miễn phí để người dùng AWS tham gia các nhóm cộng đồng, đặt câu hỏi, tìm câu trả lời và đọc các bài viết do cộng đồng tạo ra về các biện pháp thực hành tốt nhất?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'AWS re:Post là nền tảng miễn phí để người dùng AWS tham gia các nhóm cộng đồng, đặt câu hỏi, tìm câu trả lời và đọc các bài viết do cộng đồng tạo ra về các phương pháp hay nhất. AWS re:Post là nền tảng truyền thông xã hội kết nối người dùng AWS với nhau và với các chuyên gia AWS. Người dùng có thể tạo bài đăng, nhận xét về bài đăng, theo dõi chủ đề và tham gia các nhóm liên quan đến dịch vụ, giải pháp và trường hợp sử dụng AWS. AWS re:Post cũng có các nguồn cấp dữ liệu sự kiện trực tiếp, câu chuyện cộng đồng và hồ sơ AWS Hero. AWS re:Post là một cách tuyệt vời để học hỏi từ cộng đồng AWS, chia sẻ kiến ​​thức của bạn và lấy cảm hứng.', '[{"label": "A", "text_vi": "Trung tâm kiến thức AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm kiến thức AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "AWS re:Post", "is_correct": true, "analysis_vi": "Đúng. AWS re:Post là đáp án chính xác. AWS re:Post là nền tảng miễn phí để người dùng AWS tham gia các nhóm cộng đồng, đặt câu hỏi, tìm câu trả lời và đọc các bài viết do cộng đồng tạo ra về các phương pháp hay nhất."}, {"label": "C", "text_vi": "AWS 10", "is_correct": false, "analysis_vi": "Sai. AWS 10 không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Hỗ trợ doanh nghiệp AWS", "is_correct": false, "analysis_vi": "Sai. Hỗ trợ doanh nghiệp AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
