INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-249', 'practice_283', 'Một công ty muốn nhận thông báo để theo dõi chi phí vận hành tổng thể đối với cơ sở hạ tầng đám mây công cộng AWS của mình. Sản phẩm AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'AWS Budgets là dịch vụ cho phép bạn lập kế hoạch sử dụng dịch vụ, chi phí dịch vụ và đặt trước phiên bản. Bạn có thể sử dụng Ngân sách AWS để tạo ngân sách tùy chỉnh cảnh báo cho bạn khi chi phí hoặc mức sử dụng của bạn vượt quá (hoặc được dự báo sẽ vượt quá) số tiền dự kiến ​​của bạn. Bạn cũng có thể sử dụng Ngân sách AWS để theo dõi mức độ sử dụng và chi phí của bạn phù hợp với mức độ đáp ứng các giao dịch mua dự trữ của bạn1', '[{"label": "A", "text_vi": "Cầu sự kiện Amazon", "is_correct": false, "analysis_vi": "Sai. Cầu sự kiện Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tính toán kế hoạch tiết kiệm", "is_correct": false, "analysis_vi": "Sai. Tính toán kế hoạch tiết kiệm không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Ngân sách AWS", "is_correct": true, "analysis_vi": "Đúng. Ngân sách AWS là đáp án chính xác. AWS Budgets là dịch vụ cho phép bạn lập kế hoạch sử dụng dịch vụ, chi phí dịch vụ và đặt trước phiên bản."}, {"label": "D", "text_vi": "Người đánh giá di chuyển", "is_correct": false, "analysis_vi": "Sai. Người đánh giá di chuyển không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["AWS Budgets"]'::jsonb, NOW())
