INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-250', 'practice_283', 'Dịch vụ AWS nào được thiết kế để giúp người dùng xây dựng giao diện đàm thoại thành ứng dụng bằng giọng nói và văn bản?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'A đúng vì Amazon Lex là dịch vụ AWS giúp người dùng xây dựng giao diện đàm thoại vào các ứng dụng sử dụng giọng nói và văn bản. B sai vì Amazon Transcribe là dịch vụ AWS giúp người dùng chuyển lời nói thành văn bản. C không chính xác vì Amazon Comprehend là dịch vụ AWS giúp người dùng phân tích văn bản bằng cách xử lý ngôn ngữ tự nhiên. D sai vì Amazon Timestream là dịch vụ AWS giúp người dùng thu thập, lưu trữ và xử lý dữ liệu chuỗi thời gian.', '[{"label": "A", "text_vi": "Amazon Lex", "is_correct": true, "analysis_vi": "Đúng. Amazon Lex đáp ứng đầy đủ yêu cầu của đề bài. A đúng vì Amazon Lex là dịch vụ AWS giúp người dùng xây dựng giao diện đàm thoại vào các ứng dụng sử dụng giọng nói và văn bản."}, {"label": "B", "text_vi": "Phiên âm của Amazon", "is_correct": false, "analysis_vi": "Sai. B sai vì Amazon Transcribe là dịch vụ AWS giúp người dùng chuyển lời nói thành văn bản."}, {"label": "C", "text_vi": "Amazon Hiểu", "is_correct": false, "analysis_vi": "Sai. C không chính xác vì Amazon Comprehend là dịch vụ AWS giúp người dùng phân tích văn bản bằng cách xử lý ngôn ngữ tự nhiên."}, {"label": "D", "text_vi": "Dòng thời gian của Amazon", "is_correct": false, "analysis_vi": "Sai. D sai vì Amazon Timestream là dịch vụ AWS giúp người dùng thu thập, lưu trữ và xử lý dữ liệu chuỗi thời gian.."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
