INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-251', 'practice_283', 'Một công ty lớn có khối lượng công việc đòi hỏi phần cứng phải được duy trì tại chỗ. Công ty muốn sử dụng cùng các dịch vụ mặt phẳng quản lý và điều khiển mà họ hiện đang sử dụng trên AWS. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng những yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Câu trả lời đúng là C vì AWS Outposts là dịch vụ AWS giúp công ty đáp ứng được yêu cầu. AWS Outposts là dịch vụ được quản lý toàn phần giúp mở rộng cơ sở hạ tầng, dịch vụ, API và công cụ AWS tới hầu hết mọi trung tâm dữ liệu, không gian chung hoặc cơ sở tại chỗ. AWS Outposts cho phép khách hàng chạy khối lượng công việc của mình trên cùng phần cứng và phần mềm mà AWS sử dụng trên đám mây của mình, trong khi vẫn duy trì quyền truy cập và kiểm soát cục bộ. Các tùy chọn khác không chính xác vì chúng không phải là dịch vụ AWS cho phép công ty đáp ứng các yêu cầu. AWS Device Farm là dịch vụ AWS cho phép khách hàng thử nghiệm các ứng dụng web và di động của họ trên các thiết bị thực trong Đám mây AWS. AWS Fargate là dịch vụ AWS cho phép khách hàng chạy vùng chứa mà không cần phải quản lý máy chủ hoặc cụm. Trạm mặt đất AWS là dịch vụ AWS cho phép khách hàng giao tiếp với vệ tinh và dữ liệu đường xuống từ quỹ đạo.', '[{"label": "A", "text_vi": "Cụm thiết bị AWS", "is_correct": false, "analysis_vi": "Sai. Cụm thiết bị AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Cổng xa AWS", "is_correct": false, "analysis_vi": "Sai. AWS Fargate là dịch vụ AWS cho phép khách hàng chạy vùng chứa mà không cần phải quản lý máy chủ hoặc cụm."}, {"label": "C", "text_vi": "Tiền đồn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiền đồn AWS là đáp án chính xác. Câu trả lời đúng là C vì AWS Outposts là dịch vụ AWS giúp công ty đáp ứng được yêu cầu."}, {"label": "D", "text_vi": "Trạm mặt đất AWS", "is_correct": false, "analysis_vi": "Sai. Trạm mặt đất AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
