INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-252', 'practice_283', 'Những dịch vụ hoặc công cụ AWS nào được thiết kế để bảo vệ khối lượng công việc khỏi việc chèn SQL, tấn công tập lệnh chéo trang và tấn công DDoS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Shield Standard và AWS WAF là các dịch vụ hoặc công cụ AWS được thiết kế để bảo vệ khối lượng công việc khỏi việc chèn SQL, tập lệnh chéo trang và tấn công DDoS. Theo Hướng dẫn dành cho nhà phát triển AWS Shield, "AWS Shield là dịch vụ bảo vệ Từ chối dịch vụ phân tán (DDoS) được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS. AWS Shield cung cấp khả năng phát hiện luôn bật và giảm thiểu nội tuyến tự động giúp giảm thiểu thời gian ngừng hoạt động và độ trễ của ứng dụng, do đó không cần phải tham gia AWS Support để hưởng lợi từ tính năng bảo vệ DDoS." hoặc tiêu tốn quá nhiều tài nguyên. AWS WAF cung cấp cho bạn quyền kiểm soát cách lưu lượng truy cập đến ứng dụng của bạn bằng cách cho phép bạn tạo các quy tắc bảo mật chặn các kiểu tấn công phổ biến, chẳng hạn như chèn SQL hoặc tập lệnh chéo trang và các quy tắc lọc ra các mẫu lưu lượng truy cập cụ thể mà bạn xác định." VPC Endpoint, cổng riêng ảo và AWS Config không được thiết kế để bảo vệ khối lượng công việc khỏi các kiểu tấn công này.', '[{"label": "A", "text_vi": "VPC Endpoint", "is_correct": false, "analysis_vi": "Sai. AWS WAF cung cấp cho bạn quyền kiểm soát cách lưu lượng truy cập đến ứng dụng của bạn bằng cách cho phép bạn tạo các quy tắc bảo mật chặn các kiểu tấn công phổ biến, chẳng hạn như chèn SQL hoặc tập lệnh chéo trang và các quy tắc lọc ra các mẫu lưu lượng truy cập cụ thể mà bạn xác định.\" VPC Endpoint, cổng riêng ảo và AWS Config không được thiết kế để bảo vệ khối lượng công việc khỏi các kiểu tấn công này.."}, {"label": "B", "text_vi": "Cổng riêng ảo", "is_correct": false, "analysis_vi": "Sai. AWS WAF cung cấp cho bạn quyền kiểm soát cách lưu lượng truy cập đến ứng dụng của bạn bằng cách cho phép bạn tạo các quy tắc bảo mật chặn các kiểu tấn công phổ biến, chẳng hạn như chèn SQL hoặc tập lệnh chéo trang và các quy tắc lọc ra các mẫu lưu lượng truy cập cụ thể mà bạn xác định.\" VPC Endpoint, cổng riêng ảo và AWS Config không được thiết kế để bảo vệ khối lượng công việc khỏi các kiểu tấn công này.."}, {"label": "C", "text_vi": "Tiêu chuẩn lá chắn AWS", "is_correct": true, "analysis_vi": "Đúng. Tiêu chuẩn lá chắn AWS là đáp án chính xác. AWS Shield Standard và AWS WAF là các dịch vụ hoặc công cụ AWS được thiết kế để bảo vệ khối lượng công việc khỏi việc chèn SQL, tập lệnh chéo trang và tấn công DDoS."}, {"label": "D", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. AWS WAF cung cấp cho bạn quyền kiểm soát cách lưu lượng truy cập đến ứng dụng của bạn bằng cách cho phép bạn tạo các quy tắc bảo mật chặn các kiểu tấn công phổ biến, chẳng hạn như chèn SQL hoặc tập lệnh chéo trang và các quy tắc lọc ra các mẫu lưu lượng truy cập cụ thể mà bạn xác định.\" VPC Endpoint, cổng riêng ảo và AWS Config không được thiết kế để bảo vệ khối lượng công việc khỏi các kiểu tấn công này.."}, {"label": "E", "text_vi": "AWS WAF", "is_correct": true, "analysis_vi": "Đúng. AWS WAF là giải pháp đáp ứng yêu cầu. AWS Shield Standard và AWS WAF là các dịch vụ hoặc công cụ AWS được thiết kế để bảo vệ khối lượng công việc khỏi việc chèn SQL, tập lệnh chéo trang và tấn công DDoS. AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "AWS WAF", "Amazon VPC", "AWS Storage Gateway"]'::jsonb, NOW())
