INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-253', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào là ví dụ về hệ thống quản lý cơ sở dữ liệu quan hệ?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon Redshift là dịch vụ kho dữ liệu có quy mô petabyte được quản lý toàn phần trên đám mây. Bạn có thể bắt đầu chỉ với vài trăm gigabyte dữ liệu và mở rộng quy mô thành petabyte trở lên. Điều này cho phép bạn sử dụng dữ liệu của mình để có được thông tin chi tiết mới cho doanh nghiệp và khách hàng của mình. Amazon Redshift là một hệ thống quản lý cơ sở dữ liệu quan hệ (RDBMS), do đó nó tương thích với các ứng dụng RDBMS khác. Bạn có thể sử dụng SQL tiêu chuẩn để truy vấn dữ liệu.', '[{"label": "A", "text_vi": "Amazon Athena", "is_correct": false, "analysis_vi": "Sai. Amazon Athena không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Dịch chuyển đỏ của Amazon", "is_correct": true, "analysis_vi": "Đúng. Dịch chuyển đỏ của Amazon là đáp án chính xác. Amazon Redshift là dịch vụ kho dữ liệu có quy mô petabyte được quản lý toàn phần trên đám mây."}, {"label": "C", "text_vi": "Chọn Amazon S3", "is_correct": false, "analysis_vi": "Sai. Chọn Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Luồng dữ liệu Amazon Kinesis", "is_correct": false, "analysis_vi": "Sai. Luồng dữ liệu Amazon Kinesis không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
