INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-254', 'practice_283', 'Lợi ích nào của AWS được thể hiện qua các dịch vụ công nghệ theo yêu cầu cho phép các công ty thay thế chi phí cố định trả trước bằng chi phí biến đổi?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Định giá thanh toán theo nhu cầu sử dụng là một lợi ích của AWS thể hiện khả năng của người dùng trong việc thay thế chi phí cố định trả trước bằng chi phí biến đổi. Với chính sách trả theo mức sử dụng, người dùng chỉ trả tiền cho những tài nguyên họ sử dụng mà không cần bất kỳ hợp đồng hoặc cam kết dài hạn nào. Điều này có thể làm giảm tổng chi phí sở hữu và tăng lợi tức đầu tư. Định giá trả theo nhu cầu sử dụng cũng mang lại tính linh hoạt và khả năng mở rộng vì người dùng có thể điều chỉnh việc sử dụng tài nguyên theo nhu cầu và nhu cầu thay đổi của họ. Khung giá trị đám mây AWSNgười thực hành đám mây được chứng nhận của AWS - aws.amazon.com', '[{"label": "A", "text_vi": "Tính sẵn sàng cao", "is_correct": false, "analysis_vi": "Sai. Tính sẵn sàng cao: Tính sẵn sàng cao (High Availability) đảm bảo ứng dụng vận hành liên tục không gián đoạn bằng cách triển khai phân tán trên nhiều Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Tính kinh tế theo quy mô", "is_correct": false, "analysis_vi": "Sai. Tính kinh tế theo quy mô: Tính kinh tế nhờ quy mô khổng lồ (Massive economies of scale) cho phép AWS tổng hợp nhu cầu của hàng triệu khách hàng để hạ giá thành dịch vụ liên tục. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Định giá thanh toán theo nhu cầu sử dụng", "is_correct": true, "analysis_vi": "Đúng. Định giá thanh toán theo nhu cầu sử dụng là đáp án chính xác. Định giá thanh toán theo nhu cầu sử dụng là một lợi ích của AWS thể hiện khả năng của người dùng trong việc thay thế chi phí cố định trả trước bằng chi phí biến đổi."}, {"label": "D", "text_vi": "Phạm vi tiếp cận toàn cầu", "is_correct": false, "analysis_vi": "Sai. Phạm vi tiếp cận toàn cầu: Phạm vi tiếp cận toàn cầu (Go global in minutes) cho phép triển khai ứng dụng tới người dùng ở nhiều quốc gia với độ trễ thấp thông qua mạng lưới AWS Regions và Edge Locations. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
