INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-255', 'practice_283', 'Những lựa chọn nào được đề xuất cho hành trình chuyển đổi đám mây của AWS Cloud Adoption Framework (AWS CAF)? (Chọn HAI.)', 'Domain 1: Cloud Concepts', 'Cloud Concepts', 'Hành trình chuyển đổi đám mây AWS Cloud Adoption Framework (AWS CAF) là một quy trình gồm bốn giai đoạn giúp khách hàng lập kế hoạch và thực hiện quá trình di chuyển sang đám mây và chuyển đổi kỹ thuật số. Bốn giai đoạn đó là: Giai đoạn hình dung: Giai đoạn này tập trung vào việc chứng minh đám mây sẽ giúp đẩy nhanh kết quả kinh doanh của khách hàng như thế nào. Nó liên quan đến việc xác định và ưu tiên các cơ hội chuyển đổi trên bốn lĩnh vực: kinh doanh, con người, quản trị và nền tảng. Nó cũng liên quan đến việc liên kết các sáng kiến ​​chuyển đổi với các bên liên quan chính và kết quả kinh doanh có thể đo lường được1. Giai đoạn căn chỉnh: Giai đoạn này tập trung vào việc xác định các khoảng cách về năng lực trên sáu khía cạnh: kinh doanh, con người, quản trị, nền tảng, bảo mật và vận hành. Nó cũng liên quan đến việc xác định sự phụ thuộc giữa các tổ chức và giải quyết các mối quan tâm và thách thức của các bên liên quan. Mục tiêu của giai đoạn này là tạo ra các chiến lược để cải thiện tính sẵn sàng của đám mây, đảm bảo sự liên kết của các bên liên quan và tạo điều kiện thuận lợi cho các hoạt động quản lý thay đổi có liên quan của tổ chức1. Giai đoạn khởi động: Giai đoạn này tập trung vào việc đưa ra các sáng kiến ​​thí điểm trong sản xuất và thể hiện giá trị kinh doanh gia tăng. Phi công phải có tác động lớn và ảnh hưởng đến định hướng tương lai. Khách hàng nên học hỏi từ các phi công và điều chỉnh cách tiếp cận của họ trước khi mở rộng quy mô sang sản xuất hoàn chỉnh1. Giai đoạn mở rộng quy mô: Giai đoạn này tập trung vào việc mở rộng các thử nghiệm sản xuất và giá trị kinh doanh đến quy mô mong muốn và đảm bảo rằng các lợi ích kinh doanh liên quan đến đầu tư vào đám mây được hiện thực hóa và duy trì1.', '[{"label": "A", "text_vi": "Giai đoạn hình dung", "is_correct": true, "analysis_vi": "Đúng. Giai đoạn hình dung là đáp án chính xác. Hành trình chuyển đổi đám mây AWS Cloud Adoption Framework (AWS CAF) là một quy trình gồm bốn giai đoạn giúp khách hàng lập kế hoạch và thực hiện quá trình di chuyển sang đám mây và chuyển đổi kỹ thuật số."}, {"label": "B", "text_vi": "Căn chỉnh pha", "is_correct": false, "analysis_vi": "Sai. Căn chỉnh pha không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Giai đoạn đánh giá", "is_correct": false, "analysis_vi": "Sai. Giai đoạn đánh giá không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Giai đoạn huy động", "is_correct": false, "analysis_vi": "Sai. Giai đoạn huy động không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Giai đoạn di cư và hiện đại hóa", "is_correct": true, "analysis_vi": "Đúng. Giai đoạn di cư và hiện đại hóa là đáp án chính xác. Hành trình chuyển đổi đám mây AWS Cloud Adoption Framework (AWS CAF) là một quy trình gồm bốn giai đoạn giúp khách hàng lập kế hoạch và thực hiện quá trình di chuyển sang đám mây và chuyển đổi kỹ thuật số."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
