INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-256', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào sẽ tìm kiếm và xác định các tài nguyên AWS được chia sẻ ra bên ngoài?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Trình phân tích truy cập AWS IAM là dịch vụ AWS giúp khách hàng xác định và xem xét các tài nguyên trong tài khoản AWS của họ được chia sẻ với một thực thể bên ngoài, chẳng hạn như tài khoản AWS khác, người dùng root, tổ chức hoặc thực thể công cộng. Trình phân tích truy cập AWS IAM sử dụng lý luận tự động, một dạng logic và suy luận toán học để phân tích các chính sách dựa trên tài nguyên trong tài khoản và tạo ra kết quả toàn diện cho thấy cấp độ truy cập, nguồn truy cập, tài nguyên bị ảnh hưởng và điều kiện áp dụng quyền truy cập. Khách hàng có thể sử dụng AWS IAM Access Phân tích để kiểm tra tài nguyên được chia sẻ, xác thực chính sách truy cập của họ và giám sát mọi thay đổi đối với trạng thái chia sẻ tài nguyên.', '[{"label": "A", "text_vi": "Dịch vụ tìm kiếm mở của Amazon", "is_correct": false, "analysis_vi": "Sai. Dịch vụ tìm kiếm mở của Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tháp điều khiển AWS", "is_correct": false, "analysis_vi": "Sai. Tháp điều khiển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Trình phân tích truy cập AWS IAM", "is_correct": true, "analysis_vi": "Đúng. Trình phân tích truy cập AWS IAM là đáp án chính xác. Trình phân tích truy cập AWS IAM là dịch vụ AWS giúp khách hàng xác định và xem xét các tài nguyên trong tài khoản AWS của họ được chia sẻ với một thực thể bên ngoài, chẳng hạn như tài khoản AWS khác, người dùng root, tổ chức hoặc thực thể công cộng."}, {"label": "D", "text_vi": "Cổng xa AWS", "is_correct": false, "analysis_vi": "Sai. Cổng xa AWS: AWS Fargate là công nghệ điện toán serverless cho container (ECS/EKS), giúp chạy container mà không cần quản trị máy chủ EC2 cơ sở. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
