INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-257', 'practice_283', 'Một công ty đã phát triển một ứng dụng phân tán có khả năng phục hồi nhanh chóng sau khi bị gián đoạn. Ứng dụng xử lý định kỳ khối lượng lớn dữ liệu bằng cách sử dụng nhiều phiên bản Amazon EC2. Ứng dụng này đôi khi không hoạt động trong nhiều tháng. Tùy chọn mua phiên bản EC2 nào tiết kiệm chi phí NHẤT cho trường hợp sử dụng này?', 'Domain 4: Billing, Pricing and Support', 'Quản lý chi phí & Thanh toán AWS', 'Phiên bản Spot là phiên bản sử dụng dung lượng EC2 dự phòng được giảm giá tới 90% so với giá Theo yêu cầu. Vì Phiên bản Spot có thể bị gián đoạn bởi EC2 với hai phút thông báo khi EC2 cần lấy lại công suất nên bạn có thể sử dụng chúng cho các ứng dụng có thời gian bắt đầu và kết thúc linh hoạt hoặc có thể chịu được gián đoạn5. Tùy chọn này hiệu quả nhất về mặt chi phí đối với trường hợp sử dụng được mô tả trong câu hỏi. Phiên bản dự trữ là phiên bản bạn mua với thời hạn một năm hoặc ba năm và trả mức giá theo giờ thấp hơn so với Phiên bản theo yêu cầu. Tùy chọn này phù hợp với các ứng dụng có trạng thái ổn định hoặc mức sử dụng có thể dự đoán được. Phiên bản chuyên dụng là các phiên bản chạy trên phần cứng dành riêng cho một khách hàng trong Amazon VPC. Tùy chọn này phù hợp cho các ứng dụng có yêu cầu tuân thủ hoặc quy định nghiêm ngặt. Phiên bản theo yêu cầu là phiên bản mà bạn thanh toán theo giây, không có cam kết dài hạn hoặc thanh toán trả trước. Tùy chọn này phù hợp với các ứng dụng có khối lượng công việc không thể đoán trước hoặc không liên tục.', '[{"label": "A", "text_vi": "Phiên bản dự trữ", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Phiên bản Spot", "is_correct": true, "analysis_vi": "Đúng. Phiên bản Spot là đáp án chính xác. Phiên bản Spot là phiên bản sử dụng dung lượng EC2 dự phòng được giảm giá tới 90% so với giá Theo yêu cầu."}, {"label": "C", "text_vi": "Phiên bản chuyên dụng", "is_correct": false, "analysis_vi": "Sai. Phiên bản chuyên dụng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Phiên bản theo yêu cầu", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
