INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-258', 'practice_283', 'Một công ty đang chạy hệ thống xử lý đơn hàng trên phiên bản Amazon EC2. Công ty muốn di chuyển ứng dụng dựa trên microservice. Ứng dụng có thể sử dụng sự kết hợp dịch vụ AWS nào để đáp ứng các yêu cầu này? (Chọn HAI.)', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Sự kết hợp của các dịch vụ AWS mà ứng dụng có thể sử dụng để di chuyển sang ứng dụng dựa trên vi dịch vụ là Amazon Simple Queue Service (Amazon SQS) và AWS Lambda. Amazon SQS là dịch vụ xếp hàng tin nhắn được quản lý toàn phần, cho phép khách hàng tách rời và mở rộng quy mô các vi dịch vụ, hệ thống phân tán và ứng dụng serverless. Ứng dụng có thể sử dụng Amazon SQS để gửi, lưu trữ và nhận tin nhắn giữa các vi dịch vụ, đảm bảo rằng mỗi tin nhắn chỉ được xử lý một lần và theo đúng thứ tự. AWS Lambda là dịch vụ điện toán serverless cho phép khách hàng chạy mã mà không cần cung cấp hay quản lý máy chủ. Ứng dụng có thể sử dụng AWS Lambda để tạo và triển khai các vi dịch vụ dưới dạng các chức năng được kích hoạt bởi các sự kiện, chẳng hạn như tin nhắn từ Amazon SQS. AWS Migration Hub, AWS AppSync và AWS Application Migration Service không phải là những dịch vụ tốt nhất để sử dụng khi di chuyển sang ứng dụng dựa trên vi dịch vụ. Trung tâm di chuyển AWS là dịch vụ cung cấp một vị trí duy nhất để theo dõi tiến trình di chuyển ứng dụng trên nhiều giải pháp của AWS và đối tác. AWS AppSync là dịch vụ đơn giản hóa việc phát triển API GraphQL để đồng bộ hóa dữ liệu ngoại tuyến và thời gian thực. Dịch vụ di chuyển ứng dụng AWS là dịch vụ cho phép khách hàng di chuyển các ứng dụng tại chỗ của họ sang AWS mà không thực hiện bất kỳ thay đổi nào đối với ứng dụng, máy chủ hoặc cơ sở dữ liệu.', '[{"label": "A", "text_vi": "Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS) là đáp án chính xác. Sự kết hợp của các dịch vụ AWS mà ứng dụng có thể sử dụng để di chuyển sang ứng dụng dựa trên vi dịch vụ là Amazon Simple Queue Service (Amazon SQS) và AWS Lambda."}, {"label": "B", "text_vi": "AWS Lambda", "is_correct": true, "analysis_vi": "Đúng. AWS Lambda là đáp án chính xác. Sự kết hợp của các dịch vụ AWS mà ứng dụng có thể sử dụng để di chuyển sang ứng dụng dựa trên vi dịch vụ là Amazon Simple Queue Service (Amazon SQS) và AWS Lambda."}, {"label": "C", "text_vi": "Trung tâm di chuyển AWS", "is_correct": false, "analysis_vi": "Sai. Trung tâm di chuyển AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Đồng bộ hóa ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "E", "text_vi": "Dịch vụ di chuyển ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Dịch vụ di chuyển ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Lambda", "Amazon SQS"]'::jsonb, NOW())
