INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-259', 'practice_283', 'Một công ty muốn lưu trữ dữ liệu với tính sẵn sàng cao, mã hóa dữ liệu ở trạng thái lưu trữ và có quyền truy cập trực tiếp vào dữ liệu qua internet. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này với chi phí hiệu quả nhất?', 'Domain 3: Cloud Technology and Services', 'Quản lý chi phí & Thanh toán AWS', 'Amazon Elastic File System (Amazon EFS) cung cấp hệ thống tệp NFS đàn hồi đơn giản, có thể mở rộng và được quản lý hoàn toàn để sử dụng với các dịch vụ Đám mây AWS và tài nguyên tại chỗ. Nó được xây dựng để mở rộng quy mô theo yêu cầu lên tới petabyte mà không làm gián đoạn ứng dụng, tự động tăng và thu nhỏ khi bạn thêm và xóa tệp, loại bỏ nhu cầu cung cấp và quản lý dung lượng để đáp ứng sự tăng trưởng. Amazon EFS cung cấp hai lớp lưu trữ: lớp lưu trữ Tiêu chuẩn và lớp lưu trữ Truy cập không thường xuyên (EFS IA). EFS IA cung cấp mức giá/hiệu suất được tối ưu hóa về mặt chi phí cho những tệp không được truy cập hàng ngày. Amazon EFS mã hóa dữ liệu khi lưu trữ và truyền đi, đồng thời hỗ trợ truy cập trực tiếp qua internet4.', '[{"label": "A", "text_vi": "Cửa hàng khối đàn hồi Amazon (AmazonEBS)", "is_correct": false, "analysis_vi": "Sai. Cửa hàng khối đàn hồi Amazon (AmazonEBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Hệ thống tệp đàn hồi của Amazon (Amazon EFS)", "is_correct": true, "analysis_vi": "Đúng. Hệ thống tệp đàn hồi của Amazon (Amazon EFS) là đáp án chính xác. Amazon Elastic File System (Amazon EFS) cung cấp hệ thống tệp NFS đàn hồi đơn giản, có thể mở rộng và được quản lý hoàn toàn để sử dụng với các dịch vụ Đám mây AWS và tài nguyên tại chỗ."}, {"label": "D", "text_vi": "AWS Storage Gateway", "is_correct": false, "analysis_vi": "Sai. AWS Storage Gateway: AWS Storage Gateway kết nối môi trường tại chỗ với lưu trữ đám mây AWS, cung cấp quyền truy cập liền mạch vào S3 và EBS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS Storage Gateway"]'::jsonb, NOW())
