INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-260', 'practice_283', 'Công ty cần một hệ thống tệp NFS đàn hồi có thể mở rộng, được quản lý toàn phần để sử dụng với các dịch vụ Đám mây AWS và tài nguyên tại chỗ. Dịch vụ AWS nào đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon Elastic File System (Amazon EFS) là dịch vụ cung cấp hệ thống tệp NFS đàn hồi đơn giản, có thể mở rộng và được quản lý hoàn toàn để sử dụng với các dịch vụ Đám mây AWS và tài nguyên tại chỗ. Nó được xây dựng để mở rộng quy mô theo yêu cầu lên tới petabyte mà không làm gián đoạn ứng dụng, tự động tăng và thu nhỏ khi bạn thêm và xóa tệp, loại bỏ nhu cầu cung cấp và quản lý dung lượng để đáp ứng sự tăng trưởng. Bạn có thể sử dụng Amazon EFS để tạo một hệ thống tệp dùng chung có thể sử dụng được cho cả trung tâm dữ liệu tại chỗ và môi trường Đám mây AWS của bạn. Amazon Elastic Block Store (Amazon EBS) là dịch vụ cung cấp khối lượng lưu trữ khối liên tục để sử dụng với các phiên bản Amazon EC2 trên Đám mây AWS. Mỗi ổ đĩa Amazon EBS được tự động sao chép trong Availability Zone (AZ) để bảo vệ bạn khỏi lỗi thành phần, mang lại độ sẵn sàng và độ bền cao. Tuy nhiên, ổ đĩa Amazon EBS không phải là hệ thống tệp dùng chung và chúng không thể có sẵn cho cả trung tâm dữ liệu tại chỗ lẫn môi trường Đám mây AWS của bạn. Amazon S3 là dịch vụ cung cấp lưu trữ đối tượng thông qua giao diện dịch vụ web. Bạn có thể sử dụng Amazon S3 để lưu trữ và bảo vệ bất kỳ lượng dữ liệu nào cho nhiều trường hợp sử dụng, chẳng hạn như kho dữ liệu, trang web, ứng dụng di động, sao lưu và khôi phục, lưu trữ, ứng dụng doanh nghiệp, thiết bị IoT và phân tích dữ liệu lớn. Tuy nhiên, Amazon S3 không phải là hệ thống tệp dùng chung và nó không thể có sẵn cho cả trung tâm dữ liệu tại chỗ lẫn môi trường Đám mây AWS của bạn nếu không có cấu hình bổ sung. Amazon ElastiCache là dịch vụ cho phép bạn thiết lập, chạy và mở rộng quy mô các kho dữ liệu trong bộ nhớ tương thích nguồn mở phổ biến trên đám mây một cách liền mạch. Bạn có thể sử dụng Amazon ElastiCache để cải thiện hiệu suất ứng dụng của mình bằng cách cho phép bạn truy xuất thông tin từ các kho dữ liệu trong bộ nhớ, có tốc độ nhanh, được quản lý, thay vì dựa hoàn toàn vào cơ sở dữ liệu trên đĩa có tốc độ chậm hơn. Tuy nhiên, Amazon ElastiCache không phải là hệ thống tệp dùng chung và nó không thể có sẵn cho cả trung tâm dữ liệu tại chỗ lẫn môi trường Đám mây AWS của bạn.', '[{"label": "A", "text_vi": "Cửa hàng khối đàn hồi Amazon (Amazon EBS)", "is_correct": false, "analysis_vi": "Sai. Cửa hàng khối đàn hồi Amazon (Amazon EBS): Amazon EBS cung cấp các khối lưu trữ cấp block gắn trực tiếp vào phiên bản EC2 với độ trễ thấp và tính bền vững cao trong một Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon S3", "is_correct": false, "analysis_vi": "Sai. Amazon S3: Amazon S3 là dịch vụ lưu trữ đối tượng (Object Storage) không giới hạn dung lượng với độ bền 99.999999999% (11 số 9), lý tưởng cho backup, media, data lake và static website. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon ElastiCache", "is_correct": false, "analysis_vi": "Sai. Amazon ElastiCache: Amazon ElastiCache là dịch vụ bộ nhớ đệm in-memory (Redis hoặc Memcached) giúp tăng tốc độ truy xuất dữ liệu với độ trễ dưới 1 mili-giây. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Hệ thống tệp đàn hồi của Amazon (Amazon EFS)", "is_correct": true, "analysis_vi": "Đúng. Hệ thống tệp đàn hồi của Amazon (Amazon EFS) là đáp án chính xác. Amazon Elastic File System (Amazon EFS) là dịch vụ cung cấp hệ thống tệp NFS đàn hồi đơn giản, có thể mở rộng và được quản lý hoàn toàn để sử dụng với các dịch vụ Đám mây AWS và tài nguyên tại chỗ."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon S3"]'::jsonb, NOW())
