INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-261', 'practice_283', 'Những dịch vụ hoặc tính năng nào của AWS cung cấp giải pháp khắc phục thảm họa cho phiên bản Amazon EC2? (Chọn HAI.)', 'Domain 4: Billing, Pricing and Support', 'Dịch vụ điện toán đám mây Amazon EC2', 'Câu trả lời đúng là B và C. Ảnh chụp nhanh EC2 Amazon Machine Images (AMI) và Amazon Elastic Block Store (Amazon EBS) là hai dịch vụ AWS cung cấp giải pháp khắc phục thảm họa cho phiên bản Amazon EC2. AMI EC2 là các mẫu được cấu hình sẵn chứa cấu hình phần mềm và dữ liệu cần thiết để khởi chạy phiên bản EC2. Bạn có thể tạo AMI từ các phiên bản EC2 đang chạy của mình và sử dụng chúng để khởi chạy các phiên bản mới trong cùng hoặc khác AWS Region. Bằng cách này, bạn có thể nhanh chóng khôi phục các phiên bản EC2 trong trường hợp xảy ra thảm họa ảnh hưởng đến Khu vực chính hoặc Availability Zone (AZ)1 của bạn. Bản kết xuất nhanh của Amazon EBS là bản sao lưu gia tăng cho các ổ đĩa Amazon EBS của bạn. Bạn có thể tạo ảnh chụp nhanh cho ổ đĩa của mình và lưu trữ chúng trong Amazon S3, đây là dịch vụ lưu trữ có độ bền cao và có khả năng mở rộng. Bạn có thể sử dụng ảnh chụp nhanh để khôi phục các tập của mình về thời điểm trước đó hoặc để tạo các tập mới từ ảnh chụp nhanh. Ảnh chụp nhanh cũng có thể được sao chép trên các AWS Region, cho phép bạn khôi phục dữ liệu của mình ở Khu vực khác trong trường hợp xảy ra thảm họa2. Các tùy chọn khác không liên quan trực tiếp đến việc khắc phục thảm họa cho các phiên bản EC2: Phiên bản dự trữ EC2 là mô hình định giá cho phép bạn dự trữ công suất EC2 trong một khoảng thời gian cụ thể và được giảm giá theo giờ. Phiên bản dự trữ không mang lại bất kỳ lợi ích khắc phục thảm họa nào vì chúng chỉ là một tùy chọn thanh toán3. AWS Shield là dịch vụ được quản lý nhằm bảo vệ tài nguyên AWS của bạn khỏi các cuộc tấn công từ chối dịch vụ (DDoS) phân tán. AWS Shield cung cấp khả năng bảo vệ cơ bản cho tất cả khách hàng AWS mà không tính thêm phí và bảo vệ nâng cao cho những khách hàng cần mức độ phát hiện và giảm nhẹ cao hơn. AWS Shield không cung cấp bất kỳ lợi ích khắc phục thảm họa nào vì đây chỉ là một dịch vụ bảo mật4. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa giúp giám sát tài khoản AWS và khối lượng công việc của bạn để phát hiện hoạt động độc hại hoặc trái phép. Amazon GuardDuty phân tích nhiều nguồn dữ liệu khác nhau, chẳng hạn như AWS CloudTrail, Nhật ký lưu lượng Amazon VPC và nhật ký DNS, để xác định các mối đe dọa tiềm ẩn và cảnh báo cho bạn thông qua Amazon CloudWatch Events hoặc AWS Lambda. Amazon GuardDuty không cung cấp bất kỳ lợi ích khắc phục thảm họa nào vì đây chỉ là dịch vụ giám sát5.', '[{"label": "A", "text_vi": "Phiên bản dự trữ EC2", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Hình ảnh máy EC2 Amazon (AMI)", "is_correct": true, "analysis_vi": "Đúng. Hình ảnh máy EC2 Amazon (AMI) là đáp án chính xác. Ảnh chụp nhanh EC2 Amazon Machine Images (AMI) và Amazon Elastic Block Store (Amazon EBS) là hai dịch vụ AWS cung cấp giải pháp khắc phục thảm họa cho phiên bản Amazon EC2."}, {"label": "C", "text_vi": "Ảnh chụp nhanh của Amazon Elastic Block Store (Amazon EBS)", "is_correct": true, "analysis_vi": "Đúng. Ảnh chụp nhanh của Amazon Elastic Block Store (Amazon EBS) là đáp án chính xác. Ảnh chụp nhanh EC2 Amazon Machine Images (AMI) và Amazon Elastic Block Store (Amazon EBS) là hai dịch vụ AWS cung cấp giải pháp khắc phục thảm họa cho phiên bản Amazon EC2."}, {"label": "D", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "E", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Nhiệm vụ bảo vệ của Amazon: Amazon GuardDuty là dịch vụ phát hiện mối đe dọa thông minh sử dụng máy học để liên tục phân tích VPC Flow Logs, CloudTrail Logs và DNS Logs. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Shield", "Amazon GuardDuty"]'::jsonb, NOW())
