INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-262', 'practice_283', 'Một công ty đang chạy ứng dụng của mình trên Đám mây AWS và muốn bảo vệ khỏi cuộc tấn công DDoS. Security Group của công ty muốn có khả năng hiển thị gần như thời gian thực về các cuộc tấn công DDoS. Bộ lọc lưu lượng hoặc dịch vụ AWS nào sẽ đáp ứng các yêu cầu này với các tính năng NHẤT để bảo vệ DDoS?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'AWS Shield Advanced là dịch vụ bảo vệ Từ chối dịch vụ phân tán (DDoS) được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS. AWS Shield Advanced cung cấp cho bạn quyền truy cập 24x7 vào Nhóm phản hồi DDoS (DRT) của AWS và bảo vệ khỏi các cuộc tấn công DDoS ở mọi quy mô hoặc thời lượng. AWS Shield Advanced cũng cung cấp khả năng hiển thị gần như theo thời gian thực về các cuộc tấn công, khả năng giảm thiểu tấn công nâng cao và khả năng tích hợp với AWS WAF và AWS Tường lửa Manager1. AWS Shield là một dịch vụ tiêu chuẩn cung cấp khả năng phát hiện liên tục và giảm thiểu nội tuyến tự động để giảm thiểu thời gian ngừng hoạt động và độ trễ của ứng dụng, nhưng dịch vụ này không cung cấp cùng mức tính năng và hỗ trợ như AWS Shield Advanced2. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa liên tục giám sát hoạt động độc hại và hành vi trái phép nhưng không cung cấp tính năng bảo vệ DDoS3. ACL mạng là các bộ lọc không trạng thái có thể được liên kết với mạng con để kiểm soát lưu lượng đến và đi từ mạng con, nhưng chúng không được thiết kế để bảo vệ khỏi các cuộc tấn công DDoS', '[{"label": "A", "text_vi": "Lá chắn AWS nâng cao", "is_correct": true, "analysis_vi": "Đúng. Lá chắn AWS nâng cao là đáp án chính xác. AWS Shield Advanced là dịch vụ bảo vệ Từ chối dịch vụ phân tán (DDoS) được quản lý nhằm bảo vệ các ứng dụng chạy trên AWS."}, {"label": "B", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Khiên AWS: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa liên tục giám sát hoạt động độc hại và hành vi trái phép nhưng không cung cấp tính năng bảo vệ DDoS3."}, {"label": "D", "text_vi": "ACL mạng", "is_correct": false, "analysis_vi": "Sai. ACL mạng là các bộ lọc không trạng thái có thể được liên kết với mạng con để kiểm soát lưu lượng đến và đi từ mạng con, nhưng chúng không được thiết kế để bảo vệ khỏi các cuộc tấn công DDoS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "Amazon GuardDuty"]'::jsonb, NOW())
