INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-263', 'practice_283', 'Ứng dụng của công ty lưu trữ dữ liệu trong bộ chứa Amazon S3. Công ty có chức năng AWS Lambda xử lý dữ liệu trong nhóm S3. Công ty cần gọi hàm này mỗi ngày một lần vào một thời điểm cụ thể. Công ty nên sử dụng dịch vụ AWS nào để đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ lưu trữ Amazon S3 & Vòng đời dữ liệu', 'Amazon EventBridge là dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu gọi hàm Lambda mỗi ngày một lần vào một thời điểm cụ thể. Amazon EventBridge là dịch vụ bus sự kiện serverless cho phép bạn dễ dàng kết nối ứng dụng của mình với dữ liệu từ dịch vụ AWS, ứng dụng SaaS và ứng dụng của riêng bạn. Bạn có thể sử dụng Amazon EventBridge để tạo các quy tắc khớp với các sự kiện và định tuyến chúng đến các mục tiêu như hàm AWS Lambda, chủ đề Amazon SNS, hàng đợi Amazon SQS hoặc các dịch vụ AWS khác. Bạn cũng có thể sử dụng Amazon EventBridge để tạo các quy tắc đã lên lịch nhằm kích hoạt mục tiêu của mình vào một thời điểm hoặc khoảng thời gian cụ thể, chẳng hạn như một lần mỗi ngày. AWS Managed Services (AMS), AWS CodeStar và AWS Step Functions không phải là những dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu này. AMS là dịch vụ cung cấp khả năng quản lý vận hành cho cơ sở hạ tầng và ứng dụng AWS của bạn. AWS CodeStar là dịch vụ cung cấp giao diện người dùng thống nhất để quản lý các dự án phát triển phần mềm trên AWS. AWS Step Functions là dịch vụ điều phối nhiều dịch vụ AWS thành các quy trình làm việc phi máy chủ.', '[{"label": "A", "text_vi": "Dịch vụ được quản lý AWS (AMS)", "is_correct": false, "analysis_vi": "Sai. AWS Managed Services (AMS), AWS CodeStar và AWS Step Functions không phải là những dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu này."}, {"label": "B", "text_vi": "Ngôi sao mã AWS", "is_correct": false, "analysis_vi": "Sai. AWS Managed Services (AMS), AWS CodeStar và AWS Step Functions không phải là những dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu này."}, {"label": "C", "text_vi": "Cầu sự kiện Amazon", "is_correct": true, "analysis_vi": "Đúng. Cầu sự kiện Amazon là đáp án chính xác. Amazon EventBridge là dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu gọi hàm Lambda mỗi ngày một lần vào một thời điểm cụ thể."}, {"label": "D", "text_vi": "Chức năng bước AWS", "is_correct": false, "analysis_vi": "Sai. AWS Managed Services (AMS), AWS CodeStar và AWS Step Functions không phải là những dịch vụ mà công ty nên sử dụng để đáp ứng yêu cầu này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon S3", "AWS Lambda"]'::jsonb, NOW())
