INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-264', 'practice_283', 'Tuyên bố nào giải thích giá trị kinh doanh của việc di chuyển sang Đám mây AWS? (Chọn HAI.)', 'Domain 2: Security and Compliance', 'Security and Compliance', 'B và D đúng vì tính khả dụng và bảo mật của AWS cho phép khách hàng cải thiện SLA của họ đồng thời giảm rủi ro và thời gian ngừng hoạt động ngoài dự kiến1, đồng thời AWS giảm chi phí CNTT liên quan đến cơ sở hạ tầng, cho phép khách hàng tái đầu tư vào các lĩnh vực khác2. A không chính xác vì việc di chuyển sang Đám mây AWS không tự động cung cấp ứng dụng trên thiết bị di động vì điều này phụ thuộc vào thiết kế và khả năng tương thích của ứng dụng. C không chính xác vì các công ty di chuyển sang Đám mây AWS vẫn cần lập kế hoạch để có tính sẵn sàng cao và khắc phục thảm họa, vì AWS là mô hình trách nhiệm chung3. E sai vì việc di chuyển sang Đám mây AWS không yêu cầu các công ty phải cấu trúc lại và viết lại tất cả các ứng dụng doanh nghiệp vì AWS đưa ra các chiến lược di chuyển khác nhau tùy thuộc vào độ phức tạp của ứng dụng và mục tiêu kinh doanh4.', '[{"label": "A", "text_vi": "Việc di chuyển các ứng dụng doanh nghiệp sang Đám mây AWS giúp các ứng dụng này tự động có sẵn trên thiết bị di động.", "is_correct": false, "analysis_vi": "Sai. Việc di chuyển các ứng dụng doanh nghiệp sang Đám mây AWS giúp các ứng dụng này tự động có sẵn trên thiết bị di động. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tính khả dụng và bảo mật của AWS cung cấp khả năng cải thiện các thỏa thuận cấp độ dịch vụ (SLA) đồng thời giảm thiểu rủi ro và thời gian ngừng hoạt động ngoài dự kiến.", "is_correct": true, "analysis_vi": "Đúng. Tính khả dụng và bảo mật của AWS cung cấp khả năng cải thiện các thỏa thuận cấp độ dịch vụ (SLA) đồng thời giảm thiểu rủi ro và thời gian ngừng hoạt động ngoài dự kiến. là đáp án chính xác. B và D đúng vì tính khả dụng và bảo mật của AWS cho phép khách hàng cải thiện SLA của họ đồng thời giảm rủi ro và thời gian ngừng hoạt động ngoài dự kiến1, đồng thời AWS giảm chi phí CNTT liên quan đến cơ sở hạ tầng, cho phép khách hàng tái đầu tư vào các lĩnh vực khác2."}, {"label": "C", "text_vi": "Các công ty di chuyển sang Đám mây AWS sẽ loại bỏ nhu cầu lập kế hoạch cho tính sẵn sàng cao và khắc phục thảm họa.", "is_correct": false, "analysis_vi": "Sai. Các công ty di chuyển sang Đám mây AWS sẽ loại bỏ nhu cầu lập kế hoạch cho tính sẵn sàng cao và khắc phục thảm họa.: Tính sẵn sàng cao (High Availability) đảm bảo ứng dụng vận hành liên tục không gián đoạn bằng cách triển khai phân tán trên nhiều Availability Zone. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Các công ty di chuyển sang Đám mây AWS sẽ giảm chi phí CNTT liên quan đến cơ sở hạ tầng, giải phóng ngân sách để tái đầu tư vào các lĩnh vực khác.", "is_correct": true, "analysis_vi": "Đúng. Các công ty di chuyển sang Đám mây AWS sẽ giảm chi phí CNTT liên quan đến cơ sở hạ tầng, giải phóng ngân sách để tái đầu tư vào các lĩnh vực khác. là đáp án chính xác. B và D đúng vì tính khả dụng và bảo mật của AWS cho phép khách hàng cải thiện SLA của họ đồng thời giảm rủi ro và thời gian ngừng hoạt động ngoài dự kiến1, đồng thời AWS giảm chi phí CNTT liên quan đến cơ sở hạ tầng, cho phép khách hàng tái đầu tư vào các lĩnh vực khác2."}, {"label": "E", "text_vi": "Các ứng dụng được hiện đại hóa vì việc di chuyển sang Đám mây AWS yêu cầu các công ty phải cấu trúc lại và viết lại tất cả các ứng dụng doanh nghiệp.", "is_correct": false, "analysis_vi": "Sai. Các ứng dụng được hiện đại hóa vì việc di chuyển sang Đám mây AWS yêu cầu các công ty phải cấu trúc lại và viết lại tất cả các ứng dụng doanh nghiệp. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
