INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-265', 'practice_283', 'Ví dụ này cho thấy phương pháp thực hành tốt nhất nào về quản trị chi phí?', 'Domain 1: Cloud Concepts', 'Quản lý chi phí & Thanh toán AWS', 'Tối ưu hóa kiến trúc là cách thực hành tốt nhất để quản trị chi phí mà ví dụ này cho thấy. Tối ưu hóa kiến ​​trúc là quá trình thiết kế và triển khai các giải pháp AWS hiệu quả, có thể mở rộng và tiết kiệm chi phí. Bằng cách sử dụng các dịch vụ AWS cụ thể để nâng cao hiệu quả và giảm chi phí, công ty đang tuân theo phương pháp thực hành tốt nhất về tối ưu hóa kiến ​​trúc. Một số kỹ thuật để tối ưu hóa kiến ​​trúc bao gồm sử dụng đúng kích cỡ và loại tài nguyên, tận dụng tính linh hoạt và khả năng mở rộng, chọn lớp lưu trữ phù hợp nhất cũng như sử dụng các dịch vụ được quản lý và không có máy chủ2.', '[{"label": "A", "text_vi": "Kiểm soát tài nguyên", "is_correct": false, "analysis_vi": "Sai. Một số kỹ thuật để tối ưu hóa kiến ​​trúc bao gồm sử dụng đúng kích cỡ và loại tài nguyên, tận dụng tính linh hoạt và khả năng mở rộng, chọn lớp lưu trữ phù hợp nhất cũng như sử dụng các dịch vụ được quản lý và không có máy chủ2.."}, {"label": "B", "text_vi": "Phân bổ chi phí", "is_correct": false, "analysis_vi": "Sai. Phân bổ chi phí không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Tối ưu hóa kiến trúc", "is_correct": true, "analysis_vi": "Đúng. Tối ưu hóa kiến trúc là đáp án chính xác. Tối ưu hóa kiến trúc là cách thực hành tốt nhất để quản trị chi phí mà ví dụ này cho thấy."}, {"label": "D", "text_vi": "Thực thi gắn thẻ", "is_correct": false, "analysis_vi": "Sai. Thực thi gắn thẻ không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Phân biệt: Cost Explorer (dự báo và phân tích lịch sử chi tiêu), AWS Budgets (đặt ngưỡng cảnh báo ngân sách)."]'::jsonb, '[{"term": "dự báo chi phí", "points_to": "AWS Cost Explorer"}]'::jsonb, '[]'::jsonb, NOW())
