INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-266', 'practice_283', 'Kỹ sư CNTT cần truy cập các dịch vụ AWS từ ứng dụng tại chỗ. Ứng dụng cần thông tin xác thực hoặc khóa nào để xác thực?', 'Domain 2: Security and Compliance', 'Security and Compliance', 'Khóa truy cập IAM là thông tin xác thực dài hạn bao gồm ID khóa truy cập và khóa truy cập bí mật. Bạn sử dụng khóa truy cập để ký các yêu cầu có lập trình mà bạn gửi tới AWS. Nếu cần truy cập các dịch vụ AWS từ ứng dụng tại chỗ, bạn có thể sử dụng khóa truy cập IAM để xác thực yêu cầu của mình. Tên người dùng và mật khẩu tài khoản AWS được sử dụng để đăng nhập vào Bảng điều khiển quản lý AWS. Cặp khóa Amazon EC2 được dùng để kết nối với phiên bản EC2 của bạn bằng SSH. Khóa AWS Key Management Service (AWS KMS) được dùng để mã hóa và giải mã dữ liệu của bạn bằng SDK mã hóa AWS hoặc AWS CLI.', '[{"label": "A", "text_vi": "Tên người dùng và mật khẩu tài khoản AWS", "is_correct": false, "analysis_vi": "Sai. Tên người dùng và mật khẩu tài khoản AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khóa truy cập IAM và bí mật", "is_correct": true, "analysis_vi": "Đúng. Khóa truy cập IAM và bí mật là đáp án chính xác. Khóa truy cập IAM là thông tin xác thực dài hạn bao gồm ID khóa truy cập và khóa truy cập bí mật."}, {"label": "C", "text_vi": "Cặp khóa Amazon EC2", "is_correct": false, "analysis_vi": "Sai. Cặp khóa Amazon EC2: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Khóa Dịch vụ quản lý khóa AWS (AWS KMS)", "is_correct": false, "analysis_vi": "Sai. Khóa Dịch vụ quản lý khóa AWS (AWS KMS): AWS Key Management Service (KMS) giúp tạo, quản lý và kiểm soát các khóa mã hóa dùng để mã hóa dữ liệu trên các dịch vụ AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS KMS", "AWS IAM"]'::jsonb, NOW())
