INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-267', 'practice_283', 'Dịch vụ hoặc công cụ AWS nào đưa ra đề xuất để giúp người dùng có được các phiên bản Amazon EC2 được cấp phép dựa trên dữ liệu sử dụng khối lượng công việc trước đây?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Trình tối ưu hóa điện toán AWS là dịch vụ hoặc công cụ AWS cung cấp các đề xuất để giúp người dùng có được các phiên bản Amazon EC2 được cấp phép dựa trên dữ liệu sử dụng khối lượng công việc trước đây. Trình tối ưu hóa điện toán AWS phân tích cấu hình và đặc điểm hiệu năng của phiên bản EC2, đồng thời đưa ra đề xuất về loại, kích thước và cấu hình phiên bản tối ưu. Trình tối ưu hóa điện toán AWS giúp người dùng cải thiện hiệu suất, giảm chi phí và loại bỏ các tài nguyên không được sử dụng đúng mức', '[{"label": "A", "text_vi": "Công cụ tính giá AWS", "is_correct": false, "analysis_vi": "Sai. Công cụ tính giá AWS: AWS Pricing Calculator là công cụ ước tính chi phí trước khi triển khai kiến trúc trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Trình tối ưu hóa điện toán AWS", "is_correct": true, "analysis_vi": "Đúng. Trình tối ưu hóa điện toán AWS là đáp án chính xác. Trình tối ưu hóa điện toán AWS là dịch vụ hoặc công cụ AWS cung cấp các đề xuất để giúp người dùng có được các phiên bản Amazon EC2 được cấp phép dựa trên dữ liệu sử dụng khối lượng công việc trước đây."}, {"label": "C", "text_vi": "Trình chạy ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Trình chạy ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Trình quản lý hệ thống AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý hệ thống AWS: AWS Systems Manager cung cấp giao diện quản lý tập trung tài nguyên, tự động hóa tác vụ vận hành, quản lý bản vá (Patch Manager) và chạy lệnh (Run Command). Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "AWS Secrets Manager"]'::jsonb, NOW())
