  updated_at = NOW();

INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-268', 'practice_283', 'Dịch vụ AWS nào là dịch vụ lưu trữ dữ liệu trong bộ nhớ?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon ElastiCache là dịch vụ bộ nhớ đệm và lưu trữ dữ liệu trong bộ nhớ được quản lý toàn phần, mang lại thời gian phản hồi dưới một phần nghìn giây cho các ứng dụng. Bạn có thể sử dụng ElastiCache làm kho lưu trữ dữ liệu chính cho ứng dụng của mình hoặc làm bộ nhớ đệm để cải thiện hiệu suất của cơ sở dữ liệu hiện có. ElastiCache hỗ trợ hai công cụ trong bộ nhớ nguồn mở phổ biến: Redis và Memcached5.', '[{"label": "A", "text_vi": "Amazon cực quang", "is_correct": false, "analysis_vi": "Sai. Amazon cực quang: Amazon Aurora là cơ sở dữ liệu quan hệ tương thích MySQL/PostgreSQL hiệu năng cao gấp 3-5 lần, tự động sao chép 6 bản dữ liệu qua 3 AZ. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon RDS", "is_correct": false, "analysis_vi": "Sai. Amazon RDS: Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý (PostgreSQL, MySQL, MariaDB, Oracle, SQL Server), tự động sao lưu, vá lỗi và hỗ trợ Multi-AZ cho tính sẵn sàng cao. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Amazon DynamoDB", "is_correct": false, "analysis_vi": "Sai. Amazon DynamoDB: Amazon DynamoDB là cơ sở dữ liệu NoSQL (Key-Value và Document) serverless, cung cấp hiệu năng dưới 10 mili-giây ổn định ở mọi quy mô. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Amazon ElastiCache", "is_correct": true, "analysis_vi": "Đúng. Amazon ElastiCache là đáp án chính xác. Amazon ElastiCache là dịch vụ bộ nhớ đệm và lưu trữ dữ liệu trong bộ nhớ được quản lý toàn phần, mang lại thời gian phản hồi dưới một phần nghìn giây cho các ứng dụng."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon RDS", "Amazon Aurora", "Amazon DynamoDB"]'::jsonb, NOW())
