INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-269', 'practice_283', 'Sử dụng AWS Identity and Access Management (IAM) để chỉ cấp quyền truy cập vào các tài nguyên cần thiết để thực hiện một tác vụ là một khái niệm được gọi là:', 'Domain 2: Security and Compliance', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Khái niệm chỉ cấp quyền truy cập vào các tài nguyên cần thiết để thực hiện một tác vụ được gọi là quyền truy cập đặc quyền tối thiểu. Đây là phương pháp bảo mật tốt nhất trong IAM giúp giảm nguy cơ thực hiện các hành động trái phép hoặc độc hại. Bằng cách áp dụng quyền truy cập đặc quyền tối thiểu, bạn có thể giới hạn quyền của người dùng, nhóm và vai trò IAM của mình ở mức tối thiểu cần thiết cho các tác vụ cụ thể của họ. Bạn cũng có thể sử dụng các điều kiện, ranh giới quyền và Trình phân tích quyền truy cập IAM để hạn chế và xác minh thêm quyền truy cập.', '[{"label": "A", "text_vi": "quyền truy cập bị hạn chế.", "is_correct": false, "analysis_vi": "Sai. quyền truy cập bị hạn chế. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "truy cập khi cần thiết.", "is_correct": false, "analysis_vi": "Sai. truy cập khi cần thiết. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "quyền truy cập ít đặc quyền nhất.", "is_correct": true, "analysis_vi": "Đúng. quyền truy cập ít đặc quyền nhất. là đáp án chính xác. Khái niệm chỉ cấp quyền truy cập vào các tài nguyên cần thiết để thực hiện một tác vụ được gọi là quyền truy cập đặc quyền tối thiểu."}, {"label": "D", "text_vi": "truy cập mã thông báo.", "is_correct": false, "analysis_vi": "Sai. truy cập mã thông báo. không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS IAM"]'::jsonb, NOW())
