INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-270', 'practice_283', 'Dịch vụ hoặc tính năng AWS nào được sử dụng để gửi cả tin nhắn văn bản và email từ các ứng dụng được phân phối?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) là dịch vụ hoặc tính năng AWS được sử dụng để gửi cả tin nhắn văn bản và email từ các ứng dụng phân tán. Amazon SNS là dịch vụ nhắn tin pub/sub được quản lý toàn phần, cho phép người dùng gửi tin nhắn đến nhiều người đăng ký hoặc điểm cuối, chẳng hạn như địa chỉ email, số điện thoại, điểm cuối HTTP, chức năng AWS Lambda, v.v. Amazon SNS có thể được sử dụng để gửi thông báo, cảnh báo, xác nhận và lời nhắc từ ứng dụng tới người dùng hoặc ứng dụng khác4.', '[{"label": "A", "text_vi": "Dịch vụ thông báo đơn giản của Amazon (Amazon SNS)", "is_correct": true, "analysis_vi": "Đúng. Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) là đáp án chính xác. Dịch vụ thông báo đơn giản của Amazon (Amazon SNS) là dịch vụ hoặc tính năng AWS được sử dụng để gửi cả tin nhắn văn bản và email từ các ứng dụng phân tán."}, {"label": "B", "text_vi": "Dịch vụ email đơn giản của Amazon (Amazon SES)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ email đơn giản của Amazon (Amazon SES) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Cảnh báo của Amazon CloudWatch", "is_correct": false, "analysis_vi": "Sai. Cảnh báo của Amazon CloudWatch: Amazon CloudWatch là dịch vụ giám sát và quan sát tài nguyên, thu thập chỉ số (metrics), log và gửi cảnh báo (alarms) theo thời gian thực. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS)", "is_correct": false, "analysis_vi": "Sai. Dịch vụ xếp hàng đơn giản của Amazon (Amazon SQS) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon CloudWatch", "Amazon SNS", "Amazon SQS"]'::jsonb, NOW())
