INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-271', 'practice_283', 'Một công ty muốn sử dụng phiên bản Amazon EC2 để chạy quy trình không trạng thái và có thể khởi động lại sau giờ làm việc. Dịch vụ AWS nào cung cấp độ phân giải DNS?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'Amazon Route 53 là dịch vụ AWS cung cấp độ phân giải DNS. DNS (Domain Name System) là dịch vụ dịch tên miền thành địa chỉ IP. Amazon Route 53 là dịch vụ DNS đám mây có tính sẵn sàng cao và có khả năng mở rộng, cung cấp dịch vụ đăng ký tên miền, định tuyến DNS và kiểm tra tình trạng. Amazon Route 53 có thể định tuyến lưu lượng truy cập đến nhiều dịch vụ AWS khác nhau, chẳng hạn như Amazon EC2, Amazon S3 và Amazon CloudFront. Amazon Route 53 cũng có thể tích hợp với các dịch vụ AWS khác, chẳng hạn như AWS Certification Manager, AWS Shield và AWS WAF. Để biết thêm thông tin, hãy xem [Amazon Route 53 là gì?] và [Tính năng của Amazon Route 53]. Các bãi chứa AWS-Certified-Cloud-Practitioner hợp lệ được EduDump.com chia sẻ để giúp vượt qua kỳ thi dành cho người thực hành trên nền tảng đám mây được chứng nhận AWS! EduDump.com hiện cung cấp các kết xuất bài thi AWS- Certified-Cloud-Practitioner mới nhất, các câu hỏi thi EduDump.com AWS-Certified-Cloud-Practitioner đã được cập nhật và các câu trả lời đã được sửa. Hãy tải các kết xuất bài thi EduDump.com AWS-Certified-Cloud-Practitioner mới nhất với Test Engine tại đây: https://www.edudump.com/exams/Amazon/AWS-Certified-Cloud-Practitioner/premium/ ( 600 lượt hỏi đáp, GIẢM GIÁ 35% Mã giảm giá đặc biệt: freecram )', '[{"label": "A", "text_vi": "Amazon CloudFront", "is_correct": false, "analysis_vi": "Sai. Amazon CloudFront: Amazon CloudFront là dịch vụ mạng phân phối nội dung (CDN) toàn cầu với độ trễ thấp thông qua mạng lưới các Edge Location. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Amazon VPC", "is_correct": false, "analysis_vi": "Sai. Amazon VPC: Amazon VPC cho phép khởi tạo mạng ảo riêng biệt được cô lập logic trên đám mây AWS, kiểm soát toàn diện dải IP, subnet, bảng định tuyến và cổng mạng. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Tuyến đường Amazon 53", "is_correct": true, "analysis_vi": "Đúng. Tuyến đường Amazon 53 là đáp án chính xác. Amazon Route 53 là dịch vụ AWS cung cấp độ phân giải DNS."}, {"label": "D", "text_vi": "Kết nối trực tiếp AWS", "is_correct": false, "analysis_vi": "Sai. Kết nối trực tiếp AWS: AWS Direct Connect thiết lập kết nối mạng chuyên dụng riêng biệt từ hạ tầng on-premises tới AWS, bỏ qua mạng Internet công cộng để có băng thông ổn định. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon CloudFront", "Amazon Route 53", "Amazon VPC", "AWS Direct Connect"]'::jsonb, NOW())
