INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-272', 'practice_283', 'Một công ty có trang web được lưu trữ trên AWS nằm phía sau Cân bằng tải ứng dụng. Công ty muốn bảo vệ trang web khỏi việc tiêm SQL hoặc viết kịch bản chéo trang. Công ty nên sử dụng dịch vụ AWS nào?', 'Domain 2: Security and Compliance', 'An ninh & Phòng chống đe dọa (Security & Compliance)', 'Công ty nên sử dụng AWS WAF để bảo vệ trang web khỏi việc chèn SQL hoặc viết lệnh chéo trang. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web khỏi các hoạt động khai thác web phổ biến có thể ảnh hưởng đến tính khả dụng, xâm phạm bảo mật hoặc tiêu tốn quá nhiều tài nguyên. Công ty có thể sử dụng AWS WAF để tạo các quy tắc tùy chỉnh chặn các yêu cầu độc hại phù hợp với các mẫu nhất định, chẳng hạn như chèn SQL hoặc tạo tập lệnh chéo trang. AWS WAF có thể được áp dụng cho các ứng dụng web sử dụng Cân bằng tải ứng dụng, Amazon CloudFront hoặc Amazon API Gateway. Amazon GuardDuty, AWS Trusted Advisor và Amazon Inspector không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa nhằm giám sát hoạt động độc hại và hành vi trái phép trên các tài khoản và tài nguyên AWS. AWS Trusted Advisor là dịch vụ cung cấp các đề xuất biện pháp thực hành tốt nhất để tối ưu hóa chi phí, hiệu suất, bảo mật và khả năng chịu lỗi. Amazon Inspector là dịch vụ đánh giá tính bảo mật và tuân thủ của các ứng dụng chạy trên phiên bản Amazon EC212', '[{"label": "A", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, AWS Trusted Advisor và Amazon Inspector không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}, {"label": "B", "text_vi": "AWS WAF", "is_correct": true, "analysis_vi": "Đúng. AWS WAF là giải pháp đáp ứng yêu cầu. Công ty nên sử dụng AWS WAF để bảo vệ trang web khỏi việc chèn SQL hoặc viết lệnh chéo trang. AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS."}, {"label": "C", "text_vi": "AWS Trusted Advisor", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, AWS Trusted Advisor và Amazon Inspector không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}, {"label": "D", "text_vi": "Amazon Inspector", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, AWS Trusted Advisor và Amazon Inspector không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["AWS Trusted Advisor", "AWS WAF", "Amazon GuardDuty", "Amazon Inspector"]'::jsonb, NOW())
