INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-273', 'practice_283', 'Một công ty đang lưu trữ ứng dụng web trên phiên bản Amazon EC2. Công ty muốn triển khai các điều kiện tùy chỉnh để lọc và kiểm soát lưu lượng truy cập web vào. Dịch vụ AWS nào sẽ đáp ứng những yêu cầu này?', 'Domain 2: Security and Compliance', 'Dịch vụ điện toán đám mây Amazon EC2', 'Dịch vụ AWS sẽ đáp ứng các yêu cầu của công ty đang lưu trữ ứng dụng web trên phiên bản Amazon EC2 và muốn triển khai các điều kiện tùy chỉnh để lọc và kiểm soát lưu lượng truy cập web gửi đến là AWS WAF. AWS WAF là tường lửa ứng dụng web giúp bảo vệ các ứng dụng web khỏi các hoạt động khai thác web phổ biến có thể ảnh hưởng đến tính khả dụng, xâm phạm bảo mật hoặc tiêu tốn quá nhiều tài nguyên. Công ty có thể sử dụng AWS WAF để tạo các quy tắc tùy chỉnh chặn các yêu cầu độc hại phù hợp với các mẫu nhất định, chẳng hạn như chèn SQL hoặc tạo tập lệnh chéo trang. AWS WAF có thể được áp dụng cho các ứng dụng web sử dụng Cân bằng tải ứng dụng, Amazon CloudFront hoặc Amazon API Gateway. Amazon GuardDuty, Amazon Macie và AWS Shield không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này. Amazon GuardDuty là dịch vụ phát hiện mối đe dọa nhằm giám sát hoạt động độc hại và hành vi trái phép trên các tài khoản và tài nguyên AWS. Amazon Macie là dịch vụ bảo mật dữ liệu và quyền riêng tư dữ liệu sử dụng máy học và khớp mẫu để khám phá, phân loại và bảo vệ dữ liệu nhạy cảm được lưu trữ trong Amazon S3. AWS Shield là dịch vụ bảo vệ từ chối dịch vụ (DDoS) phân tán được quản lý nhằm bảo vệ các ứng dụng web chạy trên AWS. Các dịch vụ này hữu ích hơn trong việc phát hiện và ngăn chặn các loại mối đe dọa và tấn công khác nhau thay vì lọc và kiểm soát lưu lượng truy cập web gửi đến dựa trên các điều kiện tùy chỉnh.', '[{"label": "A", "text_vi": "Nhiệm vụ bảo vệ của Amazon", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, Amazon Macie và AWS Shield không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}, {"label": "B", "text_vi": "AWSWAF", "is_correct": true, "analysis_vi": "Đúng. AWSWAF là giải pháp đáp ứng yêu cầu. Dịch vụ AWS sẽ đáp ứng các yêu cầu của công ty đang lưu trữ ứng dụng web trên phiên bản Amazon EC2 và muốn triển khai các điều kiện tùy chỉnh để lọc và kiểm soát lưu lượng truy cập web gửi đến là AWS WAF. AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS."}, {"label": "C", "text_vi": "Amazon Macie", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, Amazon Macie và AWS Shield không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}, {"label": "D", "text_vi": "Khiên AWS", "is_correct": false, "analysis_vi": "Sai. Amazon GuardDuty, Amazon Macie và AWS Shield không phải là những dịch vụ tốt nhất để sử dụng cho mục đích này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon EC2", "AWS Shield", "AWS WAF", "Amazon GuardDuty", "Amazon Macie"]'::jsonb, NOW())
