INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-274', 'practice_283', 'Người dùng AWS mới có ít kinh nghiệm về đám mây muốn xây dựng ứng dụng bằng cách sử dụng dịch vụ AWS. Người dùng muốn tìm hiểu cách triển khai các dịch vụ AWS cụ thể từ các ví dụ của khách hàng khác. Người dùng cũng muốn đặt câu hỏi cho các chuyên gia AWS. Dịch vụ hoặc tài nguyên AWS nào sẽ đáp ứng các yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'Tọa đàm công nghệ trực tuyến AWS là các bài thuyết trình trực tuyến đề cập đến nhiều chủ đề ở các cấp độ kỹ thuật khác nhau và cung cấp phiên hỏi đáp trực tiếp với các chuyên gia AWS. Chúng là nguồn tài nguyên tuyệt vời dành cho những người dùng AWS mới muốn tìm hiểu cách triển khai các dịch vụ AWS cụ thể từ các ví dụ của khách hàng khác và đặt câu hỏi cho các chuyên gia AWS. Tài liệu AWS, AWS Marketplace và AWS Health Dashboard không cung cấp mức độ tương tác và hướng dẫn giống như Hội thảo công nghệ trực tuyến AWS. Nguồn: Tọa đàm công nghệ trực tuyến AWS', '[{"label": "A", "text_vi": "Tọa đàm công nghệ trực tuyến AWS", "is_correct": true, "analysis_vi": "Đúng. Tọa đàm công nghệ trực tuyến AWS là đáp án chính xác. Tọa đàm công nghệ trực tuyến AWS là các bài thuyết trình trực tuyến đề cập đến nhiều chủ đề ở các cấp độ kỹ thuật khác nhau và cung cấp phiên hỏi đáp trực tiếp với các chuyên gia AWS."}, {"label": "B", "text_vi": "Tài liệu AWS", "is_correct": false, "analysis_vi": "Sai. Tài liệu AWS, AWS Marketplace và AWS Health Dashboard không cung cấp mức độ tương tác và hướng dẫn giống như Hội thảo công nghệ trực tuyến AWS."}, {"label": "C", "text_vi": "Thị trường AWS", "is_correct": false, "analysis_vi": "Sai. Tài liệu AWS, AWS Marketplace và AWS Health Dashboard không cung cấp mức độ tương tác và hướng dẫn giống như Hội thảo công nghệ trực tuyến AWS."}, {"label": "D", "text_vi": "Bảng thông tin tình trạng AWS", "is_correct": false, "analysis_vi": "Sai. Tài liệu AWS, AWS Marketplace và AWS Health Dashboard không cung cấp mức độ tương tác và hướng dẫn giống như Hội thảo công nghệ trực tuyến AWS."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
