INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-275', 'practice_283', 'Trụ cột nào của Khung kiến trúc tối ưu AWS tập trung vào lợi tức đầu tư khi chuyển sang Đám mây AWS?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Tối ưu hóa chi phí là trụ cột của Khung kiến trúc tối ưu AWS tập trung vào lợi tức đầu tư khi chuyển sang Đám mây AWS. Tối ưu hóa chi phí có nghĩa là người dùng có thể đạt được kết quả kinh doanh mong muốn ở mức giá thấp nhất có thể trong khi vẫn duy trì hiệu suất và độ tin cậy cao. Có thể đạt được tối ưu hóa chi phí bằng cách sử dụng nhiều tính năng và biện pháp thực hành tốt nhất của AWS, chẳng hạn như định giá theo mức sử dụng, định cỡ phù hợp, độ linh hoạt, phiên bản dự trữ, phiên bản giao ngay, thẻ phân bổ chi phí, báo cáo chi phí và mức sử dụng cũng như AWS Trusted Advisor. [Khuôn khổ có kiến trúc tốt của AWS] Người thực hành đám mây được chứng nhận AWS - aws.amazon.com', '[{"label": "A", "text_vi": "Tính bền vững", "is_correct": false, "analysis_vi": "Sai. Tính bền vững không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Tối ưu hóa chi phí", "is_correct": true, "analysis_vi": "Đúng. Tối ưu hóa chi phí đáp ứng đầy đủ yêu cầu của đề bài. Tối ưu hóa chi phí là trụ cột của Khung kiến trúc tối ưu AWS tập trung vào lợi tức đầu tư khi chuyển sang Đám mây AWS."}, {"label": "C", "text_vi": "Hoạt động xuất sắc", "is_correct": false, "analysis_vi": "Sai. Hoạt động xuất sắc không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Độ tin cậy", "is_correct": false, "analysis_vi": "Sai. Độ tin cậy không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
