INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-276', 'practice_283', 'Một công ty đang xây dựng một ứng dụng sẽ nhận được hàng triệu truy vấn cơ sở dữ liệu mỗi giây. Công ty cần kho lưu trữ dữ liệu để ứng dụng có thể mở rộng quy mô nhằm đáp ứng những nhu cầu này. Dịch vụ AWS nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Giải pháp cơ sở dữ liệu trên AWS', 'Amazon DynamoDB là dịch vụ AWS sẽ đáp ứng yêu cầu xây dựng một ứng dụng có thể nhận được hàng triệu truy vấn cơ sở dữ liệu mỗi giây. Amazon DynamoDB là dịch vụ cơ sở dữ liệu NoSQL được quản lý toàn phần, cung cấp hiệu năng, khả năng mở rộng và độ bền nhanh và nhất quán. Amazon DynamoDB có thể xử lý mọi mức lưu lượng yêu cầu và tự động tăng hoặc giảm công suất dựa trên nhu cầu. Amazon DynamoDB cũng hỗ trợ bộ nhớ đệm trong bộ nhớ với Amazon DynamoDB Accelerator (DAX) để cải thiện thời gian phản hồi và giảm chi phí. Để biết thêm thông tin, hãy xem Amazon DynamoDB là gì? và các tính năng của Amazon DynamoDB.', '[{"label": "A", "text_vi": "Amazon DynamoDB", "is_correct": true, "analysis_vi": "Đúng. Amazon DynamoDB là đáp án chính xác. Amazon DynamoDB là dịch vụ AWS sẽ đáp ứng yêu cầu xây dựng một ứng dụng có thể nhận được hàng triệu truy vấn cơ sở dữ liệu mỗi giây."}, {"label": "B", "text_vi": "AWS Cloud9", "is_correct": false, "analysis_vi": "Sai. AWS Cloud9 không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Amazon ElastiCache dành cho Memcached", "is_correct": false, "analysis_vi": "Sai. Amazon ElastiCache dành cho Memcached: Amazon ElastiCache là dịch vụ bộ nhớ đệm in-memory (Redis hoặc Memcached) giúp tăng tốc độ truy xuất dữ liệu với độ trễ dưới 1 mili-giây. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "D", "text_vi": "Sao Hải Vương Amazon", "is_correct": false, "analysis_vi": "Sai. Sao Hải Vương Amazon không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["S3 là Object Storage với 11 số 9 độ bền (99.999999999%). Muốn lưu trữ rẻ nhất cho dữ liệu lâu dài hiếm khi truy cập: S3 Glacier Deep Archive."]'::jsonb, '[{"term": "lưu trữ đối tượng", "points_to": "Amazon S3"}]'::jsonb, '["Amazon DynamoDB"]'::jsonb, NOW())
