INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-277', 'practice_283', 'Mô hình định giá nào sẽ làm gián đoạn phiên bản Amazon EC2 đang chạy nếu tạm thời không có dung lượng?', 'Domain 4: Billing, Pricing and Support', 'Dịch vụ điện toán đám mây Amazon EC2', 'Phiên bản dùng ngay là một loại phiên bản EC2 cho phép bạn đặt giá thầu trên công suất điện toán chưa sử dụng, được AWS cung cấp với mức chiết khấu lên tới 90% so với giá Theo yêu cầu1. Phiên bản Spot phù hợp với các ứng dụng có khả năng chịu lỗi, không trạng thái hoặc linh hoạt có thể xử lý tình trạng gián đoạn2. Phiên bản Spot có thể bị gián đoạn với cảnh báo hai phút khi EC2 cần khôi phục dung lượng3. Các tùy chọn khác không phải là mô hình định giá sẽ làm gián đoạn phiên bản EC2 đang chạy nếu tạm thời không có dung lượng', '[{"label": "A", "text_vi": "Phiên bản theo yêu cầu", "is_correct": false, "analysis_vi": "Sai. Phiên bản theo yêu cầu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Phiên bản dự trữ tiêu chuẩn", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ tiêu chuẩn không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Phiên bản Spot", "is_correct": true, "analysis_vi": "Đúng. Phiên bản Spot là đáp án chính xác. Phiên bản dùng ngay là một loại phiên bản EC2 cho phép bạn đặt giá thầu trên công suất điện toán chưa sử dụng, được AWS cung cấp với mức chiết khấu lên tới 90% so với giá Theo yêu cầu1."}, {"label": "D", "text_vi": "Phiên bản dự trữ có thể chuyển đổi", "is_correct": false, "analysis_vi": "Sai. Phiên bản dự trữ có thể chuyển đổi không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2"]'::jsonb, NOW())
