INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-278', 'practice_283', 'Một công ty có cơ sở dữ liệu MySQL chạy trên một phiên bản Amazon EC2. Công ty hiện yêu cầu tính sẵn sàng cao hơn trong trường hợp mất điện. Nhóm nhiệm vụ nào sẽ đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Dịch vụ điện toán đám mây Amazon EC2', 'Nhóm tác vụ đáp ứng yêu cầu về độ sẵn sàng cao hơn cho cơ sở dữ liệu MySQL chạy trên một phiên bản Amazon EC2 duy nhất là di chuyển sang Amazon RDS và kích hoạt Multi-AZ. Amazon RDS là dịch vụ cơ sở dữ liệu quan hệ được quản lý toàn phần, hỗ trợ MySQL và các công cụ cơ sở dữ liệu phổ biến khác. Bằng cách bật Multi-AZ, người dùng có thể có cơ sở dữ liệu chính trong một Availability Zone (AZ) và bản sao dự phòng đồng bộ trong một Availability Zone (AZ) khác. Trong trường hợp cơ sở dữ liệu chính bị ngừng hoạt động theo kế hoạch hoặc ngoài kế hoạch, Amazon RDS sẽ tự động chuyển sang bản sao dự phòng với mức gián đoạn tối thiểu3. Việc thêm Cân bằng tải ứng dụng trước phiên bản EC2, đặt cấu hình Tự động khôi phục EC2 để di chuyển phiên bản sang Availability Zone (AZ) khác hoặc bật tính năng bảo vệ chấm dứt cho phiên bản EC2 sẽ không mang lại độ khả dụng cao hơn cho cơ sở dữ liệu vì chúng không giải quyết được một điểm lỗi hoặc vấn đề sao chép dữ liệu.', '[{"label": "A", "text_vi": "Thêm Cân bằng tải ứng dụng trước phiên bản EC2.", "is_correct": false, "analysis_vi": "Sai. Thêm Cân bằng tải ứng dụng trước phiên bản EC2.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Định cấu hình EC2 Auto Recovery để di chuyển phiên bản sang Availability Zone (AZ) khác.", "is_correct": false, "analysis_vi": "Sai. Định cấu hình EC2 Auto Recovery để di chuyển phiên bản sang Availability Zone (AZ) khác.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Di chuyển sang Amazon RDS và bật Multi-AZ.", "is_correct": true, "analysis_vi": "Đúng. Di chuyển sang Amazon RDS và bật Multi-AZ. là đáp án chính xác. Nhóm tác vụ đáp ứng yêu cầu về độ sẵn sàng cao hơn cho cơ sở dữ liệu MySQL chạy trên một phiên bản Amazon EC2 duy nhất là di chuyển sang Amazon RDS và kích hoạt Multi-AZ."}, {"label": "D", "text_vi": "Kích hoạt tính năng bảo vệ chấm dứt cho phiên bản EC2 để tránh ngừng hoạt động.", "is_correct": false, "analysis_vi": "Sai. Kích hoạt tính năng bảo vệ chấm dứt cho phiên bản EC2 để tránh ngừng hoạt động.: Amazon EC2 cung cấp máy chủ ảo có thể cấu hình linh hoạt (vCPU, RAM, OS), phù hợp cho khối lượng công việc đa dạng nhưng yêu cầu khách hàng tự quản lý hệ điều hành và cập nhật bảo mật. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["Amazon EC2", "Amazon RDS"]'::jsonb, NOW())
