INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-279', 'practice_283', 'Amazon Rekognition mang lại lợi ích gì?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Amazon Rekognition là dịch vụ cung cấp khả năng phân tích hình ảnh và video dựa trên deep learning. Một trong những lợi ích của Amazon Rekognition là khả năng phát hiện các đối tượng xuất hiện trong ảnh, chẳng hạn như khuôn mặt, cột mốc, động vật, văn bản và cảnh. Điều này có thể cho phép các ứng dụng thực hiện các tác vụ như nhận dạng khuôn mặt, xác minh khuôn mặt, so sánh khuôn mặt, tìm kiếm khuôn mặt, nhận dạng người nổi tiếng, phát hiện cảm xúc, ước tính độ tuổi, nhận dạng giới tính, phân tích khuôn mặt, nhận dạng nét mặt, v.v. Tổng quan về Amazon RekognitionNgười thực hành đám mây được chứng nhận của AWS - aws.amazon.com', '[{"label": "A", "text_vi": "Khả năng đặt hình mờ trên hình ảnh", "is_correct": false, "analysis_vi": "Sai. Khả năng đặt hình mờ trên hình ảnh không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Khả năng phát hiện vật thể xuất hiện trong ảnh", "is_correct": true, "analysis_vi": "Đúng. Khả năng phát hiện vật thể xuất hiện trong ảnh là đáp án chính xác. Amazon Rekognition là dịch vụ cung cấp khả năng phân tích hình ảnh và video dựa trên deep learning."}, {"label": "C", "text_vi": "Khả năng tự động thay đổi kích thước hàng triệu hình ảnh", "is_correct": false, "analysis_vi": "Sai. Khả năng tự động thay đổi kích thước hàng triệu hình ảnh không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Khả năng đấu thầu các công việc phát hiện đối tượng", "is_correct": false, "analysis_vi": "Sai. Khả năng đấu thầu các công việc phát hiện đối tượng không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
