INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-280', 'practice_283', 'Nguyên tắc nào sau đây là nguyên tắc thiết kế Khung kiến trúc tối ưu của AWS để vận hành xuất sắc trên Đám mây AWS?', 'Domain 1: Cloud Concepts', 'Khung kiến trúc tối ưu AWS (Well-Architected Framework)', 'Thực hiện các thay đổi thường xuyên, nhỏ và có thể đảo ngược là một trong những nguyên tắc thiết kế để vận hành xuất sắc trên Đám mây AWS, như được xác định trong Khung kiến trúc tối ưu AWS. Nguyên tắc này có nghĩa là bạn nên thiết kế khối lượng công việc của mình để cho phép thực hiện các thay đổi nhanh chóng và an toàn, chẳng hạn như triển khai các bản cập nhật, khôi phục lỗi và thử nghiệm các tính năng mới. Bằng cách thực hiện những thay đổi nhỏ và có thể đảo ngược, bạn có thể giảm nguy cơ xảy ra lỗi, giảm thiểu tác động của lỗi và tăng tốc độ khôi phục2.', '[{"label": "A", "text_vi": "Vươn ra toàn cầu trong vài phút", "is_correct": false, "analysis_vi": "Sai. Vươn ra toàn cầu trong vài phút không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "B", "text_vi": "Thực hiện những thay đổi nhỏ, thường xuyên và có thể đảo ngược", "is_correct": true, "analysis_vi": "Đúng. Thực hiện những thay đổi nhỏ, thường xuyên và có thể đảo ngược là đáp án chính xác. Thực hiện các thay đổi thường xuyên, nhỏ và có thể đảo ngược là một trong những nguyên tắc thiết kế để vận hành xuất sắc trên Đám mây AWS, như được xác định trong Khung kiến trúc tối ưu AWS."}, {"label": "C", "text_vi": "Triển khai nền tảng vững chắc về quản lý danh tính và quyền truy cập", "is_correct": false, "analysis_vi": "Sai. Triển khai nền tảng vững chắc về quản lý danh tính và quyền truy cập không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "D", "text_vi": "Ngừng chi tiền vào cơ sở hạ tầng phần cứng cho hoạt động của trung tâm dữ liệu", "is_correct": false, "analysis_vi": "Sai. Ngừng chi tiền vào cơ sở hạ tầng phần cứng cho hoạt động của trung tâm dữ liệu không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
