INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-281', 'practice_283', 'Dịch vụ AWS nào được triển khai cho VPC và cung cấp khả năng bảo vệ khỏi các mối đe dọa mạng phổ biến?', 'Domain 3: Cloud Technology and Services', 'Hạ tầng mạng & Phân phối nội dung (VPC & Networking)', 'Tường lửa mạng AWS là một dịch vụ được quản lý giúp dễ dàng triển khai các biện pháp bảo vệ mạng cần thiết cho tất cả Đám mây riêng ảo Amazon (VPC) của bạn. Dịch vụ có thể được thiết lập chỉ bằng vài cú nhấp chuột từ bảng điều khiển AWS hoặc sử dụng API. Tường lửa mạng AWS tự động điều chỉnh quy mô theo lưu lượng mạng của bạn, do đó bạn không phải lo lắng về việc triển khai và quản lý bất kỳ cơ sở hạ tầng nào. Tường lửa mạng AWS cung cấp khả năng bảo vệ khỏi các mối đe dọa mạng phổ biến như chèn SQL, tập lệnh chéo trang và tấn công DDoS1.', '[{"label": "A", "text_vi": "AWSShield", "is_correct": false, "analysis_vi": "Sai. AWSShield: AWS Shield là dịch vụ phòng chống tấn công từ chối dịch vụ phân tán (DDoS), bản Standard miễn phí tích hợp sẵn và bản Advanced hỗ trợ phản ứng 24/7 từ đội SRT. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "AWSWAF", "is_correct": false, "analysis_vi": "Sai. AWSWAF: AWS WAF là tường lửa ứng dụng web hoạt động ở tầng 7 (HTTP/S), bảo vệ chống lại các lỗ hổng web phổ biến như SQL Injection và XSS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Tường lửa mạng AWS", "is_correct": true, "analysis_vi": "Đúng. Tường lửa mạng AWS là đáp án chính xác. Tường lửa mạng AWS là một dịch vụ được quản lý giúp dễ dàng triển khai các biện pháp bảo vệ mạng cần thiết cho tất cả Đám mây riêng ảo Amazon (VPC) của bạn."}, {"label": "D", "text_vi": "Trình quản lý tường lửa AWS", "is_correct": false, "analysis_vi": "Sai. Trình quản lý tường lửa AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Shield", "AWS WAF", "AWS Secrets Manager", "Amazon VPC"]'::jsonb, NOW())
