INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-282', 'practice_283', 'Công ty nên sử dụng giải pháp AWS nào để đáp ứng yêu cầu này?', 'Domain 3: Cloud Technology and Services', 'Cloud Technology and Services', 'Danh mục dịch vụ AWS là dịch vụ cho phép bạn tạo và quản lý danh mục dịch vụ CNTT được phê duyệt để sử dụng trên AWS. Bạn có thể sử dụng Danh mục dịch vụ AWS để quản lý tập trung các dịch vụ CNTT được triển khai phổ biến và giúp tổ chức của bạn đạt được khả năng quản trị nhất quán cũng như đáp ứng các yêu cầu tuân thủ, đồng thời cho phép người dùng chỉ triển khai nhanh chóng các dịch vụ CNTT được phê duyệt mà họ cần1. AWS Config là dịch vụ cho phép bạn đánh giá, kiểm tra và đánh giá cấu hình tài nguyên AWS của mình. Bộ công cụ phát triển phần mềm (SDK) AWS là các công cụ cho phép bạn dễ dàng tích hợp ứng dụng của mình với các dịch vụ AWS bằng ngôn ngữ lập trình ưa thích của bạn. AWS AppSync là dịch vụ đơn giản hóa việc phát triển ứng dụng bằng cách cho phép bạn tạo API linh hoạt để truy cập, thao tác và kết hợp dữ liệu từ một hoặc nhiều nguồn dữ liệu một cách an toàn. Không có dịch vụ nào trong số này có thể giúp bạn hạn chế quyền truy cập AWS của nhân viên vào danh mục tài nguyên AWS được xác định trước.', '[{"label": "A", "text_vi": "Cấu hình AWS", "is_correct": false, "analysis_vi": "Sai. Cấu hình AWS: AWS Config liên tục ghi lại và đánh giá các thay đổi cấu hình tài nguyên so với các quy tắc tuân thủ mong muốn. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Bộ công cụ phát triển phần mềm AWS (SDK)", "is_correct": false, "analysis_vi": "Sai. Bộ công cụ phát triển phần mềm AWS (SDK) không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}, {"label": "C", "text_vi": "Danh mục dịch vụ AWS", "is_correct": true, "analysis_vi": "Đúng. Danh mục dịch vụ AWS là đáp án chính xác. Danh mục dịch vụ AWS là dịch vụ cho phép bạn tạo và quản lý danh mục dịch vụ CNTT được phê duyệt để sử dụng trên AWS."}, {"label": "D", "text_vi": "Đồng bộ hóa ứng dụng AWS", "is_correct": false, "analysis_vi": "Sai. Đồng bộ hóa ứng dụng AWS không phải là giải pháp phù hợp hoặc không đáp ứng các tiêu chuẩn kỹ thuật/nghiệp vụ được đặt ra trong câu hỏi này."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '[]'::jsonb, NOW())
