INSERT INTO public.question_explanations (question_id, exam_id, question_vi, domain, topic, explanation_vi, options, tips, keywords, related_services, updated_at)
VALUES ('practice-283-283', 'practice_283', 'Dịch vụ hoặc công cụ AWS nào giúp người dùng hình dung, hiểu và quản lý chi tiêu cũng như mức sử dụng theo thời gian?', 'Domain 4: Billing, Pricing and Support', 'Quản lý danh tính & Kiểm soát truy cập (AWS IAM)', 'AWS Cost Explorer là dịch vụ hoặc công cụ AWS giúp người dùng hình dung, hiểu và quản lý chi tiêu cũng như mức sử dụng theo thời gian. AWS Cost Explorer là giao diện dựa trên web cho phép người dùng truy cập vào các biểu đồ và bảng tương tác hiển thị chi phí và dữ liệu sử dụng AWS của họ. Người dùng có thể tạo báo cáo tùy chỉnh để phân tích dữ liệu chi phí và mức sử dụng theo nhiều thứ nguyên khác nhau, chẳng hạn như dịch vụ, khu vực, tài khoản, thẻ, v.v. Người dùng cũng có thể xem dữ liệu lịch sử trong tối đa 12 tháng qua, dự báo chi phí trong tương lai trong tối đa 12 tháng tới và nhận đề xuất để tối ưu hóa chi phí. AWS Cost Explorer cũng cung cấp các chế độ xem được cấu hình sẵn để hiển thị các tình huống sử dụng và chi phí phổ biến, chẳng hạn như chi tiêu hàng tháng theo dịch vụ, chi tiêu hàng ngày theo tài khoản được liên kết và mức sử dụng Phiên bản dự trữ. Người dùng có thể sử dụng AWS Cost Explorer để theo dõi xu hướng sử dụng và chi tiêu AWS của mình, xác định các yếu tố thúc đẩy chi phí và các điểm bất thường, đồng thời tối ưu hóa việc phân bổ tài nguyên và lập kế hoạch ngân sách.', '[{"label": "A", "text_vi": "AWS Organizations", "is_correct": false, "analysis_vi": "Sai. AWS Organizations: AWS Organizations giúp quản lý tập trung nhiều tài khoản AWS, hỗ trợ xuất hóa đơn hợp nhất (Consolidated Billing) và áp dụng chính sách SCP. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "B", "text_vi": "Công cụ tính giá AWS", "is_correct": false, "analysis_vi": "Sai. Công cụ tính giá AWS: AWS Pricing Calculator là công cụ ước tính chi phí trước khi triển khai kiến trúc trên AWS. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}, {"label": "C", "text_vi": "Trình AWS Cost Explorer AWS", "is_correct": true, "analysis_vi": "Đúng. Trình AWS Cost Explorer AWS là đáp án chính xác. AWS Cost Explorer là dịch vụ hoặc công cụ AWS giúp người dùng hình dung, hiểu và quản lý chi tiêu cũng như mức sử dụng theo thời gian."}, {"label": "D", "text_vi": "Danh mục dịch vụ AWS", "is_correct": false, "analysis_vi": "Sai. Danh mục dịch vụ AWS: AWS Service Catalog cho phép tổ chức tạo và quản lý các danh mục dịch vụ CNTT đã được phê duyệt sẵn để người dùng tự triển khai. Do đó không phù hợp với yêu cầu cụ thể của câu hỏi."}]'::jsonb, '["Đọc kỹ từ khóa trong câu hỏi (như ''least operational overhead'', ''most cost-effective'', ''serverless'') để loại trừ các phương án đòi hỏi quản trị máy chủ.", "Sử dụng phương pháp loại trừ: Các dịch vụ có tiền tố Amazon/AWS thường có chức năng chuyên biệt, không chọn dịch vụ hạ tầng cho tác vụ phân tích kinh doanh."]'::jsonb, '[{"term": "tối ưu & tự động hóa", "points_to": "Dịch vụ Managed / Serverless"}]'::jsonb, '["AWS Cost Explorer", "AWS Organizations"]'::jsonb, NOW())
